\end{proof}

\begin{lemma}[Properties composition]
\label{morphisms-lemma-properties-composition}
\source{stacks:01SZ}
\href{https://stacks.math.columbia.edu/tag/01SZ}{\texttt{Stacks tag 01SZ}}
\group{morphisms}

The following properties of ring maps are stable under composition.
\begin{enumerate}
