\end{proof}

\begin{lemma}[Ubiquity nagata]
\label{morphisms-lemma-ubiquity-nagata}
\source{stacks:035B}
\href{https://stacks.math.columbia.edu/tag/035B}{\texttt{Stacks tag 035B}}
\group{morphisms}

The following types of schemes are Nagata.
\begin{enumerate}
\item Any scheme locally of finite type over a field.
\item Any scheme locally of finite type over a Noetherian complete local ring.
\item Any scheme locally of finite type over $\mathbf{Z}$.
\item Any scheme locally of finite type over a Dedekind ring of
characteristic zero.
\item And so on.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-finite-type-nagata}

By Lemma \ref{morphisms-lemma-finite-type-nagata} we only need to show that
