\begin{lemma}[Base change module flat]
\label{morphisms-lemma-base-change-module-flat}
\source{stacks:01U8}
\href{https://stacks.math.columbia.edu/tag/01U8}{\texttt{Stacks tag 01U8}}
\group{morphisms}

Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent sheaf of $\mathcal{O}_X$-modules.
Let $g : S' \to S$ be a morphism of schemes.
