\begin{lemma}[Base change flat]
\label{morphisms-lemma-base-change-flat}
\source{stacks:01U9}
\href{https://stacks.math.columbia.edu/tag/01U9}{\texttt{Stacks tag 01U9}}
\group{morphisms}

