\begin{lemma}[Differential product]
\label{morphisms-lemma-differential-product}
\source{stacks:01V1}
\href{https://stacks.math.columbia.edu/tag/01V1}{\texttt{Stacks tag 01V1}}
\group{morphisms}

\uses{morphisms-lemma-functoriality-differentials}
Let $f : X \to S$ and $g : Y \to S$ be morphisms of schemes with the same
target. Let $p : X \times_S Y \to X$ and $q : X \times_S Y \to Y$ be the
projection morphisms. The maps from
Lemma \ref{morphisms-lemma-functoriality-differentials}
$$
p^*\Omega_{X/S} \oplus q^*\Omega_{Y/S}
\longrightarrow
\Omega_{X \times_S Y/S}
$$
give an isomorphism.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-base-change-differentials, morphisms-lemma-triangle-differentials}

