\begin{lemma}[Differentials relative immersion]
\label{morphisms-lemma-differentials-relative-immersion}
\source{stacks:01UZ}
\href{https://stacks.math.columbia.edu/tag/01UZ}{\texttt{Stacks tag 01UZ}}
\group{morphisms}

\uses{morphisms-lemma-functoriality-differentials}
Let $i : Z \to X$ be an immersion of schemes over $S$.
There is a canonical exact sequence
$$
\mathcal{C}_{Z/X} \to i^*\Omega_{X/S} \to \Omega_{Z/S} \to 0
$$
where the first arrow is induced by $\text{d}_{X/S}$
and the second arrow comes from Lemma \ref{morphisms-lemma-functoriality-differentials}.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-i-star-equivalence}

This is the sheafified version of
Algebra, Lemma \ref{algebra-lemma-differential-seq}. However
we should make sure we can define the first arrow globally.
Hence we explain the meaning of ``induced by $\text{d}_{X/S}$'' here.
Namely, we may assume that $i$ is a closed immersion by
shrinking $X$. Let $\mathcal{I} \subset \mathcal{O}_X$
be the sheaf of ideals corresponding to $Z \subset X$.
Then $\text{d}_{X/S} : \mathcal{I} \to \Omega_{X/S}$
maps the subsheaf $\mathcal{I}^2 \subset \mathcal{I}$ to
$\mathcal{I}\Omega_{X/S}$. Hence it induces a map
$\mathcal{I}/\mathcal{I}^2 \to \Omega_{X/S}/\mathcal{I}\Omega_{X/S}$
which is $\mathcal{O}_X/\mathcal{I}$-linear.
By Lemma \ref{morphisms-lemma-i-star-equivalence} this corresponds to a map
$\mathcal{C}_{Z/X} \to i^*\Omega_{X/S}$ as desired.
\end{proof}

\begin{lemma}[Differentials relative immersion section]
\label{morphisms-lemma-differentials-relative-immersion-section}
\source{stacks:0474}
\href{https://stacks.math.columbia.edu/tag/0474}{\texttt{Stacks tag 0474}}
\group{morphisms}

\uses{morphisms-lemma-differentials-relative-immersion}
Let $i : Z \to X$ be an immersion of schemes over $S$, and
assume $i$ (locally) has a left inverse. Then the canonical
sequence
$$
0 \to \mathcal{C}_{Z/X} \to i^*\Omega_{X/S} \to \Omega_{Z/S} \to 0
$$
of
Lemma \ref{morphisms-lemma-differentials-relative-immersion}
is (locally) split exact. In particular, if $s : S \to X$ is a section
of the structure morphism $X \to S$ then the map
$\mathcal{C}_{S/X} \to s^*\Omega_{X/S}$ induced by
$\text{d}_{X/S}$ is an isomorphism.
\end{lemma}

\begin{proof}
It follows from Algebra, Lemma \ref{algebra-lemma-differential-seq-split}
that the result holds when $X, Z, S$ are affine. In general we conclude
the sequence is locally split exact. If $g : X \to Z$ is a left inverse
of $i$, then $i^*c_g$ is a right inverse of the map
$i^*\Omega_{X/S} \to \Omega_{Z/S}$ by
Modules, Lemma \ref{modules-lemma-check-functoriality-differentials}.
This implies the sequence is split by
Homology, Lemma \ref{homology-lemma-ses-split}.
Finally, if $s$ is a section, then it is an immersion $s : Z = S \to X$
over $S$ (see Schemes, Lemma \ref{schemes-lemma-section-immersion})
and in that case $\Omega_{Z/S} = 0$.
\end{proof}

\begin{remark}[Differentials diagonal]
\label{morphisms-remark-differentials-diagonal}
\source{stacks:060N}
\href{https://stacks.math.columbia.edu/tag/060N}{\texttt{Stacks tag 060N}}
\group{morphisms}

\uses{morphisms-lemma-differential-product, morphisms-lemma-differentials-relative-immersion-section, morphisms-lemma-differentials-diagonal}
Let $X \to S$ be a morphism of schemes. According to
Lemma \ref{morphisms-lemma-differential-product}
we have
$$
\Omega_{X \times_S X/S} =
\text{pr}_1^*\Omega_{X/S} \oplus \text{pr}_2^*\Omega_{X/S}
$$
On the other hand, the diagonal morphism $\Delta : X \to X \times_S X$
is an immersion, which locally has a left inverse. Hence by
Lemma \ref{morphisms-lemma-differentials-relative-immersion-section}
we obtain a canonical short exact sequence
$$
0 \to \mathcal{C}_{X/X \times_S X} \to \Omega_{X/S} \oplus \Omega_{X/S}
\to \Omega_{X/S} \to 0
$$
Note that the right arrow is $(1, 1)$ which is indeed a split surjection.
On the other hand, by Lemma \ref{morphisms-lemma-differentials-diagonal}
we have an identification $\Omega_{X/S} = \mathcal{C}_{X/X \times_S X}$.
Because we chose $\text{d}_{X/S}(f) = s_2(f) - s_1(f)$ in this
identification it turns out that the left arrow is the map
$(-1, 1)$\footnote{Namely,
the local section $\text{d}_{X/S}(f) = 1 \otimes f - f \otimes 1$ of the
ideal sheaf of $\Delta$ maps via $\text{d}_{X \times_S X/X}$ to the
local section
$1 \otimes 1 \otimes 1 \otimes f - 1 \otimes f \otimes 1 \otimes 1
-1 \otimes 1 \otimes f \otimes 1 + f \otimes 1 \otimes 1 \otimes 1 =
\text{pr}_2^*\text{d}_{X/S}(f) - \text{pr}_1^*\text{d}_{X/S}(f)$.}.
\end{remark}

\begin{lemma}[Two immersions]
\label{morphisms-lemma-two-immersions}
\source{stacks:067L}
\href{https://stacks.math.columbia.edu/tag/067L}{\texttt{Stacks tag 067L}}
\group{morphisms}

\uses{morphisms-lemma-conormal-functorial, morphisms-lemma-differentials-relative-immersion}
Let
$$
\begin{array}{cc}Z \underset{i}{\longrightarrow}\underset{j}{\searrow} & X \downarrow \\  & Y\end{array}
$$
be a commutative diagram of schemes where $i$ and $j$ are immersions.
Then there is a canonical exact sequence
$$
\mathcal{C}_{Z/Y} \to
\mathcal{C}_{Z/X} \to
i^*\Omega_{X/Y} \to 0
$$
where the first arrow comes from
Lemma \ref{morphisms-lemma-conormal-functorial}
and the second from
Lemma \ref{morphisms-lemma-differentials-relative-immersion}.
\end{lemma}

\begin{proof}
The algebraic version of this is
Algebra, Lemma \ref{algebra-lemma-application-NL}.
\end{proof}

\section{Finite order differential operators}
\label{morphisms-section-differential-operators}
We suggest the reader take a look at the corresponding section
in the chapter on commutative algebra
(Algebra, Section \ref{algebra-section-differential-operators})
and the corresponding section in the chapter on sheaves of modules
(Modules, Section \ref{modules-section-differential-operators}).

\begin{lemma}[Affine case differential operators]
\label{morphisms-lemma-affine-case-differential-operators}
\source{stacks:0G44}
\href{https://stacks.math.columbia.edu/tag/0G44}{\texttt{Stacks tag 0G44}}
\group{morphisms}

Let $R \to A$ be a ring map. Denote $f : X \to S$ the corresponding
morphism of affine schemes. Let $\mathcal{F}$ and $\mathcal{G}$
be $\mathcal{O}_X$-modules. If $\mathcal{F}$ is quasi-coherent then
the map
$$
\text{Diff}^k_{X/S}(\mathcal{F}, \mathcal{G}) \to
\text{Diff}^k_{A/R}(\Gamma(X, \mathcal{F}), \Gamma(X, \mathcal{G}))
$$
sending a differential operator to its action on global sections
is bijective.
\end{lemma}

\begin{proof}
Write $\mathcal{F} = \widetilde{M}$ for some $A$-module $M$. Set
$N = \Gamma(X, \mathcal{G})$. Let $D : M \to N$ be a differential
operator of order $k$. We have to show there exists
a unique differential operator $\mathcal{F} \to \mathcal{G}$ of order $k$
which gives rise to $D$ on global sections. Let $U = D(f) \subset X$
be a standard affine open. Then $\mathcal{F}(U) = M_f$ is the localization.
By Algebra, Lemma \ref{algebra-lemma-invert-system-differential-operators}
the differential operator $D$ extends to a unique differential operator
$$
D_f : \mathcal{F}(U) = \widetilde{M}(U) = M_f \to N_f = \widetilde{N}(U)
$$
The uniqueness shows that these maps $D_f$ glue to give a map of sheaves
$\widetilde{M} \to \widetilde{N}$ on the basis of all standard opens
of $X$. Hence we get a unique map of sheaves
$\widetilde{D} : \widetilde{M} \to \widetilde{N}$ agreeing with these maps
by the material in Sheaves, Section \ref{sheaves-section-bases}.
Since $\widetilde{D}$ is given by differential operators of order $k$ on
the standard opens, we find that $\widetilde{D}$ is a differential operator
of order $k$ (small detail omitted).
Finally, we can post-compose with the canonical $\mathcal{O}_X$-module map
$c : \widetilde{N} \to \mathcal{G}$
(Schemes, Lemma \ref{schemes-lemma-compare-constructions})
to get $c \circ \widetilde{D} : \mathcal{F} \to \mathcal{G}$
which is a differential operator of order $k$ by
Modules, Lemma \ref{modules-lemma-composition-differential-operators}.
This proves existence. We omit the proof of uniqueness.
\end{proof}

\begin{lemma}[Base change differential operators]
\label{morphisms-lemma-base-change-differential-operators}
\source{stacks:0G45}
\href{https://stacks.math.columbia.edu/tag/0G45}{\texttt{Stacks tag 0G45}}
\group{morphisms}

Let $a : X \to S$ and $b : Y \to S$ be morphisms of schemes.
Let $\mathcal{F}$ and $\mathcal{F}'$ be quasi-coherent $\mathcal{O}_X$-modules.
Let $D : \mathcal{F} \to \mathcal{F}'$ be a differential operator
of order $k$ on $X/S$. Let $\mathcal{G}$ be a quasi-coherent
$\mathcal{O}_Y$-module. Then there is a unique differential
operator
$$
D' :
\text{pr}_1^*\mathcal{F} \otimes_{\mathcal{O}_{X \times_S Y}}
\text{pr}_2^*\mathcal{G}
\longrightarrow
\text{pr}_1^*\mathcal{F}' \otimes_{\mathcal{O}_{X \times_S Y}}
\text{pr}_2^*\mathcal{G}
$$
of order $k$ on $X \times_S Y / Y$ such that
$
D'(s \otimes t) = D(s) \otimes t
$
for local sections $s$ of $\mathcal{F}$ and $t$ of $\mathcal{G}$.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-affine-case-differential-operators}

In case $X$, $Y$, and $S$ are affine, this follows, via
Lemma \ref{morphisms-lemma-affine-case-differential-operators},
from the corresponding algebra result, see
Algebra, Lemma \ref{algebra-lemma-base-change-differential-operators}.
In general, one uses coverings by affines
(for example as in Schemes, Lemma
\ref{schemes-lemma-affine-covering-fibre-product})
to construct $D'$ globally. Details omitted.
\end{proof}

\begin{remark}[Base change differential operators]
\label{morphisms-remark-base-change-differential-operators}
\source{stacks:0G46}
\href{https://stacks.math.columbia.edu/tag/0G46}{\texttt{Stacks tag 0G46}}
\group{morphisms}

\uses{morphisms-lemma-base-change-differential-operators}
Let $a : X \to S$ and $b : Y \to S$ be morphisms of schemes.
Denote $p : X \times_S Y \to X$ and $q : X \times_S Y \to Y$ the
projections. In this remark, given an $\mathcal{O}_X$-module $\mathcal{F}$
and an $\mathcal{O}_Y$-module $\mathcal{G}$ let us set
$$
\mathcal{F} \boxtimes \mathcal{G} =
p^*\mathcal{F} \otimes_{\mathcal{O}_{X \times_S Y}} q^*\mathcal{G}
$$
Denote $\mathcal{A}_{X/S}$ the additive category
whose objects are quasi-coherent $\mathcal{O}_X$-modules and
whose morphisms are differential operators of finite order on $X/S$.
Similarly for $\mathcal{A}_{Y/S}$ and $\mathcal{A}_{X \times_S Y/S}$.
The construction of Lemma \ref{morphisms-lemma-base-change-differential-operators}
determines a functor
$$
\boxtimes :
\mathcal{A}_{X/S} \times \mathcal{A}_{Y/S} \longrightarrow
\mathcal{A}_{X \times_S Y/S},
\quad
(\mathcal{F}, \mathcal{G}) \longmapsto \mathcal{F} \boxtimes \mathcal{G}
$$
which is bilinear on morphisms. If $X = \Spec(A)$, $Y = \Spec(B)$, and
$S = \Spec(R)$, then via the identification of quasi-coherent sheaves
with modules this functor is given by $(M, N) \mapsto M \otimes_R N$
on objects and sends the morphism $(D, D') : (M, N) \to (M', N')$ to
$D \otimes D' : M \otimes_R N \to M' \otimes_R N'$.
\end{remark}

\section{Smooth morphisms}
\label{morphisms-section-smooth}
Let $f : X \to Y$ be a continuous map of topological spaces.
Consider the following condition:
For every $x \in X$ there exist open neighbourhoods
$x \in U \subset X$ and $f(x) \in V \subset Y$, and an integer $d$
such that $f(U) \subset V$ and such that we obtain
a commutative diagram
$$
\begin{array}{ccc}X \downarrow & U \longleftarrow\downarrow\underset{\pi}{\longrightarrow} & V \times \mathbf{R}^d \swarrow \\ Y & V \longleftarrow & \end{array}
$$
where $\pi$ is a homeomorphism onto an open subset.
Smooth morphisms of schemes are the analogue of these maps
in the category of schemes. See
Lemma \ref{morphisms-lemma-smooth-locally-standard-smooth}
and
Lemma \ref{morphisms-lemma-smooth-etale-over-affine-space}.

\medskip\noindent
Contrary to expectations (perhaps) the notion
of a smooth ring map is not defined solely in terms
of the module of differentials. Namely, recall that
$R \to A$ is a {\it smooth ring map} if $A$ is of finite presentation over $R$
and if the naive cotangent complex of $A$ over $R$ is quasi-isomorphic
to a projective module placed in degree $0$, see
Algebra, Definition \ref{algebra-definition-smooth}.

\begin{definition}[Smooth]
\label{morphisms-definition-smooth}
\source{stacks:01V5}
\href{https://stacks.math.columbia.edu/tag/01V5}{\texttt{Stacks tag 01V5}}
\group{morphisms}

Let $f : X \to S$ be a morphism of schemes.
\begin{enumerate}
\item We say that $f$ is {\it smooth at $x \in X$} if
there exist an affine open neighbourhood $\Spec(A) = U \subset X$
of $x$ and affine open $\Spec(R) = V \subset S$
with $f(U) \subset V$ such that the induced ring map
$R \to A$ is smooth.
\item We say that $f$ is {\it smooth} if it is smooth at every point of $X$.
\item A morphism of affine schemes $f : X \to S$
is called {\it standard smooth} if there exists a standard smooth ring
map $R \to R[x_1, \ldots, x_n]/(f_1, \ldots, f_c)$ (see
Algebra, Definition \ref{algebra-definition-standard-smooth})
such that $X \to S$ is isomorphic to
$$
\Spec(R[x_1, \ldots, x_n]/(f_1, \ldots, f_c)) \to \Spec(R).
$$
\end{enumerate}
\end{definition}

A pleasing feature of this definition is that the set of points
where a morphism is smooth is automatically open.

\medskip\noindent
Note that there is no separation or quasi-compactness hypotheses in the
definition. Hence the question of being smooth is local in nature on
the source. Here is the precise result.

\begin{lemma}[Smooth characterize]
\label{morphisms-lemma-smooth-characterize}
\source{stacks:01V6}
\href{https://stacks.math.columbia.edu/tag/01V6}{\texttt{Stacks tag 01V6}}
\group{morphisms}

Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item The morphism $f$ is smooth.
\item For every affine opens $U \subset X$, $V \subset S$
with $f(U) \subset V$ the ring map
$\mathcal{O}_S(V) \to \mathcal{O}_X(U)$ is smooth.
\item There exists an open covering $S = \bigcup_{j \in J} V_j$
and open coverings $f^{-1}(V_j) = \bigcup_{i \in I_j} U_i$ such
that each of the morphisms $U_i \to V_j$, $j\in J, i\in I_j$
is smooth.
\item There exists an affine open covering $S = \bigcup_{j \in J} V_j$
and affine open coverings $f^{-1}(V_j) = \bigcup_{i \in I_j} U_i$ such
that the ring map $\mathcal{O}_S(V_j) \to \mathcal{O}_X(U_i)$ is
smooth, for all $j\in J, i\in I_j$.
\end{enumerate}
Moreover, if $f$ is smooth then for
any open subschemes $U \subset X$, $V \subset S$ with $f(U) \subset V$
the restriction $f|_U : U \to V$ is smooth.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-locally-P, morphisms-definition-property-local}

This follows from Lemma \ref{morphisms-lemma-locally-P} if we show that
the property ``$R \to A$ is smooth'' is local.
We check conditions (a), (b) and (c) of Definition
\ref{morphisms-definition-property-local}.
By Algebra, Lemma \ref{algebra-lemma-base-change-smooth}
being smooth is stable under base change and hence
we conclude (a) holds. By
Algebra, Lemma \ref{algebra-lemma-compose-smooth}
being smooth is stable under composition and for any ring
$R$ the ring map $R \to R_f$ is (standard) smooth.
We conclude (b) holds. Finally, property (c) is true
according to Algebra, Lemma \ref{algebra-lemma-locally-smooth}.
\end{proof}

The following lemma characterizes a smooth morphism as a
flat, finitely presented morphism with smooth fibres.
Note that schemes smooth over a field are discussed in more detail in
Varieties, Section \ref{varieties-section-smooth}.

\begin{lemma}[Smooth flat smooth fibres]
\label{morphisms-lemma-smooth-flat-smooth-fibres}
