\label{morphisms-lemma-base-change-etale}
\source{stacks:02GO}
\href{https://stacks.math.columbia.edu/tag/02GO}{\texttt{Stacks tag 02GO}}
\group{morphisms}

The base change of a morphism which is \'etale is \'etale.
\end{lemma}

