\begin{lemma}[Description of the \'etale schemes over fields and fibres of \'etale morphisms.]
\label{morphisms-lemma-etale-over-field}
\source{stacks:02GL}
\href{https://stacks.math.columbia.edu/tag/02GL}{\texttt{Stacks tag 02GL}}
\group{morphisms}


Fibres of \'etale morphisms.
\begin{enumerate}
\item Let $X$ be a scheme over a field $k$.
The structure morphism $X \to \Spec(k)$ is \'etale if
and only if $X$ is a disjoint union of spectra of finite separable
field extensions of $k$.
\item If $f : X \to S$ is an \'etale morphism, then for every $s \in S$ the
fibre $X_s$ is a disjoint union of spectra of finite separable field
extensions of $\kappa(s)$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-unramified-over-field, morphisms-lemma-etale-smooth-unramified, morphisms-lemma-algebraic-residue-field-extension-closed-point-fibre}

You can deduce this from Lemma \ref{morphisms-lemma-unramified-over-field}
via Lemma \ref{morphisms-lemma-etale-smooth-unramified} above.
Here is a direct proof.

\medskip\noindent
We will use Algebra, Lemma \ref{algebra-lemma-etale-over-field}.
Hence it is clear that if $X$ is a disjoint union of spectra of finite
separable field extensions of $k$ then $X \to \Spec(k)$ is \'etale.
Conversely, suppose that $X \to \Spec(k)$ is \'etale. Then for any affine
open $U \subset X$ we see that $U$ is a finite disjoint union of spectra
of finite separable field extensions of $k$. Hence all points of $X$
are closed points (see
Lemma \ref{morphisms-lemma-algebraic-residue-field-extension-closed-point-fibre}
for example). Thus $X$ is a discrete space and we win.
\end{proof}

The following lemma characterizes an \'etale morphism as a
flat, finitely presented morphism with ``\'etale fibres''.

\begin{lemma}[Etale flat etale fibres]
\label{morphisms-lemma-etale-flat-etale-fibres}
\source{stacks:02GM}
\href{https://stacks.math.columbia.edu/tag/02GM}{\texttt{Stacks tag 02GM}}
\group{morphisms}

Let $f : X \to S$ be a morphism of schemes.
If $f$ is flat, locally of finite presentation, and for every $s \in S$
the fibre $X_s$ is a disjoint union of spectra of finite separable
field extensions of $\kappa(s)$, then $f$ is \'etale.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-etale-over-field, morphisms-lemma-smooth-flat-smooth-fibres, morphisms-lemma-unramified-etale-fibres, morphisms-lemma-etale-smooth-unramified}

You can deduce this from
Algebra, Lemma \ref{algebra-lemma-characterize-etale}.
Here is another proof.

\medskip\noindent
By Lemma \ref{morphisms-lemma-etale-over-field} a fibre $X_s$ is \'etale
and hence smooth over $s$. By Lemma \ref{morphisms-lemma-smooth-flat-smooth-fibres}
we see that $X \to S$ is smooth.
By Lemma \ref{morphisms-lemma-unramified-etale-fibres}
we see that $f$ is unramified. We conclude by
Lemma \ref{morphisms-lemma-etale-smooth-unramified}.
\end{proof}

