\end{lemma}

\begin{proof}
\uses{morphisms-lemma-characterize-relatively-ample}

Immediate from Lemma \ref{morphisms-lemma-characterize-relatively-ample}
and the definitions.
\end{proof}

\begin{lemma}[Quasi affine O ample]
\label{morphisms-lemma-quasi-affine-O-ample}
\source{stacks:0891}
\href{https://stacks.math.columbia.edu/tag/0891}{\texttt{Stacks tag 0891}}
\group{morphisms}

