\begin{lemma}[Relative seminormalization]
\label{morphisms-lemma-relative-seminormalization}
\source{stacks:0H3N}
\href{https://stacks.math.columbia.edu/tag/0H3N}{\texttt{Stacks tag 0H3N}}
\group{morphisms}

Let $f : Y \to X$ be a quasi-compact, quasi-separated, and dominant
morphism of schemes.
\begin{enumerate}
\item The category of factorizations $Y \to X' \to X$ where $X' \to X$
is a universal homeomorphism has an initial object $Y \to X^{Y/wn} \to X$.
\item The category of factorizations $Y \to X' \to X$ where $X' \to X$
is a universal homeomorphism inducing isomorphisms on residue fields
has an initial object $Y \to X^{Y/sn} \to X$.
\end{enumerate}
Moreover, formation of the factorization $Y \to X^{Y/wn} \to X$ and
$Y \to X^{Y/sn} \to X$ commutes with base change to open subschemes of $X$.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-universal-homeomorphism, morphisms-definition-normalization-X-in-Y, morphisms-lemma-characterize-normalization, morphisms-lemma-relative-weak-normalization-algebra, morphisms-lemma-relative-weak-normalization-localization}

We will prove (1) and omit the proof of (2); also the final assertion
will follow from the construction of the factorization. We will use
Lemma \ref{morphisms-lemma-universal-homeomorphism} without
further mention. First, let $Y \to X^{Y/n} \to X$ be the normalization
of $X$ in $Y$, see Definition \ref{morphisms-definition-normalization-X-in-Y}.
For $Y \to X' \to X$ as in (1), we obtain a unique morphism
$X^{Y/n} \to X'$ compatible with the given morphisms, see
Lemma \ref{morphisms-lemma-characterize-normalization}. Thus it suffices
to prove the lemma with $f$ replaced by $X^{Y/n} \to X$. This reduces
us to the case studied in the next paragraph.

\medskip\noindent
Assume $f$ is integral (the rest of the proof works more generally if
$f$ is affine). Let $U = \Spec(A)$ be an affine open of $X$ and let
$V = f^{-1}(U) = \Spec(B)$ be the inverse image in $Y$.
Then $A \to B$ is a ring map which induces a dominant morphism
on spectra. By Lemma \ref{morphisms-lemma-relative-weak-normalization-algebra}
we obtain an $A$-subalgebra $B' \subset B$ such that setting
$U^{V/wn} = \Spec(B')$ the factorization $V \to U^{V/wn} \to U$
is initial in the category of factorizations $V \to U' \to U$ where
$U' \to U$ is a universal homeomorphism.

\medskip\noindent
If $U_1 \subset U_2 \subset X$ are affine opens, then setting
$V_i = f^{-1}(U_i)$ we obtain a canonical morphism
$$
\rho_{U_1}^{U_2} : U_1^{V_1/wn} \to U_1 \times_{U_2} U_2^{V_2/wn}
$$
over $U_1$ by the universal property of $U_1^{V_1/wn}$. These morphisms satisfy
a natural functoriality which we leave to the reader to formulate and prove.
Furthermore, the morphism $\rho_{U_1}^{U_2}$
is an isomorphism; this follows from
Lemma \ref{morphisms-lemma-relative-weak-normalization-localization}
provided that $U_1 \subset U_2$ is a standard open
and in the general case can be reduced to this case
by the functorial nature of these maps and
Schemes, Lemma \ref{schemes-lemma-standard-open-two-affines}
(details omitted). Thus by relative glueing
(Constructions, Lemma \ref{constructions-lemma-relative-glueing})
we obtain a morphism $X^{Y/wn} \to X$ which restricts
to $U^{V/wn} \to U$ over $U$ compatibly with the $\rho_{U_1}^{U_2}$.
Of course, the morphisms $V \to U^{V/wn}$ glue to a morphism $Y \to X^{Y/wn}$
(see Constructions, Remark
\ref{constructions-remark-relative-glueing-functorial})
and we get our factorization $Y \to X^{Y/wn} \to X$ where the second morphism
is a universal homeomorphism.

\medskip\noindent
Finally, let $Y \to X' \to X$ be a factorization as in (1).
With $V \to U^{V/wn} \to U \subset X$ as above,
we obtain a factorization $V \to U \times_X X' \to U$ where
the second arrow is a universal homeomorphism
and we obtain a unique morphism $g_U : U^{V/wn} \to U \times_X X'$ over $U$
by the universal property of $U^{V/wn}$.
These $g_U$ are compatible with the morphisms $\rho_{U_1}^{U_2}$; details
omitted. Hence there is a unique morphism $g : X^{Y/wn} \to X'$
over $X$ agreeing with $g_U$ over $U$, see
Constructions, Remark \ref{constructions-remark-relative-glueing-functorial}.
This proves that $Y \to X^{Y/wn} \to X$ is initial in our category
and the proof is complete.
\end{proof}

\begin{definition}[Relative seminormalization]
\label{morphisms-definition-relative-seminormalization}
\source{stacks:0H3P}
\href{https://stacks.math.columbia.edu/tag/0H3P}{\texttt{Stacks tag 0H3P}}
\group{morphisms}

\uses{morphisms-lemma-relative-seminormalization}
Let $f : Y \to X$ be a quasi-compact, quasi-separated, and dominant
morphism of schemes.
\begin{enumerate}
\item The factorization $Y \to X^{Y/sn} \to X$ constructed in
Lemma \ref{morphisms-lemma-relative-seminormalization} part (2)
is the {\it seminormalization of $X$ in $Y$}.
\item The factorization $Y \to X^{Y/wn} \to X$ constructed in
Lemma \ref{morphisms-lemma-relative-seminormalization} part (1)
is the {\it weak normalization of $X$ in $Y$}.
\end{enumerate}
\end{definition}

Here is a way to reinterpret the seminormalization of a scheme
which locally has finitely many irreducible components.

\begin{lemma}[Seminormal and normalization]
\label{morphisms-lemma-seminormal-and-normalization}
\source{stacks:0H3Q}
\href{https://stacks.math.columbia.edu/tag/0H3Q}{\texttt{Stacks tag 0H3Q}}
\group{morphisms}

Let $X$ be a scheme such that every quasi-compact open has
finitely many irreducible components. Let $\nu : X^\nu \to X$
be the normalization of $X$. Then the seminormalization of $X$ in
$X^\nu$ is is the seminormalization of $X$. In a formula:
$X^{sn} = X^{X^\nu/sn}$.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-characterize-normalization}

Let $f : Y \to X$ be as in (\ref{equation-generic-points})
so that $X^\nu$ is the normalization of $X$ in $Y$.
The seminormalization $X^{sn} \to X$ of $X$ is the initial object in the
category of universal homeomorphisms $X' \to X$ inducing isomorphisms on
residue fields. Since $Y$ is the disjoint union of the spectra of the
residue fields at the generic points of irreducible components of $X$,
we see that for any $X' \to X$ in this category we obtain a canonical
lift $f' : Y \to X'$ of $f$. Then by
Lemma \ref{morphisms-lemma-characterize-normalization}
we obtain a canonical morphism $X^\nu \to X'$.
Whence in turn a canonical morphism $X^{X^\nu/sn} \to X'$
by the universal property of $X^{X^\nu/sn}$.
In this way we see that $X^{X^\nu/sn}$ satisfies the
same universal property that $X^{sn}$ has and we conclude.
\end{proof}

Lemma \ref{morphisms-lemma-seminormal-and-normalization} motivates the
following definition. Since we have only constructed the
normalization in case $X$ locally has finitely many irreducible components,
we will also restrict ourselves to that case for the weak normalization.

\begin{definition}[Weak normalization]
\label{morphisms-definition-weak-normalization}
\source{stacks:0H3R}
\href{https://stacks.math.columbia.edu/tag/0H3R}{\texttt{Stacks tag 0H3R}}
\group{morphisms}

\uses{morphisms-definition-normalization}
Let $X$ be a scheme such that every quasi-compact open has
finitely many irreducible components. We define the
{\it weak normalization} of $X$ as the weak normalization
$$
X^\nu \longrightarrow X^{wn} \longrightarrow X
$$
of $X$ in the normalization $X^\nu$ of $X$
(Definition \ref{morphisms-definition-normalization}).
In a formula: $X^{wn} = X^{X^\nu/wn}$.
\end{definition}

Combined with Lemma \ref{morphisms-lemma-seminormal-and-normalization} we see that
for a scheme $X$ which locally has finitely many irreducible components
there are canonical morphisms
$$
X^\nu \to X^{wn} \to X^{sn} \to X
$$
Having made this definition, we can say what it means for a scheme
to be weakly normal (provided it has locally finitely many irreducible
components).

\begin{definition}[Weakly normal]
\label{morphisms-definition-weakly-normal}
\source{stacks:0H3S}
\href{https://stacks.math.columbia.edu/tag/0H3S}{\texttt{Stacks tag 0H3S}}
\group{morphisms}

\uses{morphisms-definition-weak-normalization}
Let $X$ be a scheme such that every quasi-compact open has
finitely many irreducible components. We say $X$ is {\it weakly normal}
if the weak normalization $X^{wn} \to X$ is an isomorphism
(Definition \ref{morphisms-definition-weak-normalization}).
\end{definition}

It follows immediately from the definitions that for a scheme $X$ such
that every quasi-compact open has finitely many irreducible components
we have
$$
X\text{ normal} \Rightarrow
X\text{ weakly normal} \Rightarrow
X\text{ seminormal}
$$
We can work out the meaning of weak normality in the affine case as follows.

\begin{lemma}[Affine weakly normal]
\label{morphisms-lemma-affine-weakly-normal}
\source{stacks:0H3T}
\href{https://stacks.math.columbia.edu/tag/0H3T}{\texttt{Stacks tag 0H3T}}
\group{morphisms}

\uses{morphisms-definition-seminormal-ring}
Let $X = \Spec(A)$ be an affine scheme which has finitely many
irreducible components. Then $X$ is weakly normal if and only if
\begin{enumerate}
\item $A$ is seminormal (Definition \ref{morphisms-definition-seminormal-ring}),
\item for a prime number $p$ and $z, w \in A$ such that
(a) $z$ is a nonzerodivisor, (b) $w^p$ is divisible by $z^p$, and
(c) $pw$ is divisible by $z$, then $w$ is divisible by $z$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-description-normalization, morphisms-lemma-relative-weak-normalization-algebra}

Assume $X$ is weakly normal. Since a weakly normal scheme is seminormal,
we see that (1) holds (by our definition of weakly normal schemes).
In particular $A$ is reduced. Let $p, z, w$ be as in (2).
Choose $x, y \in A$ such that $z^p x = w^p$ and $zy = pw$.
Then $p^p x = y^p$. The ring map
$A \to C = A[t]/(t^p - x, pt - y)$ induces a universal homeomorphism
on spectra. The normalization $X^\nu$ of $X$
is the spectrum of the integral closure $A'$
of $A$ in the total ring of fractions of $A$, see
Lemma \ref{morphisms-lemma-description-normalization}.
Note that $a = w/z \in A'$ because $a^p = x$.
Hence we have an $A$-algebra homomorphism $A \to C \to A'$
sending $t$ to $a$.
At this point the defining property $X = X^{wn} = X^{X^\nu/wn}$
of being weakly normal tells us that $C \to A'$ maps into $A$.
Thus we find $a \in A$ as desired.

\medskip\noindent
Conversely, assume (1) and (2). Let $A'$ be as in the previous paragraph.
We have to show that $X^{X^\nu/wn} = X$. By construction in the proof
of Lemma \ref{morphisms-lemma-relative-weak-normalization-algebra}, the scheme
$X^{X^\nu/wn}$ is the spectrum of the subring of $A'$
which is the union of the subrings $A[a_1, \ldots, a_n] \subset A'$
such that for $i = 1, \ldots, n$ we have
\begin{enumerate}
\item[(a)] $a_i^2, a_i^3 \in A[a_1, \ldots, a_{i - 1}]$, or
\item[(b)] there exists a prime number $p$ with
$pa_i, a_i^p \in A[a_1, \ldots, a_{i - 1}]$.
\end{enumerate}
Then we can use (1) and (2) to inductively see that $a_1, \ldots, a_n \in A$;
we omit the details. Consequently, we have $X = X^{X^\nu/wn}$ and hence
$X$ is weakly normal.
\end{proof}

Here is the obligatory lemma.

\begin{lemma}[Locally weakly normal]
\label{morphisms-lemma-locally-weakly-normal}
\source{stacks:0H3U}
\href{https://stacks.math.columbia.edu/tag/0H3U}{\texttt{Stacks tag 0H3U}}
\group{morphisms}

\uses{morphisms-lemma-affine-weakly-normal}
Let $X$ be a scheme such that every quasi-compact open has
finitely many irreducible components. The following are equivalent:
\begin{enumerate}
\item The scheme $X$ is weakly normal.
\item For every affine open $U \subset X$ the ring $\mathcal{O}_X(U)$
satisfies conditions (1) and (2) of Lemma \ref{morphisms-lemma-affine-weakly-normal}.
\item There exists an affine open covering $X = \bigcup U_i$ such that
each ring $\mathcal{O}_X(U_i)$
satisfies conditions (1) and (2) of Lemma \ref{morphisms-lemma-affine-weakly-normal}.
\item There exists an open covering $X = \bigcup X_j$
such that each open subscheme $X_j$ is weakly normal.
\end{enumerate}
Moreover, if $X$ is weakly normal then every open subscheme is weakly normal.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-relative-seminormalization}

The condition to $X$ be weakly normal is that the morphism
$X^{wn} = X^{X^\nu/wn} \to X$ is an isomorphism. Since the construction
of $X^\nu \to X$ commutes with base change to open subschemes
and since the construction of $X^{X^\nu/wn}$ commutes with base
change to open subschemes of $X$ (Lemma \ref{morphisms-lemma-relative-seminormalization})
the lemma is clear.
\end{proof}

\section{Zariski's Main Theorem (algebraic version)}
\label{morphisms-section-Zariski}
This is the version you can prove using purely algebraic methods.
Before we can prove more powerful versions (for non-affine morphisms)
we need to develop more tools. See Cohomology of Schemes, Section
\ref{coherent-section-applications-formal-functions}
and
More on Morphisms, Section
\ref{more-morphisms-section-application-etale-neighbourhoods}.

\begin{theorem}[Algebraic version of Zariski's Main Theorem]

\label{morphisms-theorem-main-theorem}
\source{stacks:03GT}
\href{https://stacks.math.columbia.edu/tag/03GT}{\texttt{Stacks tag 03GT}}
\group{morphisms}

Let $f : Y \to X$ be an affine morphism of schemes.
Assume $f$ is of finite type.
Let $X'$ be the normalization of $X$ in $Y$. Picture:
$$
\begin{array}{ccc}Y \underset{f}{\searrow}\underset{f'}{\longrightarrow} &  & X' \overset{\nu}{\swarrow} \\  & X & \end{array}
$$
Then there exists an open subscheme $U' \subset X'$ such that
\begin{enumerate}
\item $(f')^{-1}(U') \to U'$ is an isomorphism, and
\item $(f')^{-1}(U') \subset Y$ is the set of points at which
$f$ is quasi-finite.
\end{enumerate}
\end{theorem}

\begin{proof}
\uses{morphisms-definition-integral-closure, morphisms-definition-normalization-X-in-Y, morphisms-lemma-integral-fibres, morphisms-lemma-quasi-finite-at-point-characterize}

There is an immediate reduction to the case where $X$ and hence $Y$
are affine. Say $X = \Spec(R)$ and $Y = \Spec(A)$.
Then $X' = \Spec(A')$, where $A'$ is the integral closure of
$R$ in $A$, see Definitions \ref{morphisms-definition-integral-closure}
and \ref{morphisms-definition-normalization-X-in-Y}. By
Algebra, Theorem \ref{algebra-theorem-main-theorem}
for every $y \in Y$ at which $f$ is quasi-finite, there exists an
open $U'_y \subset X'$ such that $(f')^{-1}(U'_y) \to U'_y$
is an isomorphism. Set $U' = \bigcup U'_y$ where $y \in Y$ ranges
over all points where $f$ is quasi-finite. It remains to show that
$f$ is quasi-finite at all points of $(f')^{-1}(U')$.
If $y \in (f')^{-1}(U')$ with image $x \in X$, then we see that
$Y_x \to X'_x$ is an isomorphism in a neighbourhood of $y$. Hence
there is no point of $Y_x$ which specializes to $y$, since this
is true for $f'(y)$ in $X'_x$, see Lemma \ref{morphisms-lemma-integral-fibres}.
By Lemma \ref{morphisms-lemma-quasi-finite-at-point-characterize} part (3)
this implies $f$ is quasi-finite at $y$.
\end{proof}

We can use the algebraic version of Zariski's Main Theorem to show that
the set of points where a morphism is quasi-finite is open.

\begin{lemma}[The locally quasi-finite locus of a morphism is open]
\label{morphisms-lemma-quasi-finite-points-open}
\source{stacks:01TI}
\href{https://stacks.math.columbia.edu/tag/01TI}{\texttt{Stacks tag 01TI}}
\group{morphisms}


Let $f : X \to S$ be a morphism of schemes.
The set of points of $X$ where $f$ is quasi-finite is an open
$U \subset X$. The induced morphism $U \to S$ is locally quasi-finite.
\end{lemma}

\begin{proof}
\uses{morphisms-definition-quasi-finite, morphisms-theorem-main-theorem}

Suppose $f$ is quasi-finite at $x$.
Let $x \in U = \Spec(A) \subset X$, $V = \Spec(R) \subset S$
be affine opens as in Definition \ref{morphisms-definition-quasi-finite}.
By either Theorem \ref{morphisms-theorem-main-theorem} above or
Algebra, Lemma \ref{algebra-lemma-quasi-finite-open},
the set of primes $\mathfrak q$ at which $R \to A$ is quasi-finite
is open in $\Spec(A)$. Since these all correspond to points
of $X$ where $f$ is quasi-finite we get the first statement.
The second statement is obvious.
\end{proof}

We will improve the following lemma to general quasi-finite separated
morphisms later, see
More on Morphisms, Lemma
\ref{more-morphisms-lemma-quasi-finite-separated-pass-through-finite}.

\begin{lemma}[Quasi finite affine]
\label{morphisms-lemma-quasi-finite-affine}
\source{stacks:03GU}
\href{https://stacks.math.columbia.edu/tag/03GU}{\texttt{Stacks tag 03GU}}
\group{morphisms}

Let $f : Y \to X$ be a morphism of schemes.
Assume
\begin{enumerate}
\item $X$ and $Y$ are affine, and
\item $f$ is quasi-finite.
\end{enumerate}
Then there exists a diagram
$$
\begin{array}{ccc}Y \underset{f}{\searrow}\underset{j}{\longrightarrow} &  & Z \overset{\pi}{\swarrow} \\  & X & \end{array}
$$
with $Z$ affine, $\pi$ finite and $j$ an open immersion.
\end{lemma}

\begin{proof}
This is
Algebra, Lemma \ref{algebra-lemma-quasi-finite-open-integral-closure}
reformulated in the language of schemes.
\end{proof}

\begin{lemma}[Image nowhere dense quasi finite]
\label{morphisms-lemma-image-nowhere-dense-quasi-finite}
\source{stacks:03J2}
\href{https://stacks.math.columbia.edu/tag/03J2}{\texttt{Stacks tag 03J2}}
\group{morphisms}

Let $f : Y \to X$ be a quasi-finite morphism of schemes.
Let $T \subset Y$ be a closed nowhere dense subset of $Y$.
Then $f(T) \subset X$ is a nowhere dense subset of $X$.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-image-nowhere-dense-finite, morphisms-lemma-quasi-finite-affine}

As in the proof of Lemma \ref{morphisms-lemma-image-nowhere-dense-finite} this
reduces immediately to the case where the base $X$ is affine.
In this case $Y = \bigcup_{i = 1, \ldots, n} Y_i$ is a finite union
of affine opens (as $f$ is quasi-compact). Since each $T \cap Y_i$
is nowhere dense, and since a finite union of nowhere dense sets is
nowhere dense (see
Topology, Lemma \ref{topology-lemma-nowhere-dense}),
it suffices to prove that the image $f(T \cap Y_i)$ is nowhere dense in $X$.
This reduces us to the case where both $X$ and $Y$ are affine. At this point
we apply Lemma \ref{morphisms-lemma-quasi-finite-affine} above to get a diagram
$$
\begin{array}{ccc}Y \underset{f}{\searrow}\underset{j}{\longrightarrow} &  & Z \overset{\pi}{\swarrow} \\  & X & \end{array}
$$
with $Z$ affine, $\pi$ finite and $j$ an open immersion.
Set $\overline{T} = \overline{j(T)} \subset Z$. By
Topology, Lemma \ref{topology-lemma-image-nowhere-dense-open}
we see $\overline{T}$ is nowhere dense in $Z$.
Since $f(T) \subset \pi(\overline{T})$
the lemma follows from the corresponding result in the finite case, see
Lemma \ref{morphisms-lemma-image-nowhere-dense-finite}.
\end{proof}

\section{Universally bounded fibres}
\label{morphisms-section-universally-bounded}
Let $X$ be a scheme over a field $k$. If $X$ is finite over $k$,
then $X = \Spec(A)$ where $A$ is a finite $k$-algebra. Another way
to say this is that $X$ is finite locally free over $\Spec(k)$,
see Definition \ref{morphisms-definition-finite-locally-free}. Hence
$X \to \Spec(k)$ has a {\it degree} which is an integer $d \geq 0$,
namely $d = \dim_k(A)$. We sometime call this the {\it degree} of the (finite)
scheme $X$ over $k$.

\begin{definition}[Universally bounded]
\label{morphisms-definition-universally-bounded}
\source{stacks:03J4}
\href{https://stacks.math.columbia.edu/tag/03J4}{\texttt{Stacks tag 03J4}}
\group{morphisms}

Let $f : X \to Y$ be a morphism of schemes.
\begin{enumerate}
\item We say the integer $n$ {\it bounds the degrees of the fibres
of $f$} if for all $y \in Y$
the fibre $X_y$ is a finite scheme over $\kappa(y)$ whose
degree over $\kappa(y)$ is $\leq n$.
\item We say the {\it fibres of $f$ are universally bounded}\footnote{This is
probably nonstandard notation.}
if there exists an integer $n$ which bounds the degrees of the fibres
of $f$.
\end{enumerate}
\end{definition}

Note that in particular the number of points in a fibre is bounded by $n$
as well. (The converse does not hold, even if all fibres are finite reduced
schemes.)

\begin{lemma}[Characterize universally bounded]
\label{morphisms-lemma-characterize-universally-bounded}
\source{stacks:03J5}
\href{https://stacks.math.columbia.edu/tag/03J5}{\texttt{Stacks tag 03J5}}
\group{morphisms}

Let $f : X \to Y$ be a morphism of schemes. Let $n \geq 0$.
The following are equivalent:
\begin{enumerate}
\item the integer $n$ bounds the degrees of the fibres of $f$, and
\item for every morphism $\Spec(k) \to Y$, where $k$ is a field,
the fibre product $X_k = \Spec(k) \times_Y X$ is finite over $k$
of degree $\leq n$.
\end{enumerate}
In this case the fibres of $f$ are universally bounded and the schemes
$X_k$ have at most $n$ points. More precisely, if
$X_k = \{x_1, \ldots, x_t\}$, then we have
$$
n \geq \sum\nolimits_{i = 1, \ldots, t} [\kappa(x_i) : k]
$$
\end{lemma}

\begin{proof}
The implication (2) $\Rightarrow$ (1) is trivial. The other implication
holds because if the image of $\Spec(k) \to Y$ is $y$, then
$X_k = \Spec(k) \times_{\Spec(\kappa(y))} X_y$. By definition the
fibres of $f$ being universally bounded means that some $n$ exists.
Finally, suppose that $X_k = \Spec(A)$. Then $\dim_k A = n$.
Hence $A$ is Artinian, all prime ideals are maximal ideals $\mathfrak m_i$,
and $A$ is the product of the localizations at these maximal ideals.
See Algebra, Lemmas \ref{algebra-lemma-finite-dimensional-algebra}
and \ref{algebra-lemma-artinian-finite-length}. Then $\mathfrak m_i$
corresponds to $x_i$, we have
$A_{\mathfrak m_i} = \mathcal{O}_{X_k, x_i}$
and hence there is a surjection
$A \to  \bigoplus \kappa(\mathfrak m_i) = \bigoplus \kappa(x_i)$
which implies the inequality in the statement of the lemma
by linear algebra.
\end{proof}

\begin{lemma}[Finite locally free universally bounded]
\label{morphisms-lemma-finite-locally-free-universally-bounded}
\source{stacks:0CC2}
\href{https://stacks.math.columbia.edu/tag/0CC2}{\texttt{Stacks tag 0CC2}}
\group{morphisms}

If $f$ is a finite locally free morphism of degree $d$, then
$d$ bounds the degree of the fibres of $f$.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-base-change-finite-locally-free}

This is true because any base change of $f$ is
finite locally free of degree $d$
(Lemma \ref{morphisms-lemma-base-change-finite-locally-free})
and hence the fibres of $f$ all have degree $d$.
\end{proof}

\begin{lemma}[Composition universally bounded]
\label{morphisms-lemma-composition-universally-bounded}
\source{stacks:03J6}
\href{https://stacks.math.columbia.edu/tag/03J6}{\texttt{Stacks tag 03J6}}
\group{morphisms}

A composition of morphisms with universally bounded fibres
is a morphism with universally bounded fibres. More precisely,
assume that $n$ bounds the degrees of the fibres of $f : X \to Y$ and
$m$ bounds the degrees of $g : Y \to Z$.
Then $nm$ bounds the degrees of the fibres of $g \circ f : X \to Z$.
\end{lemma}

\begin{proof}
Let $f : X \to Y$ and $g : Y \to Z$ have universally bounded fibres.
Say that $\deg(X_y/\kappa(y)) \leq n$ for all $y \in Y$, and that
$\deg(Y_z/\kappa(z)) \leq m$ for all $z \in Z$.
Let $z \in Z$ be a point. By assumption the scheme
$Y_z$ is finite over $\Spec(\kappa(z))$.
In particular, the underlying topological space of $Y_z$
is a finite discrete set. The fibres of the morphism
$f_z : X_z \to Y_z$ are the fibres of $f$ at the corresponding
points of $Y$, which are finite discrete sets by the reasoning above.
Hence we conclude that the underlying topological space
of $X_z$ is a finite discrete set as well. Thus $X_z$ is an affine
scheme (this is a nice exercise; it also follows for example from
Properties, Lemma \ref{properties-lemma-maximal-points-affine}
applied to the set of all points of $X_z$). Write $X_z = \Spec(A)$,
$Y_z = \Spec(B)$, and $k = \kappa(z)$. Then $k \to B \to A$
and we know that (a) $\dim_k(B) \leq m$, and (b) for every maximal
ideal $\mathfrak m \subset B$ we have
$\dim_{\kappa(\mathfrak m)}(A/\mathfrak mA) \leq n$.
We claim this implies that $\dim_k(A) \leq nm$.
Note that $B$ is the product of its localizations $B_{\mathfrak m}$, for
example because $Y_z$ is a disjoint union of $1$-point schemes, or by
Algebra, Lemmas \ref{algebra-lemma-finite-dimensional-algebra} and
\ref{algebra-lemma-artinian-finite-length}.
So we see that
$\dim_k(B) = \sum_{\mathfrak m} \dim_k(B_{\mathfrak m})$ and
$\dim_k(A) = \sum_{\mathfrak m} \dim_k(A_{\mathfrak m})$ where
in both cases $\mathfrak m$ runs over the maximal ideals of
$B$ (not of $A$). By the above, and Nakayama's Lemma
(Algebra, Lemma \ref{algebra-lemma-NAK})
we see that each $A_{\mathfrak m}$ is a quotient of
$B_{\mathfrak m}^{\oplus n}$ as a $B_{\mathfrak m}$-module. Hence
$\dim_k(A_{\mathfrak m}) \leq n \dim_k(B_{\mathfrak m})$. Putting
everything together we see that
$$
\dim_k(A) = \sum\nolimits_{\mathfrak m} \dim_ta	(A_{\mathfrak m})
\leq \sum\nolimits_{\mathfrak m} n \dim_k(B_{\mathfrak m})
= n \dim_k(B) \leq nm
$$
as desired.
\end{proof}

\begin{lemma}[Base change universally bounded]
\label{morphisms-lemma-base-change-universally-bounded}
\source{stacks:03J7}
\href{https://stacks.math.columbia.edu/tag/03J7}{\texttt{Stacks tag 03J7}}
\group{morphisms}

A base change of a morphism with universally bounded fibres is
a morphism with universally bounded fibres. More precisely, if
$n$ bounds the degrees of the fibres of $f : X \to Y$ and $Y' \to Y$
is any morphism, then the degrees of the fibres of the base change
$f' : Y' \times_Y X \to Y'$ is also bounded by $n$.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-characterize-universally-bounded}

This is clear from the result of
Lemma \ref{morphisms-lemma-characterize-universally-bounded}.
\end{proof}

\begin{lemma}[Descent universally bounded]
\label{morphisms-lemma-descent-universally-bounded}
\source{stacks:03J8}
\href{https://stacks.math.columbia.edu/tag/03J8}{\texttt{Stacks tag 03J8}}
\group{morphisms}

Let $f : X \to Y$ be a morphism of schemes.
Let $Y' \to Y$ be a morphism of schemes, and let
$f' : X' = X_{Y'} \to Y'$ be the base change of $f$.
If $Y' \to Y$ is surjective and $f'$ has universally bounded fibres,
then $f$ has universally bounded fibres. More precisely, if $n$ bounds
the degree of the fibres of $f'$, then also $n$ bounds the degrees
of the fibres of $f$.
\end{lemma}

\begin{proof}
Let $n \geq 0$ be an integer bounding the degrees of the fibres of $f'$.
We claim that $n$ works for $f$ also. Namely, if $y \in Y$ is a point,
then choose a point $y' \in Y'$ lying over $y$ and observe that
$$
X'_{y'} = \Spec(\kappa(y')) \times_{\Spec(\kappa(y))} X_y.
$$
Since $X'_{y'}$ is assumed finite of degree $\leq n$ over $\kappa(y')$
it follows that also $X_y$ is finite of degree $\leq n$ over $\kappa(y)$.
(Some details omitted.)
\end{proof}

\begin{lemma}[Immersion universally bounded]
\label{morphisms-lemma-immersion-universally-bounded}
\source{stacks:03J9}
\href{https://stacks.math.columbia.edu/tag/03J9}{\texttt{Stacks tag 03J9}}
\group{morphisms}

An immersion has universally bounded fibres.
\end{lemma}

\begin{proof}
The integer $n = 1$ works in the definition.
\end{proof}

\begin{lemma}[Etale universally bounded]
\label{morphisms-lemma-etale-universally-bounded}
\source{stacks:03WU}
\href{https://stacks.math.columbia.edu/tag/03WU}{\texttt{Stacks tag 03WU}}
\group{morphisms}

Let $f : X \to Y$ be an \'etale morphism of schemes.
Let $n \geq 0$. The following are equivalent
\begin{enumerate}
\item the integer $n$ bounds the degrees of the fibres,
\item for every field $k$ and morphism $\Spec(k) \to Y$ the
base change $X_k = \Spec(k) \times_Y X$ has at most $n$ points, and
\item for every $y \in Y$ and every separable algebraic closure
$\kappa(y) \subset \kappa(y)^{sep}$ the scheme
$X_{\kappa(y)^{sep}}$ has at most $n$ points.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-characterize-universally-bounded, morphisms-lemma-etale-over-field}

This follows from
Lemma \ref{morphisms-lemma-characterize-universally-bounded}
and the fact that the fibres $X_y$ are disjoint unions of spectra of finite
separable field extensions of $\kappa(y)$, see
Lemma \ref{morphisms-lemma-etale-over-field}.
\end{proof}

Having universally bounded fibres is an absolute notion and not a relative
notion. This is why the condition in the following lemma is that $X$ is
quasi-compact, and not that $f$ is quasi-compact.

\begin{lemma}[Locally quasi finite qc source universally bounded]
\label{morphisms-lemma-locally-quasi-finite-qc-source-universally-bounded}
\source{stacks:03JA}
\href{https://stacks.math.columbia.edu/tag/03JA}{\texttt{Stacks tag 03JA}}
\group{morphisms}

Let $f : X \to Y$ be a morphism of schemes.
Assume that
\begin{enumerate}
\item $f$ is locally quasi-finite, and
\item $X$ is quasi-compact.
\end{enumerate}
Then $f$ has universally bounded fibres.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-quasi-finite-at-point-characterize, morphisms-lemma-quasi-finite-locally-quasi-compact, morphisms-lemma-quasi-finite-affine, morphisms-lemma-immersion-universally-bounded, morphisms-lemma-composition-universally-bounded}

Since $X$ is quasi-compact, there exists a finite affine open covering
$X = \bigcup_{i = 1, \ldots, n} U_i$ and affine opens $V_i \subset Y$,
$i = 1, \ldots, n$ such that $f(U_i) \subset V_i$.
Because of the local nature of ``local quasi-finiteness''
(see Lemma \ref{morphisms-lemma-quasi-finite-at-point-characterize} part (4))
we see that the morphisms $f|_{U_i} : U_i \to V_i$ are locally
quasi-finite morphisms of affines, hence quasi-finite, see
Lemma \ref{morphisms-lemma-quasi-finite-locally-quasi-compact}.
For $y \in Y$ it is clear that $X_y = \bigcup_{y \in V_i} (U_i)_y$
is an open covering. Hence it suffices to prove the lemma
for a quasi-finite morphism of affines (namely, if $n_i$ works
for the morphism $f|_{U_i} : U_i \to V_i$, then $\sum n_i$
works for $f$).

\medskip\noindent
Assume $f : X \to Y$ is a quasi-finite morphism of affines.
By Lemma \ref{morphisms-lemma-quasi-finite-affine}
we can find a diagram
$$
\begin{array}{ccc}X \underset{f}{\searrow}\underset{j}{\longrightarrow} &  & Z \overset{\pi}{\swarrow} \\  & Y & \end{array}
$$
with $Z$ affine, $\pi$ finite and $j$ an open immersion. Since
$j$ has universally bounded fibres
(Lemma \ref{morphisms-lemma-immersion-universally-bounded})
this reduces us to showing that $\pi$ has universally bounded
fibres (Lemma \ref{morphisms-lemma-composition-universally-bounded}).

\medskip\noindent
This reduces us to a morphism of the form $\Spec(B) \to \Spec(A)$ where
$A \to B$ is finite. Say $B$ is generated by $x_1, \ldots, x_n$
as an $A$-module, so that
$$
A^{\oplus n} \longrightarrow B, \quad
(a_1, \ldots, a_n) \longmapsto \sum a_i x_i
$$
is a surjective $A$-module map. For any prime $\mathfrak p \subset A$
this induces a surjective map $\kappa(\mathfrak p)$-vector spaces
$$
\kappa(\mathfrak p)^{\oplus n} \longrightarrow B \otimes_A \kappa(\mathfrak p)
$$
In other words, the integer $n$ works in the definition
of a morphism with universally bounded fibres.
\end{proof}

\begin{lemma}[Universally bounded permanence]
\label{morphisms-lemma-universally-bounded-permanence}
\source{stacks:03JB}
\href{https://stacks.math.columbia.edu/tag/03JB}{\texttt{Stacks tag 03JB}}
\group{morphisms}

Consider a commutative diagram of morphisms of schemes
$$
\begin{array}{ccc}X \underset{g}{\searrow}\underset{f}{\longrightarrow} &  & Y \overset{h}{\swarrow} \\  & Z & \end{array}
$$
If $g$ has universally bounded fibres, and $f$ is surjective and flat,
then also $h$ has universally bounded fibres. More precisely, if $n$
bounds the degree of the fibres of $g$, then also $n$ bounds the
degree of the fibres of $h$.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-Artinian-affine, morphisms-lemma-fpqc-quotient-topology}

Assume $g$ has universally bounded fibres, and $f$ is surjective and flat.
Say the degree of the fibres of $g$ is bounded by $n \in \mathbf{N}$.
We claim $n$ also works for $h$.
Let $z \in Z$. Consider the morphism of schemes $X_z \to Y_z$.
It is flat and surjective. By assumption $X_z$ is a finite scheme
over $\kappa(z)$, in particular it is the spectrum of an
Artinian ring (by
Algebra, Lemma \ref{algebra-lemma-finite-dimensional-algebra}).
By Lemma \ref{morphisms-lemma-Artinian-affine} the morphism $X_z \to Y_z$ is affine
in particular quasi-compact. It follows from
Lemma \ref{morphisms-lemma-fpqc-quotient-topology}
that $Y_z$ is a finite discrete as this holds for $X_z$.
Hence $Y_z$ is an affine scheme (this is a nice exercise; it also follows
for example from
Properties, Lemma \ref{properties-lemma-maximal-points-affine}
applied to the set of all points of $Y_z$).
Write $Y_z = \Spec(B)$ and $X_z = \Spec(A)$.
Then $A$ is faithfully flat over $B$, so $B \subset A$.
Hence $\dim_k(B) \leq \dim_k(A) \leq n$ as desired.
\end{proof}

\section{Miscellany}
\label{morphisms-section-misc}
Results which do not fit elsewhere.

\begin{lemma}[Factor through point]
\label{morphisms-lemma-factor-through-point}
\source{stacks:0H1M}
\href{https://stacks.math.columbia.edu/tag/0H1M}{\texttt{Stacks tag 0H1M}}
\group{morphisms}

Let $f : Y \to X$ be a morphism of schemes. Let $x \in X$ be a point.
Assume that $Y$ is reduced and $f(Y)$ is set-theoretically contained
in $\{x\}$. Then $f$ factors through the canonical morphism
$x = \Spec(\kappa(x)) \to X$.
\end{lemma}

\begin{proof}
Omitted. Hints: working affine locally one reduces to a commutative algebra
lemma. Given a ring map $A \to B$ with $B$ reduced such that there exists
a unique prime ideal $\mathfrak p \subset A$ in the image of
$\Spec(B) \to \Spec(A)$, then $A \to B$ factors through $\kappa(\mathfrak p)$.
This is a nice exercise.
\end{proof}

\begin{lemma}[Factor through set of points]
\label{morphisms-lemma-factor-through-set-of-points}
\source{stacks:0H1N}
\href{https://stacks.math.columbia.edu/tag/0H1N}{\texttt{Stacks tag 0H1N}}
\group{morphisms}

Let $f : Y \to X$ be a morphism of schemes. Let $E \subset X$.
Assume $X$ is locally Noetherian, there are no nontrivial specializations
among the elements of $E$, $Y$ is reduced, and $f(Y) \subset E$.
Then $f$ factors through $\coprod_{x \in E} x \to X$.
\end{lemma}

\begin{proof}
\uses{morphisms-lemma-factor-through-point}

When $E$ is a singleton this follows from
Lemma \ref{morphisms-lemma-factor-through-point}. If $E$ is finite, then $E$
(with the induced topology of $X$) is a finite discrete space by
our assumption on specializations. Hence this case reduces to the
singleton case. In general, there is a reduction to the
case where $X$ and $Y$ are affine schemes. Say $f : Y \to X$ corresponds to
the ring map $\varphi : A \to B$. Denote $A' \subset B$ the image of $\varphi$.
Let $E' \subset \Spec(A') \subset \Spec(A)$ be the set of minimal primes
of $A'$. By Algebra, Lemma \ref{algebra-lemma-injective-minimal-primes-in-image}
the set $E'$ is contained in the image of
$\Spec(B) \to \Spec(A') \subset \Spec(A)$. We conclude that $E' \subset E$.
Since $A'$ is Noetherian we have $E'$ is finite by Algebra, Lemma
\ref{algebra-lemma-Noetherian-irreducible-components}.
Since any other point in the image of $\Spec(B) \to \Spec(A)$ is
a specialization of an element of $E'$ and in $E$, we conclude that
the image is contained in $E'$ (by our assumption on specializations between
points of $E$). Thus we reduce to the case where
$E$ is finite which we dealt with above.
\end{proof}

\label{chap:divisors}
\section{Introduction}
\label{divisors-section-introduction}
In this chapter we study some very basic questions related
to defining divisors, etc. A basic reference is \cite{EGA}.

\section{Associated points}
\label{divisors-section-associated}
Let $R$ be a ring and let $M$ be an $R$-module.
Recall that a prime $\mathfrak p \subset R$ is {\it associated} to $M$
if there exists an element of $M$ whose annihilator is $\mathfrak p$.
See Algebra, Definition \ref{algebra-definition-associated}.
Here is the definition of associated points
for quasi-coherent sheaves on schemes
as given in \cite[IV Definition 3.1.1]{EGA}.

\begin{definition}[Associated]
\label{divisors-definition-associated}
\source{stacks:02OJ}
\href{https://stacks.math.columbia.edu/tag/02OJ}{\texttt{Stacks tag 02OJ}}
\group{divisors}

Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
\begin{enumerate}
\item We say $x \in X$ is {\it associated} to $\mathcal{F}$
if the maximal ideal
$\mathfrak m_x$ is associated to the $\mathcal{O}_{X, x}$-module
$\mathcal{F}_x$.
\item We denote $\text{Ass}(\mathcal{F})$ or $\text{Ass}_X(\mathcal{F})$
the set of associated points of $\mathcal{F}$.
\item The {\it associated points of $X$} are the associated
points of $\mathcal{O}_X$.
\end{enumerate}
\end{definition}

These definitions are most useful when $X$ is locally Noetherian
and $\mathcal{F}$ of finite type.
For example it may happen that a generic point of an irreducible
component of $X$ is not associated to $X$, see
Example \ref{divisors-example-no-associated-prime}.
In the non-Noetherian case it may be more convenient to use weakly
associated points, see
Section \ref{divisors-section-weakly-associated}.
Let us link the scheme theoretic notion with the algebraic notion
on affine opens; note that this correspondence works perfectly only
for locally Noetherian schemes.

\begin{lemma}[Associated affine open]
\label{divisors-lemma-associated-affine-open}
\source{stacks:02OK}
\href{https://stacks.math.columbia.edu/tag/02OK}{\texttt{Stacks tag 02OK}}
\group{divisors}

Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $\Spec(A) = U \subset X$ be an affine open, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
\begin{enumerate}
\item If $\mathfrak p$ is associated to $M$, then $x$ is associated
to $\mathcal{F}$.
\item If $\mathfrak p$ is finitely generated, then the converse holds
as well.
\end{enumerate}
In particular, if $X$ is locally Noetherian, then the equivalence
$$
\mathfrak p \in \text{Ass}(M) \Leftrightarrow x \in \text{Ass}(\mathcal{F})
$$
holds for all pairs $(\mathfrak p, x)$ as above.
\end{lemma}

\begin{proof}
This follows from
Algebra, Lemma \ref{algebra-lemma-associated-primes-localize}.
But we can also argue directly as follows.
Suppose $\mathfrak p$ is associated to $M$.
Then there exists an $m \in M$ whose annihilator is $\mathfrak p$.
Since localization is exact we see that
$\mathfrak pA_{\mathfrak p}$ is the annihilator of
$m/1 \in M_{\mathfrak p}$. Since $M_{\mathfrak p} = \mathcal{F}_x$
(Schemes, Lemma \ref{schemes-lemma-spec-sheaves})
we conclude that $x$ is associated to $\mathcal{F}$.

\medskip\noindent
Conversely, assume that $x$ is associated to $\mathcal{F}$,
and $\mathfrak p$ is finitely generated.
As $x$ is associated to $\mathcal{F}$
there exists an element $m' \in M_{\mathfrak p}$ whose
annihilator is $\mathfrak pA_{\mathfrak p}$. Write
$m' = m/f$ for some $f \in A$, $f \not \in \mathfrak p$.
The annihilator $I$ of $m$ is an ideal of $A$ such that
$IA_{\mathfrak p} = \mathfrak pA_{\mathfrak p}$. Hence
$I \subset \mathfrak p$, and $(\mathfrak p/I)_{\mathfrak p} = 0$.
Since $\mathfrak p$ is finitely generated,
there exists a $g \in A$, $g \not \in \mathfrak p$ such that
$g(\mathfrak p/I) = 0$. Hence the annihilator of $gm$ is
$\mathfrak p$ and we win.

\medskip\noindent
If $X$ is locally Noetherian, then $A$ is Noetherian
(Properties, Lemma \ref{properties-lemma-locally-Noetherian})
and $\mathfrak p$ is always finitely generated.
\end{proof}

\begin{lemma}[Ass support]
\label{divisors-lemma-ass-support}
\source{stacks:05AD}
\href{https://stacks.math.columbia.edu/tag/05AD}{\texttt{Stacks tag 05AD}}
\group{divisors}

Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Then $\text{Ass}(\mathcal{F}) \subset \text{Supp}(\mathcal{F})$.
\end{lemma}

\begin{proof}
This is immediate from the definitions.
\end{proof}

\begin{lemma}[Ses ass]
\label{divisors-lemma-ses-ass}
\source{stacks:05AE}
\href{https://stacks.math.columbia.edu/tag/05AE}{\texttt{Stacks tag 05AE}}
\group{divisors}

Let $X$ be a scheme.
Let $0 \to \mathcal{F}_1 \to \mathcal{F}_2 \to \mathcal{F}_3 \to 0$
be a short exact sequence of quasi-coherent sheaves on $X$.
Then
$\text{Ass}(\mathcal{F}_2) \subset
\text{Ass}(\mathcal{F}_1) \cup \text{Ass}(\mathcal{F}_3)$
and
$\text{Ass}(\mathcal{F}_1) \subset \text{Ass}(\mathcal{F}_2)$.
\end{lemma}

\begin{proof}
For every point $x \in X$ the sequence of stalks
$0 \to \mathcal{F}_{1, x} \to \mathcal{F}_{2, x} \to \mathcal{F}_{3, x} \to 0$
is a short exact sequence of $\mathcal{O}_{X, x}$-modules.
Hence the lemma follows from
Algebra, Lemma \ref{algebra-lemma-ass}.
\end{proof}

\begin{lemma}[Finite ass]
\label{divisors-lemma-finite-ass}
\source{stacks:05AF}
\href{https://stacks.math.columbia.edu/tag/05AF}{\texttt{Stacks tag 05AF}}
\group{divisors}

Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
Then $\text{Ass}(\mathcal{F}) \cap U$ is finite for
every quasi-compact open $U \subset X$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-associated-affine-open}

This is true because the set of associated primes of a finite module over
a Noetherian ring is finite, see
Algebra, Lemma \ref{algebra-lemma-finite-ass}.
To translate from schemes to algebra use that $U$ is a finite union of
affine opens, each of these opens is the spectrum of a Noetherian ring
(Properties, Lemma \ref{properties-lemma-locally-Noetherian}),
$\mathcal{F}$ corresponds to a finite module over this ring
(Cohomology of Schemes, Lemma \ref{coherent-lemma-coherent-Noetherian}),
and finally use
Lemma \ref{divisors-lemma-associated-affine-open}.
\end{proof}

\begin{lemma}[Ass zero]
\label{divisors-lemma-ass-zero}
\source{stacks:05AG}
\href{https://stacks.math.columbia.edu/tag/05AG}{\texttt{Stacks tag 05AG}}
\group{divisors}

Let $X$ be a locally Noetherian scheme. Let $\mathcal{F}$ be a
quasi-coherent $\mathcal{O}_X$-module. Then
$$
\mathcal{F} = 0 \Leftrightarrow \text{Ass}(\mathcal{F}) = \emptyset.
$$
\end{lemma}

\begin{proof}
\uses{divisors-lemma-associated-affine-open}

If $\mathcal{F} = 0$, then $\text{Ass}(\mathcal{F}) = \emptyset$
by definition. Conversely, if $\text{Ass}(\mathcal{F}) = \emptyset$,
then $\mathcal{F} = 0$ by
Algebra, Lemma \ref{algebra-lemma-ass-zero}.
To translate from schemes to algebra, restrict to any affine and use
Lemma \ref{divisors-lemma-associated-affine-open}.
\end{proof}

\begin{example}[No associated prime]
\label{divisors-example-no-associated-prime}
\source{stacks:05AI}
\href{https://stacks.math.columbia.edu/tag/05AI}{\texttt{Stacks tag 05AI}}
\group{divisors}

Let $k$ be a field. The ring $R = k[x_1, x_2, x_3, \ldots]/(x_i^2)$
is local with locally nilpotent maximal ideal $\mathfrak m$.
There exists no element of $R$ which has annihilator $\mathfrak m$.
Hence $\text{Ass}(R) = \emptyset$, and $X = \Spec(R)$
is an example of a scheme which has no associated points.
\end{example}

\begin{lemma}[Restriction injective open contains ass]
\label{divisors-lemma-restriction-injective-open-contains-ass}
\source{stacks:0B3L}
\href{https://stacks.math.columbia.edu/tag/0B3L}{\texttt{Stacks tag 0B3L}}
\group{divisors}

Let $X$ be a locally Noetherian scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. If $U \subset X$ is open and
$\text{Ass}(\mathcal{F}) \subset U$, then
$\Gamma(X, \mathcal{F}) \to \Gamma(U, \mathcal{F})$ is injective.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-ses-ass, divisors-lemma-ass-support, divisors-lemma-ass-zero}

Let $s \in \Gamma(X, \mathcal{F})$ be a section which restricts to zero on $U$.
Let $\mathcal{F}' \subset \mathcal{F}$ be the image of the map
$\mathcal{O}_X \to \mathcal{F}$ defined by $s$. Then
$\text{Supp}(\mathcal{F}') \cap U = \emptyset$. On the other hand,
$\text{Ass}(\mathcal{F}') \subset \text{Ass}(\mathcal{F})$
by Lemma \ref{divisors-lemma-ses-ass}. Since also
$\text{Ass}(\mathcal{F}') \subset \text{Supp}(\mathcal{F}')$
(Lemma \ref{divisors-lemma-ass-support}) we conclude
$\text{Ass}(\mathcal{F}') = \emptyset$.
Hence $\mathcal{F}' = 0$ by Lemma \ref{divisors-lemma-ass-zero}.
\end{proof}

\begin{lemma}[Minimal support in ass]
\label{divisors-lemma-minimal-support-in-ass}
\source{stacks:05AH}
\href{https://stacks.math.columbia.edu/tag/05AH}{\texttt{Stacks tag 05AH}}
\group{divisors}

Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Let $x \in \text{Supp}(\mathcal{F})$ be a point in the support
of $\mathcal{F}$ which is not a specialization of another point of
$\text{Supp}(\mathcal{F})$. Then $x \in \text{Ass}(\mathcal{F})$.
In particular, any generic point of an irreducible component of $X$
is an associated point of $X$.
\end{lemma}

\begin{proof}
Since $x \in \text{Supp}(\mathcal{F})$ the module $\mathcal{F}_x$
is not zero. Hence
$\text{Ass}(\mathcal{F}_x) \subset \Spec(\mathcal{O}_{X, x})$
is nonempty by
Algebra, Lemma \ref{algebra-lemma-ass-zero}.
On the other hand, by assumption
$\text{Supp}(\mathcal{F}_x) = \{\mathfrak m_x\}$.
Since
$\text{Ass}(\mathcal{F}_x) \subset \text{Supp}(\mathcal{F}_x)$
(Algebra, Lemma \ref{algebra-lemma-ass-support})
we see that $\mathfrak m_x$ is associated to $\mathcal{F}_x$
and we win.
\end{proof}

The following lemma is the analogue of
More on Algebra, Lemma \ref{more-algebra-lemma-check-injective-on-ass}.

\begin{lemma}[Check injective on ass]
\label{divisors-lemma-check-injective-on-ass}
\source{stacks:0AVL}
\href{https://stacks.math.columbia.edu/tag/0AVL}{\texttt{Stacks tag 0AVL}}
\group{divisors}

Let $X$ be a locally Noetherian scheme. Let
$\varphi : \mathcal{F} \to \mathcal{G}$ be a map of
quasi-coherent $\mathcal{O}_X$-modules.
Assume that for every $x \in X$
at least one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x \to \mathcal{G}_x$ is injective, or
\item $x \not \in \text{Ass}(\mathcal{F})$.
\end{enumerate}
Then $\varphi$ is injective.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-ass-zero}

The assumptions imply that $\text{Ass}(\Ker(\varphi)) = \emptyset$
and hence $\Ker(\varphi) = 0$ by Lemma \ref{divisors-lemma-ass-zero}.
\end{proof}

\begin{lemma}[Check isomorphism via depth and ass]
\label{divisors-lemma-check-isomorphism-via-depth-and-ass}
\source{stacks:0AVM}
\href{https://stacks.math.columbia.edu/tag/0AVM}{\texttt{Stacks tag 0AVM}}
\group{divisors}

Let $X$ be a locally Noetherian scheme. Let
$\varphi : \mathcal{F} \to \mathcal{G}$ be a map of
quasi-coherent $\mathcal{O}_X$-modules. Assume $\mathcal{F}$ is coherent
and that for every $x \in X$ one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x \to \mathcal{G}_x$ is an isomorphism, or
\item $\text{depth}(\mathcal{F}_x) \geq 2$ and
$x \not \in \text{Ass}(\mathcal{G})$.
\end{enumerate}
Then $\varphi$ is an isomorphism.
\end{lemma}

\begin{proof}
This is a translation of More on Algebra, Lemma
\ref{more-algebra-lemma-check-isomorphism-via-depth-and-ass}
into the language of schemes.
\end{proof}

\section{Morphisms and associated points}
\label{divisors-section-morphisms-associated}
Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a sheaf of $\mathcal{O}_X$-modules.
If $s \in S$ is a point, then it is often convenient to
denote $\mathcal{F}_s$ the $\mathcal{O}_{X_s}$-module
one gets by pulling back $\mathcal{F}$ by the morphism
$i_s : X_s \to X$. Here $X_s$ is the scheme theoretic fibre of $f$ over $s$.
In a formula
$$
\mathcal{F}_s = i_s^*\mathcal{F}
$$
Of course, this notation clashes with the already existing notation
for the stalk of $\mathcal{F}$ at a point $x \in X$ if $f = \text{id}_X$.
However, the notation is often convenient, as in the formulation of
the following lemma.

\begin{lemma}[Bourbaki]
\label{divisors-lemma-bourbaki}
\source{stacks:05DB}
\href{https://stacks.math.columbia.edu/tag/05DB}{\texttt{Stacks tag 05DB}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$ which is flat over $S$.
Let $\mathcal{G}$ be a quasi-coherent sheaf on $S$.
Then we have
$$
\text{Ass}_X(\mathcal{F} \otimes_{\mathcal{O}_X} f^*\mathcal{G})
\supset
\bigcup\nolimits_{s \in \text{Ass}_S(\mathcal{G})}
\text{Ass}_{X_s}(\mathcal{F}_s)
$$
and equality holds if $S$ is locally Noetherian (for the notation
$\mathcal{F}_s$ see above).
\end{lemma}

\begin{proof}
Let $x \in X$ and let $s = f(x) \in S$.
Set $B = \mathcal{O}_{X, x}$, $A = \mathcal{O}_{S, s}$,
$N = \mathcal{F}_x$, and $M = \mathcal{G}_s$.
Note that the stalk of $\mathcal{F} \otimes_{\mathcal{O}_X} f^*\mathcal{G}$
at $x$ is equal to the $B$-module $M \otimes_A N$. Hence
$x \in \text{Ass}_X(\mathcal{F} \otimes_{\mathcal{O}_X} f^*\mathcal{G})$
if and only if $\mathfrak m_B$ is in $\text{Ass}_B(M \otimes_A N)$.
Similarly $s \in \text{Ass}_S(\mathcal{G})$ and
$x \in \text{Ass}_{X_s}(\mathcal{F}_s)$ if and only if
$\mathfrak m_A \in \text{Ass}_A(M)$ and
$\mathfrak m_B/\mathfrak m_A B \in
\text{Ass}_{B \otimes \kappa(\mathfrak m_A)}(N \otimes \kappa(\mathfrak m_A))$.
Thus the lemma follows from
Algebra, Lemma \ref{algebra-lemma-bourbaki-fibres}.
\end{proof}

\section{Embedded points}
\label{divisors-section-embedded}
Let $R$ be a ring and let $M$ be an $R$-module.
Recall that a prime $\mathfrak p \subset R$ is an
{\it embedded associated prime} of $M$ if it is an associated prime of
$M$ which is not minimal among the associated primes of $M$. See
Algebra, Definition \ref{algebra-definition-embedded-primes}.
Here is the definition of embedded associated points
for quasi-coherent sheaves on schemes
as given in \cite[IV Definition 3.1.1]{EGA}.

\begin{definition}[Embedded]
\label{divisors-definition-embedded}
\source{stacks:05AK}
\href{https://stacks.math.columbia.edu/tag/05AK}{\texttt{Stacks tag 05AK}}
\group{divisors}

Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
\begin{enumerate}
\item An {\it embedded associated point} of $\mathcal{F}$
is an associated point which is not maximal among the
associated points of $\mathcal{F}$, i.e., it is the specialization
of another associated point of $\mathcal{F}$.
\item A point $x$ of $X$ is called an {\it embedded point}
if $x$ is an embedded associated point of $\mathcal{O}_X$.
\item An {\it embedded component} of $X$ is an irreducible
closed subset $Z = \overline{\{x\}}$ where $x$ is an embedded
point of $X$.
\end{enumerate}
\end{definition}

In the Noetherian case when $\mathcal{F}$ is coherent we have
the following.

\begin{lemma}[Embedded]
\label{divisors-lemma-embedded}
\source{stacks:05AL}
\href{https://stacks.math.columbia.edu/tag/05AL}{\texttt{Stacks tag 05AL}}
\group{divisors}

Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
Then
\begin{enumerate}
\item the generic points of irreducible components of
$\text{Supp}(\mathcal{F})$ are associated points of $\mathcal{F}$, and
\item an associated point of $\mathcal{F}$ is embedded if and only
if it is not a generic point of an irreducible component
of $\text{Supp}(\mathcal{F})$.
\end{enumerate}
In particular an embedded point of $X$ is an associated point of $X$
which is not a generic point of an irreducible component of $X$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-minimal-support-in-ass, divisors-lemma-ass-support}

Recall that in this case $Z = \text{Supp}(\mathcal{F})$ is closed, see
Morphisms, Lemma \ref{morphisms-lemma-support-finite-type}
and that the generic points of irreducible components of $Z$ are
associated points of $\mathcal{F}$, see
Lemma \ref{divisors-lemma-minimal-support-in-ass}.
Finally, we have $\text{Ass}(\mathcal{F}) \subset Z$, by
Lemma \ref{divisors-lemma-ass-support}.
These results, combined with the fact that $Z$ is a sober topological
space and hence every point of $Z$ is a specialization of a generic
point of $Z$, imply (1) and (2).
\end{proof}

\begin{lemma}[S1 no embedded]
\label{divisors-lemma-S1-no-embedded}
\source{stacks:0346}
\href{https://stacks.math.columbia.edu/tag/0346}{\texttt{Stacks tag 0346}}
\group{divisors}

Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent sheaf on $X$.
Then the following are equivalent:
\begin{enumerate}
\item $\mathcal{F}$ has no embedded associated points, and
\item $\mathcal{F}$ has property $(S_1)$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{divisors-lemma-associated-affine-open}

This is Algebra, Lemma \ref{algebra-lemma-criterion-no-embedded-primes},
combined with Lemma \ref{divisors-lemma-associated-affine-open} above.
\end{proof}

\begin{lemma}[Noetherian dim 1 CM no embedded points]
\label{divisors-lemma-noetherian-dim-1-CM-no-embedded-points}
\source{stacks:0BXG}
\href{https://stacks.math.columbia.edu/tag/0BXG}{\texttt{Stacks tag 0BXG}}
\group{divisors}

Let $X$ be a locally Noetherian scheme of dimension $\leq 1$.
The following are equivalent
\begin{enumerate}
\item $X$ is Cohen-Macaulay, and
\item $X$ has no embedded points.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{divisors-lemma-S1-no-embedded}

Follows from Lemma \ref{divisors-lemma-S1-no-embedded} and the definitions.
\end{proof}

\begin{lemma}[Scheme theoretically dense contain embedded points]
\label{divisors-lemma-scheme-theoretically-dense-contain-embedded-points}
\source{stacks:083P}
\href{https://stacks.math.columbia.edu/tag/083P}{\texttt{Stacks tag 083P}}
\group{divisors}

Let $X$ be a locally Noetherian scheme. Let $U \subset X$ be an
open subscheme. The following are equivalent
\begin{enumerate}
\item $U$ is scheme theoretically dense in $X$
(Morphisms, Definition \ref{morphisms-definition-scheme-theoretically-dense}),
\item $U$ is dense in $X$ and $U$ contains all embedded points of $X$, and
\item $U$ contains all associated points of $X$.
\end{enumerate}
\end{lemma}

\begin{proof}
The question is local on $X$, hence we may assume that $X = \Spec(A)$
where $A$ is a Noetherian ring. Then $U$ is quasi-compact
(Properties, Lemma \ref{properties-lemma-immersion-into-noetherian})
hence $U = D(f_1) \cup \ldots \cup D(f_n)$
(Algebra, Lemma \ref{algebra-lemma-qc-open}).
In this situation $U$ is scheme theoretically dense in $X$ if and only if
$A \to A_{f_1} \times \ldots \times A_{f_n}$ is injective, see
Morphisms, Example \ref{morphisms-example-scheme-theoretic-closure}.
Condition (3) translated into algebra means that for every associated
prime $\mathfrak p$ of $A$ there exists an $i$ with $f_i \not \in \mathfrak p$.

\medskip\noindent
Assume (1), i.e., $A \to A_{f_1} \times \ldots \times A_{f_n}$ is injective.
Say $a \in A$ has annihilator a prime $\mathfrak p$. Since $a$ maps
to a nonzero element of $A_{f_i}$ for some $i$ we see that
$f_i \not \in \mathfrak p$. Thus (3) holds.

\medskip\noindent
Note that $U$ is dense in $\Spec(A)$ if and only if it contains all
minimal prime ideals. Since the set of associated primes
of $A$ is equal to the union of the set of minimal primes and the
set of embedded associated primes (see Algebra, Proposition
\ref{algebra-proposition-minimal-primes-associated-primes}),
we see that (2) and (3) are equivalent.

\medskip\noindent
Assume (3). This means that every associated prime $\mathfrak p$ of $A$
corresponds to a prime of $A_{f_i}$ for some $i$. Then
$A \to A_{f_1} \times \ldots \times A_{f_n}$ is injective because
$A \to \prod_{\mathfrak p \in \text{Ass}(A)} A_\mathfrak p$ is injective
by Algebra, Lemma \ref{algebra-lemma-zero-at-ass-zero}. In this way
we see that (3) implies (1).
\end{proof}

\begin{lemma}[Remove embedded points]
\label{divisors-lemma-remove-embedded-points}
\source{stacks:02OL}
\href{https://stacks.math.columbia.edu/tag/02OL}{\texttt{Stacks tag 02OL}}
\group{divisors}

Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent sheaf on $X$.
The set of coherent subsheaves
$$
\{
\mathcal{K} \subset \mathcal{F}
\mid
\text{Supp}(\mathcal{K})\text{ is nowhere dense in }\text{Supp}(\mathcal{F})
\}
$$
has a maximal element $\mathcal{K}$.
Setting $\mathcal{F}' = \mathcal{F}/\mathcal{K}$ we have the
following
\begin{enumerate}
\item $\text{Supp}(\mathcal{F}') = \text{Supp}(\mathcal{F})$,
\item $\mathcal{F}'$ has no embedded associated points, and
\item there exists a dense open $U \subset X$ such that
$U \cap \text{Supp}(\mathcal{F})$ is dense in $\text{Supp}(\mathcal{F})$
and $\mathcal{F}'|_U \cong \mathcal{F}|_U$.
\end{enumerate}
\end{lemma}

\begin{proof}
This follows from
Algebra, Lemmas \ref{algebra-lemma-remove-embedded-primes} and
\ref{algebra-lemma-remove-embedded-primes-localize}.
Note that $U$ can be taken as the complement of the closure
of the set of embedded associated points of $\mathcal{F}$.
\end{proof}

\begin{lemma}[No embedded points endos]
\label{divisors-lemma-no-embedded-points-endos}
\source{stacks:02OM}
\href{https://stacks.math.columbia.edu/tag/02OM}{\texttt{Stacks tag 02OM}}
\group{divisors}

Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module
without embedded associated points. Set
$$
\mathcal{I}
=
\Ker(\mathcal{O}_X
\longrightarrow
\SheafHom_{\mathcal{O}_X}(\mathcal{F}, \mathcal{F})).
$$
This is a coherent sheaf of ideals which defines a closed
subscheme $Z \subset X$ without embedded points. Moreover
there exists a coherent sheaf $\mathcal{G}$ on $Z$
such that (a) $\mathcal{F} = (Z \to X)_*\mathcal{G}$,
(b) $\mathcal{G}$ has no associated embedded points, and
(c) $\text{Supp}(\mathcal{G}) = Z$ (as sets).
\end{lemma}

\begin{proof}
Some of the statements we have seen in the proof of
Cohomology of Schemes, Lemma \ref{coherent-lemma-coherent-support-closed}.
The others follow from
Algebra, Lemma \ref{algebra-lemma-no-embedded-primes-endos}.
\end{proof}

\section{Weakly associated points}
\label{divisors-section-weakly-associated}
Let $R$ be a ring and let $M$ be an $R$-module.
Recall that a prime $\mathfrak p \subset R$ is {\it weakly associated}
to $M$ if there exists an element $m$ of $M$ such that $\mathfrak p$ is
minimal among the primes containing the annihilator of $m$. See
Algebra, Definition \ref{algebra-definition-weakly-associated}.
If $R$ is a local ring with maximal ideal $\mathfrak m$, then
$\mathfrak m$ is weakly associated to $M$ if and only if there exists an
element $m \in M$ whose annihilator has radical $\mathfrak m$, see
Algebra, Lemma \ref{algebra-lemma-weakly-ass-local}.

\begin{definition}[Weakly associated]
\label{divisors-definition-weakly-associated}
\source{stacks:056L}
\href{https://stacks.math.columbia.edu/tag/056L}{\texttt{Stacks tag 056L}}
\group{divisors}

Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
\begin{enumerate}
\item We say $x \in X$ is {\it weakly associated} to $\mathcal{F}$
if the maximal ideal $\mathfrak m_x$ is weakly associated to the
$\mathcal{O}_{X, x}$-module $\mathcal{F}_x$.
\item We denote $\text{WeakAss}(\mathcal{F})$ the set of weakly associated
points of $\mathcal{F}$.
\item The {\it weakly associated points of $X$} are the weakly associated
points of $\mathcal{O}_X$.
\end{enumerate}
\end{definition}

In this case, on any affine open, this corresponds exactly to the
weakly associated primes as defined above. Here is the precise statement.

\begin{lemma}[Weakly associated affine open]
\label{divisors-lemma-weakly-associated-affine-open}
\source{stacks:056M}
\href{https://stacks.math.columbia.edu/tag/056M}{\texttt{Stacks tag 056M}}
\group{divisors}

Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $\Spec(A) = U \subset X$ be an affine open, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
The following are equivalent
\begin{enumerate}
\item $\mathfrak p$ is weakly associated to $M$, and
\item $x$ is weakly associated to $\mathcal{F}$.
\end{enumerate}
\end{lemma}

\begin{proof}
This follows from
Algebra, Lemma \ref{algebra-lemma-weakly-ass-local}.
\end{proof}

\begin{lemma}[Weakly ass support]
\label{divisors-lemma-weakly-ass-support}
\source{stacks:05AM}
\href{https://stacks.math.columbia.edu/tag/05AM}{\texttt{Stacks tag 05AM}}
\group{divisors}

Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Then
$$
\text{Ass}(\mathcal{F}) \subset \text{WeakAss}(\mathcal{F}) \subset
\text{Supp}(\mathcal{F}).
$$
\end{lemma}

\begin{proof}
This is immediate from the definitions.
\end{proof}

\begin{lemma}[Ses weakly ass]
\label{divisors-lemma-ses-weakly-ass}
\source{stacks:05AN}
\href{https://stacks.math.columbia.edu/tag/05AN}{\texttt{Stacks tag 05AN}}
\group{divisors}

Let $X$ be a scheme.
Let $0 \to \mathcal{F}_1 \to \mathcal{F}_2 \to \mathcal{F}_3 \to 0$
be a short exact sequence of quasi-coherent sheaves on $X$.
Then
$\text{WeakAss}(\mathcal{F}_2) \subset
\text{WeakAss}(\mathcal{F}_1) \cup \text{WeakAss}(\mathcal{F}_3)$
and
$\text{WeakAss}(\mathcal{F}_1) \subset \text{WeakAss}(\mathcal{F}_2)$.
\end{lemma}

\begin{proof}
For every point $x \in X$ the sequence of stalks
$0 \to \mathcal{F}_{1, x} \to \mathcal{F}_{2, x} \to \mathcal{F}_{3, x} \to 0$
is a short exact sequence of $\mathcal{O}_{X, x}$-modules.
Hence the lemma follows from
Algebra, Lemma \ref{algebra-lemma-weakly-ass}.
\end{proof}

\begin{lemma}[Weakly ass zero]
\label{divisors-lemma-weakly-ass-zero}
\source{stacks:05AP}
\href{https://stacks.math.columbia.edu/tag/05AP}{\texttt{Stacks tag 05AP}}
\group{divisors}

Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Then
$$
\mathcal{F} = (0) \Leftrightarrow \text{WeakAss}(\mathcal{F}) = \emptyset
$$
\end{lemma}

\begin{proof}
\uses{divisors-lemma-weakly-associated-affine-open}

Follows from
Lemma \ref{divisors-lemma-weakly-associated-affine-open}
and
Algebra, Lemma \ref{algebra-lemma-weakly-ass-zero}
\end{proof}

\begin{lemma}[Restriction injective open contains weakly ass]
\label{divisors-lemma-restriction-injective-open-contains-weakly-ass}
\source{stacks:0B3M}
\href{https://stacks.math.columbia.edu/tag/0B3M}{\texttt{Stacks tag 0B3M}}
\group{divisors}

Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. If $U \subset X$ is open and
$\text{WeakAss}(\mathcal{F}) \subset U$, then
$\Gamma(X, \mathcal{F}) \to \Gamma(U, \mathcal{F})$
is injective.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-ses-weakly-ass, divisors-lemma-weakly-ass-support, divisors-lemma-weakly-ass-zero}

Let $s \in \Gamma(X, \mathcal{F})$ be a section which restricts to zero on $U$.
Let $\mathcal{F}' \subset \mathcal{F}$ be the image of the map
$\mathcal{O}_X \to \mathcal{F}$ defined by $s$. Then
$\text{Supp}(\mathcal{F}') \cap U = \emptyset$. On the other hand,
$\text{WeakAss}(\mathcal{F}') \subset \text{WeakAss}(\mathcal{F})$
by Lemma \ref{divisors-lemma-ses-weakly-ass}. Since also
$\text{WeakAss}(\mathcal{F}') \subset \text{Supp}(\mathcal{F}')$
(Lemma \ref{divisors-lemma-weakly-ass-support}) we conclude
$\text{WeakAss}(\mathcal{F}') = \emptyset$.
Hence $\mathcal{F}' = 0$ by Lemma \ref{divisors-lemma-weakly-ass-zero}.
\end{proof}

\begin{lemma}[Minimal support in weakly ass]
\label{divisors-lemma-minimal-support-in-weakly-ass}
\source{stacks:05AQ}
\href{https://stacks.math.columbia.edu/tag/05AQ}{\texttt{Stacks tag 05AQ}}
\group{divisors}

Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Let $x \in \text{Supp}(\mathcal{F})$ be a point in the support
of $\mathcal{F}$ which is not a specialization of another point of
$\text{Supp}(\mathcal{F})$. Then
$x \in \text{WeakAss}(\mathcal{F})$.
In particular, any generic point of an irreducible component of $X$
is weakly associated to $\mathcal{O}_X$.
\end{lemma}

\begin{proof}
Since $x \in \text{Supp}(\mathcal{F})$ the module $\mathcal{F}_x$
is not zero. Hence
$\text{WeakAss}(\mathcal{F}_x) \subset \Spec(\mathcal{O}_{X, x})$
is nonempty by
Algebra, Lemma \ref{algebra-lemma-weakly-ass-zero}.
On the other hand, by assumption
$\text{Supp}(\mathcal{F}_x) = \{\mathfrak m_x\}$.
Since
$\text{WeakAss}(\mathcal{F}_x) \subset \text{Supp}(\mathcal{F}_x)$
(Algebra, Lemma \ref{algebra-lemma-weakly-ass-support})
we see that $\mathfrak m_x$ is weakly associated to $\mathcal{F}_x$
and we win.
\end{proof}

\begin{lemma}[Ass weakly ass]
\label{divisors-lemma-ass-weakly-ass}
\source{stacks:05AR}
\href{https://stacks.math.columbia.edu/tag/05AR}{\texttt{Stacks tag 05AR}}
\group{divisors}

Let $X$ be a scheme.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
If $\mathfrak m_x$ is a finitely generated ideal of $\mathcal{O}_{X, x}$,
then
$$
x \in \text{Ass}(\mathcal{F}) \Leftrightarrow
x \in \text{WeakAss}(\mathcal{F}).
$$
In particular, if $X$ is locally Noetherian, then
$\text{Ass}(\mathcal{F}) = \text{WeakAss}(\mathcal{F})$.
\end{lemma}

\begin{proof}
See
Algebra, Lemma \ref{algebra-lemma-ass-weakly-ass}.
\end{proof}

\begin{lemma}[Weakass pushforward]
\label{divisors-lemma-weakass-pushforward}
\source{stacks:0AVN}
\href{https://stacks.math.columbia.edu/tag/0AVN}{\texttt{Stacks tag 0AVN}}
\group{divisors}

Let $f : X \to S$ be a quasi-compact and quasi-separated morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Let $s \in S$ be a point which is not in the image of $f$. Then
$s$ is not weakly associated to $f_*\mathcal{F}$.
\end{lemma}

\begin{proof}
Consider the base change $f' : X' \to \Spec(\mathcal{O}_{S, s})$
of $f$ by the morphism $g : \Spec(\mathcal{O}_{S, s}) \to S$
and denote $g' : X' \to X$ the other projection.
Then
$$
(f_*\mathcal{F})_s = (g^*f_*\mathcal{F})_s = (f'_*(g')^*\mathcal{F})_s
$$
The first equality because $g$ induces an isomorphism on local
rings at $s$ and the second by flat base change (Cohomology of Schemes, Lemma
\ref{coherent-lemma-flat-base-change-cohomology}). Of course
$s \in \Spec(\mathcal{O}_{S, s})$ is not in the image of $f'$.
Thus we may assume $S$ is the spectrum of a local ring
$(A, \mathfrak m)$ and $s$ corresponds to $\mathfrak m$.
By Schemes, Lemma \ref{schemes-lemma-push-forward-quasi-coherent}
the sheaf $f_*\mathcal{F}$ is quasi-coherent, say corresponding
to the $A$-module $M$. As $s$ is not in the image of $f$ we see that
$X = \bigcup_{a \in \mathfrak m} f^{-1}D(a)$ is an open covering.
Since $X$ is quasi-compact we can find $a_1, \ldots, a_n \in \mathfrak m$
such that $X = f^{-1}D(a_1) \cup \ldots \cup f^{-1}D(a_n)$. It follows
that
$$
M \to M_{a_1} \oplus \ldots \oplus M_{a_r}
$$
is injective. Hence for any nonzero element $m$ of the stalk $M_\mathfrak p$
there exists an $i$ such that $a_i^n m$ is nonzero for all $n \geq 0$.
Thus $\mathfrak m$ is not weakly associated to $M$.
\end{proof}

\begin{lemma}[Check injective on weakass]
\label{divisors-lemma-check-injective-on-weakass}
\source{stacks:0AVP}
\href{https://stacks.math.columbia.edu/tag/0AVP}{\texttt{Stacks tag 0AVP}}
\group{divisors}

Let $X$ be a scheme. Let $\varphi : \mathcal{F} \to \mathcal{G}$ be a map of
quasi-coherent $\mathcal{O}_X$-modules. Assume that for every $x \in X$
at least one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x \to \mathcal{G}_x$ is injective, or
\item $x \not \in \text{WeakAss}(\mathcal{F})$.
\end{enumerate}
Then $\varphi$ is injective.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-weakly-ass-zero}

The assumptions imply that $\text{WeakAss}(\Ker(\varphi)) = \emptyset$
and hence $\Ker(\varphi) = 0$ by Lemma \ref{divisors-lemma-weakly-ass-zero}.
\end{proof}

\begin{lemma}[Depth 2 hartog]
\label{divisors-lemma-depth-2-hartog}
\source{stacks:0E9I}
\href{https://stacks.math.columbia.edu/tag/0E9I}{\texttt{Stacks tag 0E9I}}
\group{divisors}

Let $X$ be a locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module. Let $j : U \to X$
be an open subscheme such that for $x \in X \setminus U$
we have $\text{depth}(\mathcal{F}_x) \geq 2$. Then
$$
\mathcal{F} \longrightarrow j_*(\mathcal{F}|_U)
$$
is an isomorphism and consequently
$\Gamma(X, \mathcal{F}) \to \Gamma(U, \mathcal{F})$
is an isomorphism too.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-check-isomorphism-via-depth-and-ass, divisors-lemma-weakass-pushforward, divisors-lemma-weakly-ass-support}

We claim Lemma \ref{divisors-lemma-check-isomorphism-via-depth-and-ass}
applies to the map displayed in the lemma.
Let $x \in X$. If $x \in U$, then the map is an
isomorphism on stalks as $j_*(\mathcal{F}|_U)|_U = \mathcal{F}|_U$.
If $x \in X \setminus U$, then $x \not \in \text{Ass}(j_*(\mathcal{F}|_U))$
(Lemmas \ref{divisors-lemma-weakass-pushforward} and \ref{divisors-lemma-weakly-ass-support}).
Since we've assumed $\text{depth}(\mathcal{F}_x) \geq 2$
this finishes the proof.
\end{proof}

\begin{lemma}[Weakass reduced]
\label{divisors-lemma-weakass-reduced}
\source{stacks:0EME}
\href{https://stacks.math.columbia.edu/tag/0EME}{\texttt{Stacks tag 0EME}}
\group{divisors}

Let $X$ be a reduced scheme. Then the weakly associated points of $X$
are exactly the generic points of the irreducible components of $X$.
\end{lemma}

\begin{proof}
Follows from Algebra, Lemma \ref{algebra-lemma-reduced-weakly-ass-minimal}.
\end{proof}

\section{Morphisms and weakly associated points}
\label{divisors-section-morphisms-weakly-associated}
\begin{lemma}[Weakly ass reverse functorial]
\label{divisors-lemma-weakly-ass-reverse-functorial}
\source{stacks:05EX}
\href{https://stacks.math.columbia.edu/tag/05EX}{\texttt{Stacks tag 05EX}}
\group{divisors}

Let $f : X \to S$ be an affine morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Then we have
$$
\text{WeakAss}_S(f_*\mathcal{F}) \subset f(\text{WeakAss}_X(\mathcal{F}))
$$
\end{lemma}

\begin{proof}
\uses{divisors-lemma-weakly-associated-affine-open}

We may assume $X$ and $S$ affine, so $X \to S$ comes from a ring map
$A \to B$. Then $\mathcal{F} = \widetilde M$ for some $B$-module $M$. By
Lemma \ref{divisors-lemma-weakly-associated-affine-open}
the weakly associated points of $\mathcal{F}$ correspond exactly to the
weakly associated primes of $M$. Similarly, the weakly associated points
of $f_*\mathcal{F}$ correspond exactly to the weakly associated primes
of $M$ as an $A$-module. Hence the lemma follows from
Algebra, Lemma \ref{algebra-lemma-weakly-ass-reverse-functorial}.
\end{proof}

\begin{lemma}[Ass functorial equal]
\label{divisors-lemma-ass-functorial-equal}
\source{stacks:05EY}
\href{https://stacks.math.columbia.edu/tag/05EY}{\texttt{Stacks tag 05EY}}
\group{divisors}

Let $f : X \to S$ be an affine morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
If $X$ is locally Noetherian, then we have
$$
f(\text{Ass}_X(\mathcal{F})) =
\text{Ass}_S(f_*\mathcal{F}) =
\text{WeakAss}_S(f_*\mathcal{F}) =
f(\text{WeakAss}_X(\mathcal{F}))
$$
\end{lemma}

\begin{proof}
\uses{divisors-lemma-associated-affine-open, divisors-lemma-weakly-ass-support, divisors-lemma-weakly-ass-reverse-functorial, divisors-lemma-ass-weakly-ass}

We may assume $X$ and $S$ affine, so $X \to S$ comes from a ring map
$A \to B$. As $X$ is locally Noetherian the ring $B$ is Noetherian, see
Properties, Lemma \ref{properties-lemma-locally-Noetherian}.
Write $\mathcal{F} = \widetilde M$ for some $B$-module $M$. By
Lemma \ref{divisors-lemma-associated-affine-open}
the associated points of $\mathcal{F}$ correspond exactly to the associated
primes of $M$, and any associated prime of $M$ as an $A$-module is an
associated points of $f_*\mathcal{F}$.
Hence the inclusion
$$
f(\text{Ass}_X(\mathcal{F})) \subset \text{Ass}_S(f_*\mathcal{F})
$$
follows from
Algebra, Lemma \ref{algebra-lemma-ass-functorial-Noetherian}.
We have the inclusion
$$
\text{Ass}_S(f_*\mathcal{F}) \subset \text{WeakAss}_S(f_*\mathcal{F})
$$
by
Lemma \ref{divisors-lemma-weakly-ass-support}.
We have the inclusion
$$
\text{WeakAss}_S(f_*\mathcal{F}) \subset f(\text{WeakAss}_X(\mathcal{F}))
$$
by
Lemma \ref{divisors-lemma-weakly-ass-reverse-functorial}.
The outer sets are equal by
Lemma \ref{divisors-lemma-ass-weakly-ass}
hence we have equality everywhere.
\end{proof}

\begin{lemma}[Weakly associated finite]
\label{divisors-lemma-weakly-associated-finite}
\source{stacks:05EZ}
\href{https://stacks.math.columbia.edu/tag/05EZ}{\texttt{Stacks tag 05EZ}}
\group{divisors}

Let $f : X \to S$ be a finite morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Then $\text{WeakAss}(f_*\mathcal{F}) = f(\text{WeakAss}(\mathcal{F}))$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-weakly-associated-affine-open}

We may assume $X$ and $S$ affine, so $X \to S$ comes from a finite ring map
$A \to B$. Write $\mathcal{F} = \widetilde M$ for some $B$-module $M$. By
Lemma \ref{divisors-lemma-weakly-associated-affine-open}
the weakly associated points of $\mathcal{F}$ correspond exactly to the
weakly associated primes of $M$. Similarly, the weakly associated points
of $f_*\mathcal{F}$ correspond exactly to the weakly associated primes
of $M$ as an $A$-module. Hence the lemma follows from
Algebra, Lemma \ref{algebra-lemma-weakly-ass-finite-ring-map}.
\end{proof}

\begin{lemma}[Weakly ass pullback]
\label{divisors-lemma-weakly-ass-pullback}
\source{stacks:05F0}
\href{https://stacks.math.columbia.edu/tag/05F0}{\texttt{Stacks tag 05F0}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes. Let $\mathcal{G}$ be a
quasi-coherent $\mathcal{O}_S$-module. Let $x \in X$ with $s = f(x)$.
If $f$ is flat at $x$, the point $x$ is a generic point of the fibre $X_s$, and
$s \in \text{WeakAss}_S(\mathcal{G})$, then
$x \in \text{WeakAss}(f^*\mathcal{G})$.
\end{lemma}

\begin{proof}
Let $A = \mathcal{O}_{S, s}$, $B = \mathcal{O}_{X, x}$, and
$M = \mathcal{G}_s$. Let $m \in M$ be an element whose annihilator
$I = \{a \in A \mid am = 0\}$ has radical $\mathfrak m_A$. Then
$m \otimes 1$ has annihilator $I B$ as $A \to B$ is
faithfully flat. Thus it suffices to see that $\sqrt{I B} = \mathfrak m_B$.
This follows from the fact that the maximal ideal of $B/\mathfrak m_AB$
is locally nilpotent (see
Algebra, Lemma \ref{algebra-lemma-minimal-prime-reduced-ring})
and the assumption that $\sqrt{I} = \mathfrak m_A$.
Some details omitted.
\end{proof}

\begin{lemma}[Weakly ass change fields]
\label{divisors-lemma-weakly-ass-change-fields}
\source{stacks:0CUC}
\href{https://stacks.math.columbia.edu/tag/0CUC}{\texttt{Stacks tag 0CUC}}
\group{divisors}

Let $K/k$ be a field extension. Let $X$ be a scheme over $k$.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Let $y \in X_K$ with image $x \in X$. If $y$ is a weakly
associated point of the pullback $\mathcal{F}_K$, then $x$
is a weakly associated point of $\mathcal{F}$.
\end{lemma}

\begin{proof}
This is the translation of
Algebra, Lemma \ref{algebra-lemma-weakly-ass-change-fields}
into the language of schemes.
\end{proof}

Here is a simple lemma where we find that pushforwards often have
depth at least 2.

\begin{lemma}[Depth pushforward]
\label{divisors-lemma-depth-pushforward}
\source{stacks:0EY0}
\href{https://stacks.math.columbia.edu/tag/0EY0}{\texttt{Stacks tag 0EY0}}
\group{divisors}

Let $f : X \to S$ be a quasi-compact and quasi-separated morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Let $s \in S$.
\begin{enumerate}
\item If $s \not \in f(X)$, then $s$ is not weakly associated
to $f_*\mathcal{F}$.
\item If $s \not \in f(X)$ and $\mathcal{O}_{S, s}$ is Noetherian,
then $s$ is not associated to $f_*\mathcal{F}$.
\item If $s \not \in f(X)$, $(f_*\mathcal{F})_s$ is a finite
$\mathcal{O}_{S, s}$-module, and $\mathcal{O}_{S, s}$
is Noetherian, then $\text{depth}((f_*\mathcal{F})_s) \geq 2$.
\item If $\mathcal{F}$ is flat over $S$ and $a \in \mathfrak m_s$
is a nonzerodivisor, then $a$ is a nonzerodivisor on $(f_*\mathcal{F})_s$.
\item If $\mathcal{F}$ is flat over $S$ and $a, b \in \mathfrak m_s$
is a regular sequence, then $a$ is a nonzerodivisor on $(f_*\mathcal{F})_s$
and $b$ is a nonzerodivisor on $(f_*\mathcal{F})_s/a(f_*\mathcal{F})_s$.
\item If $\mathcal{F}$ is flat over $S$ and $(f_*\mathcal{F})_s$
is a finite $\mathcal{O}_{S, s}$-module, then
$\text{depth}((f_*\mathcal{F})_s) \geq
\min(2, \text{depth}(\mathcal{O}_{S, s}))$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{divisors-lemma-weakass-pushforward, divisors-lemma-ass-weakly-ass}

Part (1) is Lemma \ref{divisors-lemma-weakass-pushforward}.
Part (2) follows from (1) and Lemma \ref{divisors-lemma-ass-weakly-ass}.

\medskip\noindent
Proof of part (3). To show the depth is $\geq 2$ it suffices to show that
$\Hom_{\mathcal{O}_{S, s}}(\kappa(s), (f_*\mathcal{F})_s) = 0$ and
$\Ext^1_{\mathcal{O}_{S, s}}(\kappa(s), (f_*\mathcal{F})_s) = 0$, see
Algebra, Lemma \ref{algebra-lemma-depth-ext}.
Using the exact sequence
$0 \to \mathfrak m_s \to \mathcal{O}_{S, s} \to \kappa(s) \to 0$
it suffices to prove that the map
$$
\Hom_{\mathcal{O}_{S, s}}(\mathcal{O}_{S, s}, (f_*\mathcal{F})_s)
\to
\Hom_{\mathcal{O}_{S, s}}(\mathfrak m_s, (f_*\mathcal{F})_s)
$$
is an isomorphism. By flat base change (Cohomology of Schemes, Lemma
\ref{coherent-lemma-flat-base-change-cohomology})
we may replace $S$ by
$\Spec(\mathcal{O}_{S, s})$ and $X$ by $\Spec(\mathcal{O}_{S, s}) \times_S X$.
Denote $\mathfrak m \subset \mathcal{O}_S$ the ideal sheaf of $s$.
Then we see that
$$
\Hom_{\mathcal{O}_{S, s}}(\mathfrak m_s, (f_*\mathcal{F})_s) =
\Hom_{\mathcal{O}_S}(\mathfrak m, f_*\mathcal{F}) =
\Hom_{\mathcal{O}_X}(f^*\mathfrak m, \mathcal{F})
$$
the first equality because $S$ is local with closed point $s$
and the second equality
by adjunction for $f^*, f_*$ on quasi-coherent modules. However, since
$s \not \in f(X)$ we see that $f^*\mathfrak m = \mathcal{O}_X$.
Working backwards through the arguments we get the desired equality.

\medskip\noindent
For the proof of (4), (5), and (6) we use flat base change
(Cohomology of Schemes, Lemma
\ref{coherent-lemma-flat-base-change-cohomology})
to reduce to the case where $S$ is the spectrum of
$\mathcal{O}_{S, s}$.
Then a nonzerodivisor $a \in \mathcal{O}_{S, s}$
deterimines a short exact sequence
$$
0 \to \mathcal{O}_S \xrightarrow{a} \mathcal{O}_S \to
\mathcal{O}_S/a \mathcal{O}_S \to 0
$$
Since $\mathcal{F}$ is flat over $S$, we obtain an exact sequence
$$
0 \to \mathcal{F} \xrightarrow{a} \mathcal{F} \to
\mathcal{F}/a\mathcal{F} \to 0
$$
Pushing forward we obtain an exact sequence
$$
0 \to f_*\mathcal{F} \xrightarrow{a} f_*\mathcal{F} \to
f_*(\mathcal{F}/a\mathcal{F})
$$
This proves (4) and it shows that
$f_*\mathcal{F}/ af_*\mathcal{F} \subset f_*(\mathcal{F}/a\mathcal{F})$.
If $b$ is a nonzerodivisor on
$\mathcal{O}_{S, s}/a\mathcal{O}_{S, s}$, then the exact same argument shows
$b : \mathcal{F}/a\mathcal{F} \to \mathcal{F}/a\mathcal{F}$
is injective. Pushing forward we conclude
$$
b : f_*(\mathcal{F}/a\mathcal{F}) \to f_*(\mathcal{F}/a\mathcal{F})
$$
is injective and hence also
$b : f_*\mathcal{F}/ af_*\mathcal{F} \to f_*\mathcal{F}/ af_*\mathcal{F}$
is injective. This proves (5). Part (6) follows from
(4) and (5) and the definitions.
\end{proof}

\section{Relative assassin}
\label{divisors-section-relative-assassin}
Let $A \to B$ be a ring map. Let $N$ be a $B$-module. Recall that
a prime $\mathfrak q \subset B$ is said to be in the relative assassin
of $N$ over $B/A$ if $\mathfrak q$ is an associated prime of
$N \otimes_A \kappa(\mathfrak p)$. Here $\mathfrak p = A \cap \mathfrak q$.
See Algebra, Definition \ref{algebra-definition-relative-assassin}.
Here is the definition of the relative assassin for quasi-coherent
sheaves over a morphism of schemes.

\begin{definition}[Relative assassin]
\label{divisors-definition-relative-assassin}
\source{stacks:05AT}
\href{https://stacks.math.columbia.edu/tag/05AT}{\texttt{Stacks tag 05AT}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
The {\it relative assassin of $\mathcal{F}$ in $X$ over $S$}
is the set
$$
\text{Ass}_{X/S}(\mathcal{F}) =
\bigcup\nolimits_{s \in S} \text{Ass}_{X_s}(\mathcal{F}_s)
$$
where $\mathcal{F}_s = (X_s \to X)^*\mathcal{F}$ is the restriction
of $\mathcal{F}$ to the fibre of $f$ at $s$.
\end{definition}

Again there is a caveat that this is best used when the fibres of $f$
are locally Noetherian and $\mathcal{F}$ is of finite type. In the general
case we should probably use the relative weak assassin (defined in the next
section). Let us link the scheme theoretic notion with the algebraic notion
on affine opens; note that this correspondence works perfectly only
for morphisms of schemes whose fibres are locally Noetherian.

\begin{lemma}[Relative assassin affine open]
\label{divisors-lemma-relative-assassin-affine-open}
\source{stacks:0CU5}
\href{https://stacks.math.columbia.edu/tag/0CU5}{\texttt{Stacks tag 0CU5}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $U \subset X$ and $V \subset S$ be affine opens
with $f(U) \subset V$. Write $U = \Spec(A)$, $V = \Spec(R)$, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
Then
$$
\mathfrak p \in \text{Ass}_{A/R}(M) \Rightarrow
x \in \text{Ass}_{X/S}(\mathcal{F})
$$
If all fibres $X_s$ of $f$ are locally Noetherian, then
$\mathfrak p \in \text{Ass}_{A/R}(M) \Leftrightarrow
x \in \text{Ass}_{X/S}(\mathcal{F})$
for all pairs $(\mathfrak p, x)$ as above.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-associated-affine-open}

The set $\text{Ass}_{A/R}(M)$ is defined in
Algebra, Definition \ref{algebra-definition-relative-assassin}.
Choose a pair $(\mathfrak p, x)$. Let $s = f(x)$.
Let $\mathfrak r \subset R$ be the prime lying under $\mathfrak p$,
i.e., the prime corresponding to $s$.
Let $\mathfrak p' \subset A \otimes_R \kappa(\mathfrak r)$
be the prime whose inverse image is $\mathfrak p$, i.e.,
the prime corresponding to $x$ viewed as a point of its fibre $X_s$.
Then $\mathfrak p \in \text{Ass}_{A/R}(M)$ if and only if
$\mathfrak p'$ is an associated prime of
$M \otimes_R \kappa(\mathfrak r)$, see
Algebra, Lemma \ref{algebra-lemma-compare-relative-assassins}.
Note that the ring $A \otimes_R \kappa(\mathfrak r)$ corresponds to $U_s$
and the module $M \otimes_R \kappa(\mathfrak r)$ corresponds to the
quasi-coherent sheaf $\mathcal{F}_s|_{U_s}$.
Hence $x$ is an associated point of $\mathcal{F}_s$
by Lemma \ref{divisors-lemma-associated-affine-open}.
The reverse implication holds if $\mathfrak p'$ is finitely generated
which is how the last sentence is seen to be true.
\end{proof}

\begin{lemma}[Base change relative assassin]
\label{divisors-lemma-base-change-relative-assassin}
\source{stacks:05DC}
\href{https://stacks.math.columbia.edu/tag/05DC}{\texttt{Stacks tag 05DC}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Let $g : S' \to S$ be a morphism of schemes.
Consider the base change diagram
$$
\begin{array}{cc}X' \downarrow\underset{g'}{\longrightarrow} & X \downarrow \\ S' \overset{g}{\longrightarrow} & S\end{array}
$$
and set $\mathcal{F}' = (g')^*\mathcal{F}$. Let $x' \in X'$ be a point
with images $x \in X$, $s' \in S'$ and $s \in S$.
Assume $f$ locally of finite type.
Then $x' \in \text{Ass}_{X'/S'}(\mathcal{F}')$ if and only if
$x \in \text{Ass}_{X/S}(\mathcal{F})$ and $x'$ corresponds to
a generic point of an irreducible component of
$\Spec(\kappa(s') \otimes_{\kappa(s)} \kappa(x))$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-bourbaki}

Consider the morphism $X'_{s'} \to X_s$ of fibres. As
$X_{s'} = X_s \times_{\Spec(\kappa(s))} \Spec(\kappa(s'))$
this is a flat morphism. Moreover $\mathcal{F}'_{s'}$ is the pullback
of $\mathcal{F}_s$ via this morphism. As $X_s$ is locally of finite
type over the Noetherian scheme $\Spec(\kappa(s))$ we have that
$X_s$ is locally Noetherian, see
Morphisms, Lemma \ref{morphisms-lemma-finite-type-noetherian}.
Thus we may apply
Lemma \ref{divisors-lemma-bourbaki}
and we see that
$$
\text{Ass}_{X'_{s'}}(\mathcal{F}'_{s'}) =
\bigcup\nolimits_{x \in \text{Ass}(\mathcal{F}_s)} \text{Ass}((X'_{s'})_x).
$$
Thus to prove the lemma it suffices to show that the associated points
of the fibre $(X'_{s'})_x$ of the morphism $X'_{s'} \to X_s$ over $x$
are its generic points. Note that
$(X'_{s'})_x = \Spec(\kappa(s') \otimes_{\kappa(s)} \kappa(x))$
as schemes. By
Algebra, Lemma \ref{algebra-lemma-tensor-fields-CM}
the ring $\kappa(s') \otimes_{\kappa(s)} \kappa(x)$ is a Noetherian
Cohen-Macaulay ring. Hence its associated primes are its minimal primes, see
Algebra, Proposition \ref{algebra-proposition-minimal-primes-associated-primes}
(minimal primes are associated) and
Algebra, Lemma \ref{algebra-lemma-criterion-no-embedded-primes}
(no embedded primes).
\end{proof}

\begin{remark}[Base change relative assassin]
\label{divisors-remark-base-change-relative-assassin}
\source{stacks:05KL}
\href{https://stacks.math.columbia.edu/tag/05KL}{\texttt{Stacks tag 05KL}}
\group{divisors}

\uses{divisors-lemma-base-change-relative-assassin}
With notation and assumptions as in
Lemma \ref{divisors-lemma-base-change-relative-assassin}
we see that it is always the case that
$(g')^{-1}(\text{Ass}_{X/S}(\mathcal{F})) \supset
\text{Ass}_{X'/S'}(\mathcal{F}')$.
If the morphism $S' \to S$ is locally quasi-finite, then we actually have
$$
(g')^{-1}(\text{Ass}_{X/S}(\mathcal{F}))
=
\text{Ass}_{X'/S'}(\mathcal{F}')
$$
because in this case the field extensions $\kappa(s')/\kappa(s)$
are always finite. In fact, this holds more generally for any morphism
$g : S' \to S$ such that all the field extensions
$\kappa(s')/\kappa(s)$ are algebraic, because in this case all
prime ideals of $\kappa(s') \otimes_{\kappa(s)} \kappa(x)$ are
maximal (and minimal) primes, see
Algebra, Lemma \ref{algebra-lemma-integral-over-field}.
\end{remark}

\section{Relative weak assassin}
\label{divisors-section-relative-weak-assassin}
\begin{definition}[Relative weak assassin]
\label{divisors-definition-relative-weak-assassin}
\source{stacks:05AV}
\href{https://stacks.math.columbia.edu/tag/05AV}{\texttt{Stacks tag 05AV}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
The {\it relative weak assassin of $\mathcal{F}$ in $X$ over $S$}
is the set
$$
\text{WeakAss}_{X/S}(\mathcal{F}) =
\bigcup\nolimits_{s \in S} \text{WeakAss}(\mathcal{F}_s)
$$
where $\mathcal{F}_s = (X_s \to X)^*\mathcal{F}$ is the restriction
of $\mathcal{F}$ to the fibre of $f$ at $s$.
\end{definition}

\begin{lemma}[Relative weak assassin assassin finite type]
\label{divisors-lemma-relative-weak-assassin-assassin-finite-type}
\source{stacks:05F2}
\href{https://stacks.math.columbia.edu/tag/05F2}{\texttt{Stacks tag 05F2}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes which is locally of finite type.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
Then $\text{WeakAss}_{X/S}(\mathcal{F}) = \text{Ass}_{X/S}(\mathcal{F})$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-ass-weakly-ass}

This is true because the fibres of $f$ are locally Noetherian schemes,
and associated and weakly associated points agree on locally Noetherian
schemes, see
Lemma \ref{divisors-lemma-ass-weakly-ass}.
\end{proof}

\begin{lemma}[Relative weak assassin finite]
\label{divisors-lemma-relative-weak-assassin-finite}
\source{stacks:0CUD}
\href{https://stacks.math.columbia.edu/tag/0CUD}{\texttt{Stacks tag 0CUD}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes.
Let $i : Z \to X$ be a finite morphism.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_Z$-module.
Then $\text{WeakAss}_{X/S}(i_*\mathcal{F}) =
i(\text{WeakAss}_{Z/S}(\mathcal{F}))$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-weakly-associated-finite}

Let $i_s : Z_s \to X_s$ be the induced morphism between fibres.
Then $(i_*\mathcal{F})_s = i_{s, *}(\mathcal{F}_s)$ by
Cohomology of Schemes, Lemma \ref{coherent-lemma-affine-base-change}
and the fact that $i$ is affine. Hence
we may apply Lemma \ref{divisors-lemma-weakly-associated-finite} to conclude.
\end{proof}

\section{Fitting ideals}
\label{divisors-section-fitting-ideals}
This section is the continuation of the discussion in
More on Algebra, Section \ref{more-algebra-section-fitting-ideals}.
Let $S$ be a scheme. Let $\mathcal{F}$ be a
finite type quasi-coherent $\mathcal{O}_S$-module.
In this situation we can construct the Fitting ideals
$$
0 = \text{Fit}_{-1}(\mathcal{F}) \subset \text{Fit}_0(\mathcal{F}) \subset
\text{Fit}_1(\mathcal{F}) \subset \ldots \subset \mathcal{O}_S
$$
as the sequence of quasi-coherent ideals characterized by the following
property: for every affine open $U = \Spec(A)$ of $S$ if $\mathcal{F}|_U$
corresponds to the $A$-module $M$, then $\text{Fit}_i(\mathcal{F})|_U$
corresponds to the ideal $\text{Fit}_i(M) \subset A$.
This is well defined and a quasi-coherent sheaf of ideals because
if $f \in A$, then the $i$th Fitting ideal of $M_f$ over $A_f$
is equal to $\text{Fit}_i(M) A_f$ by
More on Algebra, Lemma \ref{more-algebra-lemma-fitting-ideal-basics}.

\medskip\noindent
Alternatively, we can construct the Fitting ideals in terms of local
presentations of $\mathcal{F}$. Namely, if $U \subset X$ is open, and
$$
\bigoplus\nolimits_{i \in I} \mathcal{O}_U \to
\mathcal{O}_U^{\oplus n} \to \mathcal{F}|_U \to 0
$$
is a presentation of $\mathcal{F}$ over $U$, then
$\text{Fit}_r(\mathcal{F})|_U$ is generated by the
$(n - r) \times (n - r)$-minors
of the matrix defining the first arrow of the presentation.
This is compatible with the construction above because this
is how the Fitting ideal of a module over a ring is actually defined.
Some details omitted.

\begin{lemma}[Base change fitting ideal]
\label{divisors-lemma-base-change-fitting-ideal}
\source{stacks:0C3D}
\href{https://stacks.math.columbia.edu/tag/0C3D}{\texttt{Stacks tag 0C3D}}
\group{divisors}

Let $f : T \to S$ be a morphism of schemes.
Let $\mathcal{F}$ be a finite type quasi-coherent $\mathcal{O}_S$-module.
Then
$f^{-1}\text{Fit}_i(\mathcal{F}) \cdot \mathcal{O}_T =
\text{Fit}_i(f^*\mathcal{F})$.
\end{lemma}

\begin{proof}
Follows immediately from More on Algebra, Lemma
\ref{more-algebra-lemma-fitting-ideal-basics} part (3).
\end{proof}

\begin{lemma}[Fitting ideal of finitely presented]
\label{divisors-lemma-fitting-ideal-of-finitely-presented}
\source{stacks:0C3E}
\href{https://stacks.math.columbia.edu/tag/0C3E}{\texttt{Stacks tag 0C3E}}
\group{divisors}

Let $S$ be a scheme.
Let $\mathcal{F}$ be a finitely presented $\mathcal{O}_S$-module.
Then $\text{Fit}_r(\mathcal{F})$ is a quasi-coherent ideal of finite type.
\end{lemma}

\begin{proof}
Follows immediately from More on Algebra, Lemma
\ref{more-algebra-lemma-fitting-ideal-basics} part (4).
\end{proof}

\begin{lemma}[On subscheme cut out by Fit 0]
\label{divisors-lemma-on-subscheme-cut-out-by-Fit-0}
\source{stacks:0CYX}
\href{https://stacks.math.columbia.edu/tag/0CYX}{\texttt{Stacks tag 0CYX}}
\group{divisors}

Let $S$ be a scheme.
Let $\mathcal{F}$ be a finite type, quasi-coherent $\mathcal{O}_S$-module.
Let $Z_0 \subset S$ be the closed subscheme cut out by
$\text{Fit}_0(\mathcal{F})$.
Let $Z \subset S$ be the scheme theoretic support of $\mathcal{F}$.
Then
\begin{enumerate}
\item $Z \subset Z_0 \subset S$ as closed subschemes,
\item $Z = Z_0 = \text{Supp}(\mathcal{F})$ as closed subsets,
\item there exists a finite type, quasi-coherent $\mathcal{O}_{Z_0}$-module
$\mathcal{G}_0$ with
$$
(Z_0 \to X)_*\mathcal{G}_0 = \mathcal{F}.
$$
\end{enumerate}
\end{lemma}

\begin{proof}
Recall that $Z$ is locally cut out by the annihilator of $\mathcal{F}$, see
Morphisms, Definition \ref{morphisms-definition-scheme-theoretic-support}
(which uses Morphisms, Lemma \ref{morphisms-lemma-scheme-theoretic-support}
to define $Z$). Hence we see that $Z \subset Z_0$ scheme theoretically
by More on Algebra, Lemma
\ref{more-algebra-lemma-fitting-ideal-basics} part (6).
On the other hand we have $Z = \text{Supp}(\mathcal{F})$
set theoretically by
Morphisms, Lemma \ref{morphisms-lemma-scheme-theoretic-support}
and we have $Z_0 = Z$ set theoretically by
More on Algebra, Lemma
\ref{more-algebra-lemma-fitting-ideal-basics} part (7).
Finally, to get $\mathcal{G}_0$ as in part (3) we can either use
that we have $\mathcal{G}$ on $Z$ as in
Morphisms, Lemma \ref{morphisms-lemma-scheme-theoretic-support}
and set $\mathcal{G}_0 = (Z \to Z_0)_*\mathcal{G}$
or we can use Morphisms, Lemma \ref{morphisms-lemma-i-star-equivalence}
and the fact that $\text{Fit}_0(\mathcal{F})$ annihilates
$\mathcal{F}$ by More on Algebra, Lemma
\ref{more-algebra-lemma-fitting-ideal-basics} part (6).
\end{proof}

\begin{lemma}[Fitting ideal generate locally]
\label{divisors-lemma-fitting-ideal-generate-locally}
\source{stacks:0C3F}
\href{https://stacks.math.columbia.edu/tag/0C3F}{\texttt{Stacks tag 0C3F}}
\group{divisors}

Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type, quasi-coherent
$\mathcal{O}_S$-module. Let $s \in S$. Then $\mathcal{F}$ can be
generated by $r$ elements in a neighbourhood of $s$ if and only
if $\text{Fit}_r(\mathcal{F})_s = \mathcal{O}_{S, s}$.
\end{lemma}

\begin{proof}
Follows immediately from
More on Algebra, Lemma \ref{more-algebra-lemma-fitting-ideal-generate-locally}.
\end{proof}

\begin{lemma}[Fitting ideal finite locally free]
\label{divisors-lemma-fitting-ideal-finite-locally-free}
\source{stacks:0C3G}
\href{https://stacks.math.columbia.edu/tag/0C3G}{\texttt{Stacks tag 0C3G}}
\group{divisors}

Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type, quasi-coherent
$\mathcal{O}_S$-module. Let $r \geq 0$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is finite locally free of rank $r$
\item $\text{Fit}_{r - 1}(\mathcal{F}) = 0$ and
$\text{Fit}_r(\mathcal{F}) = \mathcal{O}_S$, and
\item $\text{Fit}_k(\mathcal{F}) = 0$ for $k < r$ and
$\text{Fit}_k(\mathcal{F}) = \mathcal{O}_S$ for $k \geq r$.
\end{enumerate}
\end{lemma}

\begin{proof}
Follows immediately from
More on Algebra, Lemma
\ref{more-algebra-lemma-fitting-ideal-finite-locally-free}.
\end{proof}

\begin{lemma}[Locally free rank r pullback]
\label{divisors-lemma-locally-free-rank-r-pullback}
\source{stacks:05P8}
\href{https://stacks.math.columbia.edu/tag/05P8}{\texttt{Stacks tag 05P8}}
\group{divisors}

Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type, quasi-coherent
$\mathcal{O}_S$-module. The closed subschemes
$$
S = Z_{-1} \supset Z_0 \supset Z_1 \supset Z_2 \ldots
$$
defined by the Fitting ideals of $\mathcal{F}$ have the following
properties
\begin{enumerate}
\item The intersection $\bigcap Z_r$ is empty.
\item The functor $(\Sch/S)^{opp} \to \textit{Sets}$ defined by the rule
$$
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ is locally generated by }
\leq r\text{ sections} \\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
is representable by the open subscheme $S \setminus Z_r$.
\item The functor $F_r : (\Sch/S)^{opp} \to \textit{Sets}$ defined by the rule
$$
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ locally free rank }r\\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
is representable by the locally closed subscheme $Z_{r - 1} \setminus Z_r$
of $S$.
\end{enumerate}
If $\mathcal{F}$ is of finite presentation, then
$Z_r \to S$, $S \setminus Z_r \to S$, and $Z_{r - 1} \setminus Z_r \to S$
are of finite presentation.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-base-change-fitting-ideal, divisors-lemma-fitting-ideal-generate-locally, divisors-lemma-fitting-ideal-finite-locally-free, divisors-lemma-fitting-ideal-of-finitely-presented}

Part (1) is true because over every affine open $U$ there is an integer $n$
such that $\text{Fit}_n(\mathcal{F})|_U = \mathcal{O}_U$. Namely, we can
take $n$ to be the number of generators of $\mathcal{F}$ over $U$, see
More on Algebra, Section \ref{more-algebra-section-fitting-ideals}.

\medskip\noindent
For any morphism $g : T \to S$ we see from
Lemmas \ref{divisors-lemma-base-change-fitting-ideal} and
\ref{divisors-lemma-fitting-ideal-generate-locally}
that $\mathcal{F}_T$ is locally generated by $\leq r$ sections if and only if
$\text{Fit}_r(\mathcal{F}) \cdot \mathcal{O}_T = \mathcal{O}_T$.
This proves (2).

\medskip\noindent
For any morphism $g : T \to S$ we see from
Lemmas \ref{divisors-lemma-base-change-fitting-ideal} and
\ref{divisors-lemma-fitting-ideal-finite-locally-free}
that $\mathcal{F}_T$ is free of rank $r$ if and only if
$\text{Fit}_r(\mathcal{F}) \cdot \mathcal{O}_T = \mathcal{O}_T$ and
$\text{Fit}_{r - 1}(\mathcal{F}) \cdot \mathcal{O}_T = 0$.
This proves (3).

\medskip\noindent
Assume $\mathcal{F}$ is of finite presentation. Then each of the morphisms
$Z_r \to S$ is of finite presentation as $\text{Fit}_r(\mathcal{F})$
is of finite type (Lemma \ref{divisors-lemma-fitting-ideal-of-finitely-presented} and
Morphisms, Lemma \ref{morphisms-lemma-closed-immersion-finite-presentation}).
This implies that $Z_{r - 1} \setminus Z_r$ is a retrocompact open in $Z_r$
(Properties, Lemma \ref{properties-lemma-quasi-coherent-finite-type-ideals})
and hence the morphism $Z_{r - 1} \setminus Z_r \to Z_r$
is of finite presentation as well.
\end{proof}

Lemma \ref{divisors-lemma-locally-free-rank-r-pullback} notwithstanding
the following lemma does not hold if $\mathcal{F}$ is a finite type
quasi-coherent module. Namely, the stratification still exists but
it isn't true that it represents the functor $F_{flat}$ in general.

\begin{lemma}[Finite presentation module]
\label{divisors-lemma-finite-presentation-module}
\source{stacks:05P9}
\href{https://stacks.math.columbia.edu/tag/05P9}{\texttt{Stacks tag 05P9}}
\group{divisors}

\uses{divisors-lemma-locally-free-rank-r-pullback}
Let $S$ be a scheme. Let $\mathcal{F}$ be an $\mathcal{O}_S$-module
of finite presentation. Let $S = Z_{-1} \supset Z_0 \supset Z_1 \supset \ldots$
be as in Lemma \ref{divisors-lemma-locally-free-rank-r-pullback}.
Set $S_r = Z_{r - 1} \setminus Z_r$.
Then $S' = \coprod_{r \geq 0} S_r$ represents the functor
$$
F_{flat} : \Sch/S \longrightarrow \textit{Sets},\quad\quad
T \longmapsto
\left\{
\begin{matrix}
\{*\} & \text{if }\mathcal{F}_T\text{ flat over }T\\
\emptyset & \text{otherwise}
\end{matrix}
\right.
$$
Moreover, $\mathcal{F}|_{S_r}$ is locally free of rank $r$ and the
morphisms $S_r \to S$ and $S' \to S$ are of finite presentation.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-locally-free-rank-r-pullback}

Suppose that $g : T \to S$ is a morphism of schemes such that the pullback
$\mathcal{F}_T = g^*\mathcal{F}$ is flat. Then $\mathcal{F}_T$ is a flat
$\mathcal{O}_T$-module of finite presentation. Hence
$\mathcal{F}_T$ is finite locally free, see
Properties, Lemma \ref{properties-lemma-finite-locally-free}.
Thus $T = \coprod_{r \geq 0} T_r$, where $\mathcal{F}_T|_{T_r}$ is locally
free of rank $r$. This implies that
$$
F_{flat} = \coprod\nolimits_{r \geq 0} F_r
$$
in the category of Zariski sheaves on $\Sch/S$ where $F_r$ is as in
Lemma \ref{divisors-lemma-locally-free-rank-r-pullback}. It follows
that $F_{flat}$ is represented by
$\coprod_{r \geq 0} (Z_{r - 1} \setminus Z_r)$ where
$Z_r$ is as in
Lemma \ref{divisors-lemma-locally-free-rank-r-pullback}.
The other statements also follow from the lemma.
\end{proof}

\begin{example}[Not fp MB]
\label{divisors-example-not-fp-MB}
\source{stacks:0FJ0}
\href{https://stacks.math.columbia.edu/tag/0FJ0}{\texttt{Stacks tag 0FJ0}}
\group{divisors}

\uses{divisors-lemma-locally-free-rank-r-pullback, divisors-lemma-finite-presentation-module}
Let $R = \prod_{n \in \mathbf{N}} \mathbf{F}_2$. Let $I \subset R$
be the ideal of elements $a = (a_n)_{n \in \mathbf{N}}$ almost all of whose
components are zero. Let $\mathfrak m$ be a maximal ideal containing $I$.
Then $M = R/\mathfrak m$ is a finite flat $R$-module, because $R$ is absolutely
flat (More on Algebra, Lemma
\ref{more-algebra-lemma-product-fields-absolutely-flat}).
Set $S = \Spec(R)$ and $\mathcal{F} = \widetilde{M}$.
The closed subschemes of Lemma \ref{divisors-lemma-locally-free-rank-r-pullback} are
$S = Z_{-1}$, $Z_0 = \Spec(R/\mathfrak m)$, and $Z_i = \emptyset$ for $i > 0$.
But $\text{id} : S \to S$ does not factor through
$(S \setminus Z_0) \amalg Z_0$ because $\mathfrak m$ is a nonisolated
point of $S$. Thus
Lemma \ref{divisors-lemma-finite-presentation-module}
does not hold for finite type modules.
\end{example}

\section{The singular locus of a morphism}
\label{divisors-section-singular-locus-morphism}
Let $f : X \to S$ be a finite type morphism of schemes. The set $U$ of points
where $f$ is smooth is an open of $X$
(by Morphisms, Definition \ref{morphisms-definition-smooth}).
In many situations it is useful to have a canonical closed
subscheme $\text{Sing}(f) \subset X$ whose complement is $U$
and whose formation commutes with arbitrary change of base.

\medskip\noindent
If $f$ is of finite presentation, then one choice would be to consider the
closed subscheme $Z$ cut out by functions which are affine locally
``strictly standard'' in the sense of
Smoothing Ring Maps, Definition \ref{smoothing-definition-strictly-standard}.
It follows from
Smoothing Ring Maps, Lemma \ref{smoothing-lemma-strictly-standard-base-change}
that if $f' : X' \to S'$ is the base change of $f$ by a morphism
$S' \to S$, then $Z' \subset S' \times_S Z$ where $Z'$ is the
closed subscheme of $X'$ cut out by functions which are affine
locally strictly standard. However, equality isn't clear.
The notion of a strictly standard element was useful in the chapter on
Popescu's theorem. The closed subscheme defined by these elements is
(as far as we know) not used in the literature\footnote{If $f$ is a
local complete intersection morphism
(More on Morphisms, Definition \ref{more-morphisms-definition-lci})
then the closed subscheme cut out by the locally strictly standard
elements is the correct thing to look at.}.

\medskip\noindent
If $f$ is flat, of finite presentation, and the fibres of $f$
all are equidimensional of dimension $d$, then the $d$th fitting ideal
of $\Omega_{X/S}$ is used to get a good closed subscheme. For any
morphism of finite type the closed subschemes of $X$ defined by the
fitting ideals of $\Omega_{X/S}$ define a stratification of $X$
in terms of the rank of $\Omega_{X/S}$  whose formation commutes with
base change. This can be helpful; it is related to embedding dimensions of
fibres, see Varieties, Section \ref{varieties-section-embedding-dimension}.

\begin{lemma}[Base change and fitting ideal omega]
\label{divisors-lemma-base-change-and-fitting-ideal-omega}
\source{stacks:0C3I}
\href{https://stacks.math.columbia.edu/tag/0C3I}{\texttt{Stacks tag 0C3I}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes which is locally of finite type.
Let $X = Z_{-1} \supset Z_0 \supset Z_1 \supset \ldots$
be the closed subschemes defined by the fitting ideals
of $\Omega_{X/S}$. Then the formation of $Z_i$ commutes
with arbitrary base change.
\end{lemma}

\begin{proof}
Observe that $\Omega_{X/S}$ is a finite type quasi-coherent
$\mathcal{O}_X$-module
(Morphisms, Lemma \ref{morphisms-lemma-finite-type-differentials})
hence the fitting ideals are defined. If $f' : X' \to S'$
is the base change of $f$ by $g : S' \to S$, then
$\Omega_{X'/S'} = (g')^*\Omega_{X/S}$ where $g' : X' \to X$
is the projection
(Morphisms, Lemma \ref{morphisms-lemma-base-change-differentials}).
Hence $(g')^{-1}\text{Fit}_i(\Omega_{X/S}) \cdot \mathcal{O}_{X'} =
\text{Fit}_i(\Omega_{X'/S'})$. This means that
$$
Z'_i = (g')^{-1}(Z_i) = Z_i \times_X X'
$$
scheme theoretically and this is the meaning of the statement of
the lemma.
\end{proof}

The $0$th fitting ideal of $\Omega$
cuts out the ``ramified locus'' of the morphism.

\begin{lemma}[Zero fitting ideal omega unramified]
\label{divisors-lemma-zero-fitting-ideal-omega-unramified}
\source{stacks:0C3J}
\href{https://stacks.math.columbia.edu/tag/0C3J}{\texttt{Stacks tag 0C3J}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes which is locally of finite type.
The closed subscheme $Z \subset X$ cut out by the $0$th fitting ideal of
$\Omega_{X/S}$ is exactly the set of points where $f$ is not unramified.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-on-subscheme-cut-out-by-Fit-0}

By Lemma \ref{divisors-lemma-on-subscheme-cut-out-by-Fit-0} the complement of $Z$
is exactly the locus where $\Omega_{X/S}$ is zero. This is exactly
the set of points where $f$ is unramified by
Morphisms, Lemma \ref{morphisms-lemma-unramified-omega-zero}.
\end{proof}

\begin{lemma}[D fitting ideal omega smooth]
\label{divisors-lemma-d-fitting-ideal-omega-smooth}
\source{stacks:0C3K}
\href{https://stacks.math.columbia.edu/tag/0C3K}{\texttt{Stacks tag 0C3K}}
\group{divisors}

Let $f : X \to S$ be a morphism of schemes. Let $d \geq 0$ be an integer.
Assume
\begin{enumerate}
\item $f$ is flat,
\item $f$ is locally of finite presentation, and
\item every nonempty fibre of $f$ is equidimensional of dimension $d$.
\end{enumerate}
Let $Z \subset X$ be the closed subscheme cut out by the $d$th fitting
ideal of $\Omega_{X/S}$. Then $Z$ is exactly the set of points
where $f$ is not smooth.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-locally-free-rank-r-pullback}

By Lemma \ref{divisors-lemma-locally-free-rank-r-pullback} the complement of $Z$
is exactly the locus where $\Omega_{X/S}$ can be generated by at most
$d$ elements. Hence the lemma follows from
Morphisms, Lemma \ref{morphisms-lemma-smooth-at-point}.
\end{proof}

\section{Torsion free modules}
\label{divisors-section-torsion-free}
This section is the analogue of
More on Algebra, Section \ref{more-algebra-section-torsion-flat}
for quasi-coherent modules.

\begin{lemma}[Torsion sections]
\label{divisors-lemma-torsion-sections}
\source{stacks:0AXR}
\href{https://stacks.math.columbia.edu/tag/0AXR}{\texttt{Stacks tag 0AXR}}
\group{divisors}

Let $X$ be an integral scheme with generic point $\eta$. Let $\mathcal{F}$
be a quasi-coherent $\mathcal{O}_X$-module. Let $U \subset X$ be nonempty
open and $s \in \mathcal{F}(U)$. The following are equivalent
\begin{enumerate}
\item for some $x \in U$ the image of $s$ in $\mathcal{F}_x$ is torsion,
\item for all $x \in U$ the image of $s$ in $\mathcal{F}_x$ is torsion,
\item the image of $s$ in $\mathcal{F}_\eta$ is zero,
\item the image of $s$ in $j_*\mathcal{F}_\eta$ is zero, where $j : \eta \to X$
is the inclusion morphism.
\end{enumerate}
\end{lemma}

\begin{proof}
Omitted.
\end{proof}

\begin{definition}[Torsion]
\label{divisors-definition-torsion}
\source{stacks:0AVR}
\href{https://stacks.math.columbia.edu/tag/0AVR}{\texttt{Stacks tag 0AVR}}
\group{divisors}

\uses{divisors-lemma-torsion-sections}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module.
\begin{enumerate}
\item We say a local section of $\mathcal{F}$ is {\it torsion}
if it satisfies the equivalent conditions of Lemma \ref{divisors-lemma-torsion-sections}.
\item We say $\mathcal{F}$ is {\it torsion free} if every torsion section
of $\mathcal{F}$ is $0$.
\end{enumerate}
\end{definition}

Here is the obligatory lemma comparing this to the usual algebraic notion.

