into the language of schemes.
\end{proof}

\section{Ranks of modules}
\label{divisors-section-rank}
This section is the analogue of
More on Algebra, Section \ref{more-algebra-section-rank}
for quasi-coherent modules.
Recall that if $X$ is an integral scheme with generic point $\eta$,
then the local ring $\mathcal{O}_{X, \eta}$ is equal to the
residue field $\kappa(\eta)$, see
Morphisms, Lemma \ref{morphisms-lemma-integral-scheme-rational-functions}.

\begin{definition}[Rank]
\label{divisors-definition-rank}
\source{stacks:0HAF}
\href{https://stacks.math.columbia.edu/tag/0HAF}{\texttt{Stacks tag 0HAF}}
\group{divisors}

Let $X$ be an integral scheme with generic point $\eta$.
Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
The {\it rank} of $\mathcal{F}$ is $\dim_{\kappa(\eta)} \mathcal{F}_\eta$.
\end{definition}

This does not conflict with the defition of the rank of a locally free module
(in the case both definitions apply). It does not seem like a good idea
to define the rank of a quasi-coherent module if the scheme $X$
is not irreducible or if the local ring $\mathcal{O}_{X, \eta}$
at the generic point is not a field\footnote{If $X$ is irreducible and
$\mathcal{F}_\eta$ is free over $\mathcal{O}_{X, \eta}$ it would appear
natural to use the rank of this free module. Beware that some references
define rank using the length of $\mathcal{F}_\eta$.}

\begin{lemma}[Check rank on affines]
\label{divisors-lemma-check-rank-on-affines}
\source{stacks:0HAG}
\href{https://stacks.math.columbia.edu/tag/0HAG}{\texttt{Stacks tag 0HAG}}
\group{divisors}

