Then the conormal sheaf is $\mathcal{C}_{D/S} = \mathcal{I}_D|_D =
\mathcal{O}_S(-D)|_D$ and the normal sheaf is
$\mathcal{N}_{D/S} = \mathcal{O}_S(D)|_D$.
\end{lemma}

\begin{proof}
This follows from Morphisms, Lemma \ref{morphisms-lemma-affine-conormal}.
\end{proof}

\begin{lemma}[Ses add divisor]
\label{divisors-lemma-ses-add-divisor}
\source{stacks:0C4T}
\href{https://stacks.math.columbia.edu/tag/0C4T}{\texttt{Stacks tag 0C4T}}
\group{divisors}

\uses{divisors-lemma-difference-effective-Cartier-divisors}
Let $X$ be a scheme. Let $D, D' \subset X$ be effective Cartier divisors
with $D \subset D'$ and let $C \subset X$ be an effective Cartier divisor
such that $D' = D + C$ (which exists by
Lemma \ref{divisors-lemma-difference-effective-Cartier-divisors}).
Then there is a short exact sequence
$$
0 \to \mathcal{O}_X(-D)|_C \to \mathcal{O}_{D'} \to \mathcal{O}_D \to 0
$$
of $\mathcal{O}_X$-modules.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-characterize-effective-Cartier-divisor}

In the statement of the lemma and in the proof we use the equivalence of
Morphisms, Lemma \ref{morphisms-lemma-i-star-equivalence} to think of
quasi-coherent modules on closed subschemes of $X$
as quasi-coherent modules on $X$. Let $\mathcal{I}$ be the ideal
sheaf of $D$ in $D'$ and let $\mathcal{I}_D = \mathcal{O}_X(-D)$ be
the ideal sheaf of $D$ in $X$. Then there is a canonical surjection
$\mathcal{I}_D \to \mathcal{I}$.
Thus it suffices to show the kernel of this map is equal to
$\mathcal{I}_C\mathcal{I}_D$ (with obvious notation).
This can be checked locally, hence we may assume
$X = \Spec(A)$, $D = \Spec(A/fA)$ and $C = \Spec(A/gA)$ where
$f, g \in A$ are nonzerodivisors
(Lemma \ref{divisors-lemma-characterize-effective-Cartier-divisor}).
Then $\mathcal{I}_D$ corresponds to $fA$, the nonzerodivisor $fg \in A$
generates the ideal of $D'$, and $\mathcal{I}$ corresponds to $I = fA/fgA$.
Thus the result is clear.
\end{proof}

