Let $(X, \mathcal{O}_X)$ be a locally ringed space.
Let $\mathcal{L}$ be an invertible sheaf on $X$.
A global section $s \in \Gamma(X, \mathcal{L})$ is called a
{\it regular section} if the map $\mathcal{O}_X \to \mathcal{L}$,
$f \mapsto fs$ is injective.
\end{definition}

\begin{lemma}[Regular section structure sheaf]
\label{divisors-lemma-regular-section-structure-sheaf}
\source{stacks:01WZ}
\href{https://stacks.math.columbia.edu/tag/01WZ}{\texttt{Stacks tag 01WZ}}
