\begin{lemma}[Blow up and irreducible components]
\label{divisors-lemma-blow-up-and-irreducible-components}
\source{stacks:0BFM}
\href{https://stacks.math.columbia.edu/tag/0BFM}{\texttt{Stacks tag 0BFM}}
\group{divisors}

Let $X$ be a scheme. Let $Z \subset X$ be a closed subscheme.
Let $b : X' \to X$ be the blowing up of $X$ along $Z$. Then
$b$ induces an bijective map from the set of generic points
of irreducible components of $X'$ to the set of generic points of
irreducible components of $X$ which are not in $Z$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-blowing-up-gives-effective-Cartier-divisor, divisors-lemma-characterize-effective-Cartier-divisor}

The exceptional divisor $E \subset X'$ is an effective Cartier divisor
and $X' \setminus E \to X \setminus Z$ is an isomorphism, see
Lemma \ref{divisors-lemma-blowing-up-gives-effective-Cartier-divisor}.
Thus it suffices to show the following: given an effective
Cartier divisor $D \subset S$ of a scheme $S$ none of the
generic points of irreducible components of $S$ are contained in $D$.
To see this, we may replace $S$ by the members of an affine open
covering. Hence by Lemma \ref{divisors-lemma-characterize-effective-Cartier-divisor}
we may assume $S = \Spec(A)$ and $D = V(f)$ where $f \in A$
is a nonzerodivisor. Then we have to show $f$ is not contained
in any minimal prime ideal $\mathfrak p \subset A$.
If so, then $f$ would map to a nonzerodivisor contained
in the maximal ideal of $R_\mathfrak p$ which is a contradiction
with Algebra, Lemma \ref{algebra-lemma-minimal-prime-reduced-ring}.
\end{proof}

\begin{lemma}[Blow up pullback effective Cartier]
\label{divisors-lemma-blow-up-pullback-effective-Cartier}
\source{stacks:0809}
\href{https://stacks.math.columbia.edu/tag/0809}{\texttt{Stacks tag 0809}}
\group{divisors}

\uses{divisors-definition-pullback-effective-Cartier-divisor, divisors-definition-pullback-meromorphic-sections}
Let $X$ be a scheme. Let $b : X' \to X$ be a blowup of $X$ in a closed
subscheme. The pullback $b^{-1}D$ is defined
for all effective Cartier divisors $D \subset X$
and pullbacks of meromorphic functions are defined for $b$
(Definitions
\ref{divisors-definition-pullback-effective-Cartier-divisor} and
\ref{divisors-definition-pullback-meromorphic-sections}).
\end{lemma}

\begin{proof}
\uses{divisors-lemma-blowing-up-affine, divisors-lemma-characterize-effective-Cartier-divisor}

By Lemmas \ref{divisors-lemma-blowing-up-affine} and
\ref{divisors-lemma-characterize-effective-Cartier-divisor}
this reduces to the following algebra fact:
Let $A$ be a ring, $I \subset A$ an ideal, $a \in I$, and $x \in A$
a nonzerodivisor. Then the image of $x$ in $A[\frac{I}{a}]$ is a
nonzerodivisor. Namely, suppose that $x (y/a^n) = 0$ in $A[\frac{I}{a}]$.
Then $a^mxy = 0$ in $A$ for some $m$. Hence $a^my = 0$ as $x$ is a
nonzerodivisor. Whence $y/a^n$ is zero in $A[\frac{I}{a}]$ as desired.
\end{proof}

\begin{lemma}[Blowing up two ideals]
\label{divisors-lemma-blowing-up-two-ideals}
\source{stacks:080A}
\href{https://stacks.math.columbia.edu/tag/080A}{\texttt{Stacks tag 080A}}
\group{divisors}

Let $X$ be a scheme. Let $\mathcal{I}, \mathcal{J} \subset \mathcal{O}_X$
be quasi-coherent sheaves of ideals. Let $b : X' \to X$
be the blowing up of $X$ in $\mathcal{I}$. Let $b' : X'' \to X'$ be the
blowing up of $X'$ in $b^{-1}\mathcal{J} \mathcal{O}_{X'}$. Then $X'' \to X$
is canonically isomorphic to the blowing up of $X$ in $\mathcal{I}\mathcal{J}$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-blowing-up-gives-effective-Cartier-divisor, divisors-lemma-blow-up-pullback-effective-Cartier, divisors-lemma-universal-property-blowing-up, divisors-lemma-sum-closed-subschemes-effective-Cartier}

Let $E \subset X'$ be the exceptional divisor of $b$ which is an effective
Cartier divisor by
Lemma \ref{divisors-lemma-blowing-up-gives-effective-Cartier-divisor}.
Then $(b')^{-1}E$ is an effective Cartier divisor on $X''$ by
Lemma \ref{divisors-lemma-blow-up-pullback-effective-Cartier}.
Let $E' \subset X''$ be the exceptional divisor of $b'$ (also an effective
Cartier divisor). Consider the effective Cartier divisor
$E'' = E' + (b')^{-1}E$. By construction the ideal of $E''$ is
$(b \circ b')^{-1}\mathcal{I} (b \circ b')^{-1}\mathcal{J} \mathcal{O}_{X''}$.
Hence according to Lemma \ref{divisors-lemma-universal-property-blowing-up}
there is a canonical morphism from $X''$ to the blowup $c : Y \to X$
of $X$ in $\mathcal{I}\mathcal{J}$. Conversely, as $\mathcal{I}\mathcal{J}$
pulls back to an invertible ideal we see that
$c^{-1}\mathcal{I}\mathcal{O}_Y$ defines
an effective Cartier divisor, see
Lemma \ref{divisors-lemma-sum-closed-subschemes-effective-Cartier}.
Thus a morphism $c' : Y \to X'$ over $X$ by
Lemma \ref{divisors-lemma-universal-property-blowing-up}.
Then $(c')^{-1}b^{-1}\mathcal{J}\mathcal{O}_Y = c^{-1}\mathcal{J}\mathcal{O}_Y$
which also defines an effective Cartier divisor. Thus a morphism
$c'' : Y \to X''$ over $X'$. We omit the verification that this
morphism is inverse to the morphism $X'' \to Y$ constructed earlier.
\end{proof}

\begin{lemma}[Blowing up projective]
\label{divisors-lemma-blowing-up-projective}
\source{stacks:02NS}
\href{https://stacks.math.columbia.edu/tag/02NS}{\texttt{Stacks tag 02NS}}
\group{divisors}

Let $X$ be a scheme. Let $\mathcal{I} \subset \mathcal{O}_X$ be a
quasi-coherent sheaf of ideals. Let $b : X' \to X$ be the blowing up of $X$
in the ideal sheaf $\mathcal{I}$. If $\mathcal{I}$ is of finite type, then
\begin{enumerate}
\item $b : X' \to X$ is a projective morphism, and
\item $\mathcal{O}_{X'}(1)$ is a $b$-relatively ample invertible sheaf.
\end{enumerate}
\end{lemma}

\begin{proof}
The surjection of graded $\mathcal{O}_X$-algebras
$$
\text{Sym}_{\mathcal{O}_X}^*(\mathcal{I})
\longrightarrow
\bigoplus\nolimits_{d \geq 0} \mathcal{I}^d
$$
defines via Constructions, Lemma
\ref{constructions-lemma-surjective-generated-degree-1-map-relative-proj}
a closed immersion
$$
X' = \underline{\text{Proj}}_X (\bigoplus\nolimits_{d \geq 0} \mathcal{I}^d)
\longrightarrow
\mathbf{P}(\mathcal{I}).
$$
Hence $b$ is projective, see
Morphisms, Definition \ref{morphisms-definition-projective}.
The second statement follows for example from the characterization
of relatively ample invertible sheaves in
Morphisms, Lemma \ref{morphisms-lemma-characterize-relatively-ample}.
Some details omitted.
\end{proof}

\begin{lemma}[Composition of blowing ups is a blowing up]
\label{divisors-lemma-composition-finite-type-blowups}
\source{stacks:080B}
\href{https://stacks.math.columbia.edu/tag/080B}{\texttt{Stacks tag 080B}}
\group{divisors}


Let $X$ be a quasi-compact and quasi-separated scheme.
Let $Z \subset X$ be a closed subscheme of finite presentation.
Let $b : X' \to X$ be the blowing up with center $Z$. Let $Z' \subset X'$ be
a closed subscheme of finite presentation.
Let $X'' \to X'$ be the blowing up with center $Z'$.
There exists a closed subscheme $Y \subset X$ of finite presentation,
such that
\begin{enumerate}
\item $Y = Z \cup b(Z')$ set theoretically, and
\item the composition $X'' \to X$ is isomorphic to the blowing up
of $X$ in $Y$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{divisors-lemma-blowing-up-gives-effective-Cartier-divisor, divisors-lemma-closed-subscheme-proj-finite-type, divisors-lemma-blowing-up-two-ideals, divisors-lemma-blow-up-effective-Cartier-divisor, divisors-lemma-blowing-up-affine}

The condition that $Z \to X$ is of finite presentation means that
$Z$ is cut out by a finite type quasi-coherent sheaf of ideals
$\mathcal{I} \subset \mathcal{O}_X$, see
Morphisms, Lemma \ref{morphisms-lemma-closed-immersion-finite-presentation}.
Write $\mathcal{A} = \bigoplus_{n \geq 0} \mathcal{I}^n$ so that
$X' = \underline{\text{Proj}}(\mathcal{A})$.
Note that $X \setminus Z$ is a quasi-compact open of $X$ by
Properties, Lemma \ref{properties-lemma-quasi-coherent-finite-type-ideals}.
Since $b^{-1}(X \setminus Z) \to X \setminus Z$ is an isomorphism
(Lemma \ref{divisors-lemma-blowing-up-gives-effective-Cartier-divisor}) the same
result shows that
$b^{-1}(X \setminus Z) \setminus Z'$ is quasi-compact open in $X'$.
Hence $U = X \setminus (Z \cup b(Z'))$ is quasi-compact open in $X$.
By Lemma \ref{divisors-lemma-closed-subscheme-proj-finite-type}
there exist a $d > 0$ and a finite type
$\mathcal{O}_X$-submodule $\mathcal{F} \subset \mathcal{I}^d$ such
that $Z' = \underline{\text{Proj}}(\mathcal{A}/\mathcal{F}\mathcal{A})$
and such that the support of $\mathcal{I}^d/\mathcal{F}$ is contained
in $X \setminus U$.

\medskip\noindent
Since $\mathcal{F} \subset \mathcal{I}^d$ is an $\mathcal{O}_X$-submodule
we may think of $\mathcal{F} \subset \mathcal{I}^d \subset \mathcal{O}_X$
as a finite type quasi-coherent sheaf of ideals on $X$. Let's denote this
$\mathcal{J} \subset \mathcal{O}_X$ to prevent confusion. Since
$\mathcal{I}^d / \mathcal{J}$ and $\mathcal{O}/\mathcal{I}^d$
are supported on $X \setminus U$ we see that $V(\mathcal{J})$ is contained
in $X \setminus U$. Conversely, as $\mathcal{J} \subset \mathcal{I}^d$
we see that $Z \subset V(\mathcal{J})$. Over
$X \setminus Z \cong X' \setminus b^{-1}(Z)$ the sheaf of ideals
$\mathcal{J}$ cuts out $Z'$ (see displayed formula below). Hence
$V(\mathcal{J})$ equals $Z \cup b(Z')$. It follows that also
$V(\mathcal{I}\mathcal{J}) = Z \cup b(Z')$ set theoretically. Moreover,
$\mathcal{I}\mathcal{J}$ is an ideal of finite type as a product of two such.
We claim that $X'' \to X$ is isomorphic to the blowing up of $X$ in
$\mathcal{I}\mathcal{J}$ which finishes the proof of the lemma by setting
$Y = V(\mathcal{I}\mathcal{J})$.

\medskip\noindent
First, recall that the blowup of $X$ in $\mathcal{I}\mathcal{J}$
is the same as the blowup of $X'$ in $b^{-1}\mathcal{J} \mathcal{O}_{X'}$,
see Lemma \ref{divisors-lemma-blowing-up-two-ideals}.
Hence it suffices to show that the blowup of $X'$ in
$b^{-1}\mathcal{J} \mathcal{O}_{X'}$ agrees with the blowup of $X'$
in $Z'$. We will show that
$$
b^{-1}\mathcal{J} \mathcal{O}_{X'} = \mathcal{I}_E^d \mathcal{I}_{Z'}
$$
as ideal sheaves on $X''$. This will prove what we want as
$\mathcal{I}_E^d$ cuts out the effective Cartier divisor $dE$
and we can use Lemmas \ref{divisors-lemma-blow-up-effective-Cartier-divisor} and
\ref{divisors-lemma-blowing-up-two-ideals}.

\medskip\noindent
To see the displayed equality of the ideals we may work locally.
With notation $A$, $I$, $a \in I$ as in Lemma \ref{divisors-lemma-blowing-up-affine}
we see that $\mathcal{F}$ corresponds to an $R$-submodule $M \subset I^d$
mapping isomorphically to an ideal $J \subset R$. The condition
$Z' = \underline{\text{Proj}}(\mathcal{A}/\mathcal{F}\mathcal{A})$
means that $Z' \cap \Spec(A[\frac{I}{a}])$ is cut out by the ideal
generated by the elements $m/a^d$, $m \in M$. Say the element $m \in M$
corresponds to the function $f \in J$. Then in the affine blowup algebra
$A' = A[\frac{I}{a}]$ we see that $f = (a^dm)/a^d = a^d (m/a^d)$.
Thus the equality holds.
\end{proof}

\section{Strict transform}
\label{divisors-section-strict-transform}
In this section we briefly discuss strict transform under blowing up.
Let $S$ be a scheme and let $Z \subset S$ be a closed subscheme.
Let $b : S' \to S$ be the blowing up of $S$ in $Z$ and denote $E \subset S'$
the exceptional divisor $E = b^{-1}Z$. In the following we will often
consider a scheme $X$ over $S$ and form the cartesian diagram
$$
\begin{array}{ccc}\text{pr}_{S'}^{-1}E \longrightarrow\downarrow & X \times_S S' \underset{\text{pr}_X}{\longrightarrow}\underset{\text{pr}_{S'}}{\downarrow} & X \overset{f}{\downarrow} \\ E \longrightarrow & S' \longrightarrow & S\end{array}
$$
Since $E$ is an effective Cartier divisor
(Lemma \ref{divisors-lemma-blowing-up-gives-effective-Cartier-divisor})
we see that $\text{pr}_{S'}^{-1}E \subset X \times_S S'$
is locally principal
(Lemma \ref{divisors-lemma-pullback-locally-principal}).
Thus the complement of $\text{pr}_{S'}^{-1}E$ in $X \times_S S'$
is retrocompact
(Lemma \ref{divisors-lemma-complement-locally-principal-closed-subscheme}).
Consequently, for a quasi-coherent $\mathcal{O}_{X \times_S S'}$-module
$\mathcal{G}$ the subsheaf of sections supported on $\text{pr}_{S'}^{-1}E$
is a quasi-coherent submodule, see
Properties, Lemma \ref{properties-lemma-sections-supported-on-closed-subset}.
If $\mathcal{G}$ is a quasi-coherent sheaf of algebras, e.g.,
$\mathcal{G} = \mathcal{O}_{X \times_S S'}$, then this subsheaf is an ideal
of $\mathcal{G}$.

\begin{definition}[Strict transform]
\label{divisors-definition-strict-transform}
\source{stacks:080D}
\href{https://stacks.math.columbia.edu/tag/080D}{\texttt{Stacks tag 080D}}
\group{divisors}

With $Z \subset S$ and $f : X \to S$ as above.
\begin{enumerate}
\item Given a quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$
the {\it strict transform} of $\mathcal{F}$ with respect to the blowup
of $S$ in $Z$ is the quotient $\mathcal{F}'$ of $\text{pr}_X^*\mathcal{F}$
by the submodule of sections supported on $\text{pr}_{S'}^{-1}E$.
\item The {\it strict transform} of $X$ is the closed subscheme
$X' \subset X \times_S S'$ cut out by the quasi-coherent ideal of
sections of $\mathcal{O}_{X \times_S S'}$ supported on $\text{pr}_{S'}^{-1}E$.
\end{enumerate}
\end{definition}

Note that taking the strict transform along a blowup depends on the
closed subscheme used for the blowup
(and not just on the morphism $S' \to S$).
This notion is often used for closed subschemes of $S$.
It turns out that the strict transform of $X$ is a blowup of $X$.

\begin{lemma}[Strict transform]
\label{divisors-lemma-strict-transform}
\source{stacks:080E}
\href{https://stacks.math.columbia.edu/tag/080E}{\texttt{Stacks tag 080E}}
\group{divisors}

\uses{divisors-definition-strict-transform}
In the situation of Definition \ref{divisors-definition-strict-transform}.
\begin{enumerate}
\item The strict transform $X'$ of $X$ is the blowup of $X$ in the closed
subscheme $f^{-1}Z$ of $X$.
\item For a quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$ the
strict transform $\mathcal{F}'$ is canonically isomorphic to
the pushforward along $X' \to X \times_S S'$ of the strict transform of
$\mathcal{F}$ relative to the blowing up $X' \to X$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{divisors-lemma-universal-property-blowing-up, divisors-lemma-blowing-up-affine}

Let $X'' \to X$ be the blowup of $X$ in $f^{-1}Z$. By the universal
property of blowing up (Lemma \ref{divisors-lemma-universal-property-blowing-up})
there exists a commutative diagram
$$
\begin{array}{cc}X'' \longrightarrow\downarrow & X \downarrow \\ S' \longrightarrow & S\end{array}
$$
whence a morphism $X'' \to X \times_S S'$. Thus the first assertion
is that this morphism is a closed immersion with image $X'$.
The question is local on $X$. Thus we may assume $X$
and $S$ are affine. Say that $S = \Spec(A)$, $X = \Spec(B)$, and $Z$
is cut out by the ideal $I \subset A$. Set $J = IB$. The map
$B \otimes_A \bigoplus_{n \geq 0} I^n \to \bigoplus_{n \geq 0} J^n$
defines a closed immersion $X'' \to X \times_S S'$, see
Constructions, Lemmas
\ref{constructions-lemma-base-change-map-proj} and
\ref{constructions-lemma-surjective-graded-rings-generated-degree-1-map-proj}.
We omit the verification that this morphism is the same as the
one constructed above from the universal property.
Pick $a \in I$ corresponding to the affine open
$\Spec(A[\frac{I}{a}]) \subset S'$, see Lemma \ref{divisors-lemma-blowing-up-affine}.
The inverse image of $\Spec(A[\frac{I}{a}])$ in the strict transform
$X'$ of $X$ is the spectrum of
$$
B' = (B \otimes_A A[\textstyle{\frac{I}{a}}])/a\text{-power-torsion}
$$
see Properties, Lemma
\ref{properties-lemma-sections-supported-on-closed-subset}.
On the other hand, letting $b \in J$ be the image of $a$ we see that
$\Spec(B[\frac{J}{b}])$ is the inverse image of $\Spec(A[\frac{I}{a}])$
in $X''$. By Algebra, Lemma \ref{algebra-lemma-blowup-base-change}
the open $\Spec(B[\frac{J}{b}])$ maps isomorphically to the open subscheme
$\text{pr}_{S'}^{-1}(\Spec(A[\frac{I}{a}]))$ of $X'$.
Thus $X'' \to X'$ is an isomorphism.

\medskip\noindent
In the notation above, let $\mathcal{F}$ correspond to the $B$-module $N$.
The strict transform of $\mathcal{F}$ corresponds to the
$B \otimes_A A[\frac{I}{a}]$-module
$$
N' = (N \otimes_A A[\textstyle{\frac{I}{a}}])/a\text{-power-torsion}
$$
see Properties, Lemma
\ref{properties-lemma-sections-supported-on-closed-subset}.
The strict transform of $\mathcal{F}$ relative to the blowup of
$X$ in $f^{-1}Z$ corresponds to the $B[\frac{J}{b}]$-module
$N \otimes_B B[\frac{J}{b}]/b\text{-power-torsion}$. In exactly the same
way as above one proves that these two modules are isomorphic.
Details omitted.
\end{proof}

\begin{lemma}[Strict transform flat]
\label{divisors-lemma-strict-transform-flat}
\source{stacks:080F}
\href{https://stacks.math.columbia.edu/tag/080F}{\texttt{Stacks tag 080F}}
\group{divisors}

\uses{divisors-definition-strict-transform}
In the situation of Definition \ref{divisors-definition-strict-transform}.
\begin{enumerate}
\item If $X$ is flat over $S$ at all points lying over $Z$, then
the strict transform of $X$ is equal to the base change $X \times_S S'$.
\item Let $\mathcal{F}$ be a quasi-coherent $\mathcal{O}_X$-module.
If $\mathcal{F}$ is flat over $S$ at all points lying over $Z$, then
the strict transform $\mathcal{F}'$ of $\mathcal{F}$ is equal to the
pullback $\text{pr}_X^*\mathcal{F}$.
\end{enumerate}
\end{lemma}

\begin{proof}
We will prove part (2) as it implies part (1) by the definition of the
strict transform of a scheme over $S$. The question is local on $X$.
Thus we may assume that $S = \Spec(A)$, $X = \Spec(B)$, and that
$\mathcal{F}$ corresponds to the $B$-module $N$. Then $\mathcal{F}'$
over the open $\Spec(B \otimes_A A[\frac{I}{a}])$ of $X \times_S S'$
corresponds to the module
$$
N' = (N \otimes_A A[\textstyle{\frac{I}{a}}])/a\text{-power-torsion}
$$
see Properties, Lemma
\ref{properties-lemma-sections-supported-on-closed-subset}.
Thus we have to show that the $a$-power-torsion of
$N \otimes_A A[\frac{I}{a}]$ is zero. Let $y \in N \otimes_A A[\frac{I}{a}]$
with $a^n y = 0$. If $\mathfrak q \subset B$
is a prime and $a \not \in \mathfrak q$, then $y$ maps to
zero in $(N \otimes_A A[\frac{I}{a}])_\mathfrak q$. on the other hand,
if $a \in \mathfrak q$, then $N_\mathfrak q$ is a flat $A$-module
and we see that
$N_\mathfrak q \otimes_A A[\frac{I}{a}]
=(N \otimes_A A[\frac{I}{a}])_\mathfrak q$
has no $a$-power torsion (as $A[\frac{I}{a}]$ doesn't).
Hence $y$ maps to zero in this localization as well. We conclude that
$y$ is zero by
Algebra, Lemma \ref{algebra-lemma-characterize-zero-local}.
\end{proof}

\begin{lemma}[Strict transform affine]
\label{divisors-lemma-strict-transform-affine}
\source{stacks:080G}
\href{https://stacks.math.columbia.edu/tag/080G}{\texttt{Stacks tag 080G}}
\group{divisors}

Let $S$ be a scheme. Let $Z \subset S$ be a closed subscheme.
Let $b : S' \to S$ be the blowing up of $Z$ in $S$. Let
$g : X \to Y$ be an affine morphism of schemes over $S$.
Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $g' : X \times_S S' \to Y \times_S S'$ be the base change
of $g$. Let $\mathcal{F}'$ be the strict transform of $\mathcal{F}$
relative to $b$. Then $g'_*\mathcal{F}'$ is the strict transform
of $g_*\mathcal{F}$.
\end{lemma}

\begin{proof}
Observe that $g'_*\text{pr}_X^*\mathcal{F} = \text{pr}_Y^*g_*\mathcal{F}$
by Cohomology of Schemes, Lemma \ref{coherent-lemma-affine-base-change}.
Let $\mathcal{K} \subset \text{pr}_X^*\mathcal{F}$ be the subsheaf
of sections supported in the inverse image of $Z$ in $X \times_S S'$.
By Properties, Lemma
\ref{properties-lemma-push-sections-supported-on-closed-subset}
the pushforward $g'_*\mathcal{K}$ is the subsheaf of sections of
$\text{pr}_Y^*g_*\mathcal{F}$ supported in the inverse
image of $Z$ in $Y \times_S S'$. As $g'$ is affine
(Morphisms, Lemma \ref{morphisms-lemma-base-change-affine})
we see that $g'_*$ is exact, hence we conclude.
\end{proof}

\begin{lemma}[Strict transform different centers]
\label{divisors-lemma-strict-transform-different-centers}
\source{stacks:080H}
\href{https://stacks.math.columbia.edu/tag/080H}{\texttt{Stacks tag 080H}}
\group{divisors}

Let $S$ be a scheme. Let $Z \subset S$ be a closed subscheme.
Let $D \subset S$ be an effective Cartier divisor.
Let $Z' \subset S$ be the closed subscheme cut out by the product
of the ideal sheaves of $Z$ and $D$.
Let $S' \to S$ be the blowup of $S$ in $Z$.
\begin{enumerate}
\item The blowup of $S$ in $Z'$ is isomorphic to $S' \to S$.
\item Let $f : X \to S$ be a morphism of schemes and let $\mathcal{F}$
be a quasi-coherent $\mathcal{O}_X$-module. If $\mathcal{F}$ has
no nonzero local sections supported in $f^{-1}D$, then the
strict transform of $\mathcal{F}$ relative to the blowing up
in $Z$ agrees with the strict transform of $\mathcal{F}$ relative
to the blowing up of $S$ in $Z'$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{divisors-lemma-blowing-up-two-ideals, divisors-lemma-blow-up-effective-Cartier-divisor, divisors-lemma-blowing-up-affine}

The first statement follows on combining
Lemmas \ref{divisors-lemma-blowing-up-two-ideals} and
\ref{divisors-lemma-blow-up-effective-Cartier-divisor}.
Using Lemma \ref{divisors-lemma-blowing-up-affine} the second statement
translates into the
following algebra problem. Let $A$ be a ring, $I \subset A$ an ideal,
$x \in A$ a nonzerodivisor, and $a \in I$. Let $M$ be an $A$-module
whose $x$-torsion is zero. To show: the $a$-power torsion in
$M \otimes_A A[\frac{I}{a}]$ is equal to the $xa$-power torsion.
The reason for this is that the kernel and cokernel of the map
$A \to A[\frac{I}{a}]$ is $a$-power torsion, so this map becomes an
isomorphism after inverting $a$. Hence the kernel
and cokernel of $M \to M \otimes_A A[\frac{I}{a}]$ are $a$-power
torsion too. This implies the result.
\end{proof}

\begin{lemma}[Strict transform composition blowups]
\label{divisors-lemma-strict-transform-composition-blowups}
\source{stacks:080I}
\href{https://stacks.math.columbia.edu/tag/080I}{\texttt{Stacks tag 080I}}
\group{divisors}

Let $S$ be a scheme. Let $Z \subset S$ be a closed subscheme.
Let $b : S' \to S$ be the blowing up with center $Z$. Let $Z' \subset S'$ be
a closed subscheme. Let $S'' \to S'$ be the blowing up with center $Z'$.
Let $Y \subset S$ be a closed subscheme such that
$Y = Z \cup b(Z')$ set theoretically and the composition $S'' \to S$
is isomorphic to the blowing up of $S$ in $Y$.
In this situation, given any scheme $X$ over $S$ and
$\mathcal{F} \in \QCoh(\mathcal{O}_X)$ we have
\begin{enumerate}
\item the strict transform of $\mathcal{F}$ with respect to the blowing
up of $S$ in $Y$ is equal to the strict transform with respect to the
blowup $S'' \to S'$ in $Z'$ of the strict transform of $\mathcal{F}$
with respect to the blowup $S' \to S$ of $S$ in $Z$, and
\item the strict transform of $X$ with respect to the blowing
up of $S$ in $Y$ is equal to the strict transform with respect to the
blowup $S'' \to S'$ in $Z'$ of the strict transform of $X$
with respect to the blowup $S' \to S$ of $S$ in $Z$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{divisors-lemma-strict-transform-different-centers}

Let $\mathcal{F}'$ be the strict transform of $\mathcal{F}$ with respect
to the blowup $S' \to S$ of $S$ in $Z$.
Let $\mathcal{F}''$ be the strict transform of $\mathcal{F}'$ with respect
to the blowup $S'' \to S'$ of $S'$ in $Z'$.
Let $\mathcal{G}$ be the strict transform of $\mathcal{F}$ with respect
to the blowup $S'' \to S$ of $S$ in $Y$.
We also label the morphisms
$$
\begin{array}{ccc}X \times_S S'' \underset{q}{\longrightarrow}\overset{f''}{\downarrow} & X \times_S S' \underset{p}{\longrightarrow}\overset{f'}{\downarrow} & X \overset{f}{\downarrow} \\ S'' \longrightarrow & S' \longrightarrow & S\end{array}
$$
By definition there is a surjection $p^*\mathcal{F} \to \mathcal{F}'$
and a surjection $q^*\mathcal{F}' \to \mathcal{F}''$ which combine
by right exactness of $q^*$ to a surjection
$(p \circ q)^*\mathcal{F} \to \mathcal{F}''$. Also we have the surjection
$(p \circ q)^*\mathcal{F} \to \mathcal{G}$. Thus it suffices to prove
that these two surjections have the same kernel.

\medskip\noindent
The kernel of the surjection $p^*\mathcal{F} \to \mathcal{F}'$
is supported on $(f \circ p)^{-1}Z$, so this map is an isomorphism at
points in the complement. Hence the kernel of
$q^*p^*\mathcal{F} \to q^*\mathcal{F}'$
is supported on $(f \circ p \circ q)^{-1}Z$. The kernel of
$q^*\mathcal{F}' \to \mathcal{F}''$ is supported on $(f' \circ q)^{-1}Z'$.
Combined we see that the kernel of
$(p \circ q)^*\mathcal{F} \to \mathcal{F}''$ is supported on
$(f \circ p \circ q)^{-1}Z \cup (f' \circ q)^{-1}Z' =
(f \circ p \circ q)^{-1}Y$.
By construction of $\mathcal{G}$ we see that we obtain a factorization
$(p \circ q)^*\mathcal{F} \to \mathcal{F}'' \to \mathcal{G}$.
To finish the proof it suffices to show that $\mathcal{F}''$ has no
nonzero (local) sections supported on
$(f \circ p \circ q)^{-1}(Y) =
(f \circ p \circ q)^{-1}Z \cup (f' \circ q)^{-1}Z'$.
This follows from Lemma \ref{divisors-lemma-strict-transform-different-centers}
applied to $\mathcal{F}'$ on $X \times_S S'$ over $S'$, the closed
subscheme $Z'$ and the effective Cartier divisor $b^{-1}Z$.
\end{proof}

\begin{lemma}[Strict transform universally injective]
\label{divisors-lemma-strict-transform-universally-injective}
\source{stacks:080W}
\href{https://stacks.math.columbia.edu/tag/080W}{\texttt{Stacks tag 080W}}
\group{divisors}

\uses{divisors-definition-strict-transform}
In the situation of Definition \ref{divisors-definition-strict-transform}.
Suppose that
$$
0 \to \mathcal{F}_1 \to \mathcal{F}_2 \to \mathcal{F}_3 \to 0
$$
is an exact sequence of quasi-coherent sheaves on $X$ which remains
exact after any base change $T \to S$. Then the strict transforms of
$\mathcal{F}_i'$ relative to any blowup $S' \to S$
form a short exact sequence
$0 \to \mathcal{F}'_1 \to \mathcal{F}'_2 \to \mathcal{F}'_3 \to 0$ too.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-strict-transform-affine}

We may localize on $S$ and $X$ and assume both are affine.
Then we may push $\mathcal{F}_i$ to $S$, see
Lemma \ref{divisors-lemma-strict-transform-affine}.
We may assume that our blowup is the morphism $1 : S \to S$
associated to an effective Cartier divisor $D \subset S$.
Then the translation into algebra is the following: Suppose that $A$
is a ring and $0 \to M_1 \to M_2 \to M_3 \to 0$ is a universally
exact sequence of $A$-modules. Let $a\in A$. Then the sequence
$$
0 \to
M_1/a\text{-power torsion} \to
M_2/a\text{-power torsion} \to
M_3/a\text{-power torsion} \to 0
$$
is exact too. Namely, surjectivity of the last map and injectivity of
the first map are immediate. The problem is exactness in the middle.
Suppose that $x \in M_2$ maps to zero in $M_3/a\text{-power torsion}$.
Then $y = a^n x \in M_1$ for some $n$. Then $y$ maps to zero in
$M_2/a^nM_2$. Since $M_1 \to M_2$ is universally injective we see that
$y$ maps to zero in $M_1/a^nM_1$. Thus $y = a^n z$ for some $z \in M_1$.
Thus $a^n(x - y) = 0$. Hence $y$ maps to the class of $x$ in
$M_2/a\text{-power torsion}$ as desired.
\end{proof}

\section{Admissible blowups}
\label{divisors-section-admissible-blowups}
To have a bit more control over our blowups we introduce the following
standard terminology.

\begin{definition}[Admissible blowup]
\label{divisors-definition-admissible-blowup}
\source{stacks:080K}
\href{https://stacks.math.columbia.edu/tag/080K}{\texttt{Stacks tag 080K}}
\group{divisors}

Let $X$ be a scheme. Let $U \subset X$ be an open subscheme. A morphism
$X' \to X$ is called a {\it $U$-admissible blowup} if there exists a
closed immersion $Z \to X$ of finite presentation with $Z$ disjoint from
$U$ such that $X'$ is isomorphic to the blowup of $X$ in $Z$.
\end{definition}

We recall that $Z \to X$ is of finite presentation if and only if the
ideal sheaf $\mathcal{I}_Z \subset \mathcal{O}_X$ is of finite type, see
Morphisms, Lemma \ref{morphisms-lemma-closed-immersion-finite-presentation}.
In particular, a $U$-admissible blowup is a projective morphism, see
Lemma \ref{divisors-lemma-blowing-up-projective}.
Note that there can be multiple centers which give rise to the same morphism.
Hence the requirement is just the existence of some center disjoint from
$U$ which produces $X'$.
Finally, as the morphism $b : X' \to X$ is an isomorphism over $U$ (see
Lemma \ref{divisors-lemma-blowing-up-gives-effective-Cartier-divisor}) we will often
abuse notation and think of $U$ as an open subscheme of $X'$ as well.

\begin{lemma}[Admissible blowups are stable under composition.]
\label{divisors-lemma-composition-admissible-blowups}
\source{stacks:080L}
\href{https://stacks.math.columbia.edu/tag/080L}{\texttt{Stacks tag 080L}}
\group{divisors}


Let $X$ be a quasi-compact and quasi-separated scheme.
Let $U \subset X$ be a quasi-compact open subscheme.
Let $b : X' \to X$ be a $U$-admissible blowup.
Let $X'' \to X'$ be a $U$-admissible blowup.
Then the composition $X'' \to X$ is a $U$-admissible blowup.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-composition-finite-type-blowups}

Immediate from the more precise
Lemma \ref{divisors-lemma-composition-finite-type-blowups}.
\end{proof}

\begin{lemma}[Extend admissible blowups]
\label{divisors-lemma-extend-admissible-blowups}
\source{stacks:080M}
\href{https://stacks.math.columbia.edu/tag/080M}{\texttt{Stacks tag 080M}}
\group{divisors}

Let $X$ be a quasi-compact and quasi-separated scheme.
Let $U, V \subset X$ be quasi-compact open subschemes.
Let $b : V' \to V$ be a $U \cap V$-admissible blowup.
Then there exists a $U$-admissible blowup $X' \to X$
whose restriction to $V$ is $V'$.
\end{lemma}

\begin{proof}
Let $\mathcal{I} \subset \mathcal{O}_V$ be the finite type
quasi-coherent sheaf of ideals such that $V(\mathcal{I})$ is
disjoint from $U \cap V$ and such that $V'$ is isomorphic to the
blowup of $V$ in $\mathcal{I}$. Let
$\mathcal{I}' \subset \mathcal{O}_{U \cup V}$ be the quasi-coherent
sheaf of ideals whose restriction to $U$ is $\mathcal{O}_U$ and
whose restriction to $V$ is $\mathcal{I}$ (see Sheaves, Section
\ref{sheaves-section-glueing-sheaves}).
By Properties, Lemma \ref{properties-lemma-extend}
there exists a finite type quasi-coherent sheaf of ideals
$\mathcal{J} \subset \mathcal{O}_X$ whose restriction to $U \cup V$ is
$\mathcal{I}'$. The lemma follows.
\end{proof}

\begin{lemma}[Dominate admissible blowups]
\label{divisors-lemma-dominate-admissible-blowups}
\source{stacks:080N}
\href{https://stacks.math.columbia.edu/tag/080N}{\texttt{Stacks tag 080N}}
\group{divisors}

Let $X$ be a quasi-compact and quasi-separated scheme.
Let $U \subset X$ be a quasi-compact open subscheme.
Let $b_i : X_i \to X$, $i = 1, \ldots, n$ be $U$-admissible blowups.
There exists a $U$-admissible blowup $b : X' \to X$ such that
(a) $b$ factors as $X' \to X_i \to X$ for $i = 1, \ldots, n$ and
(b) each of the morphisms $X' \to X_i$ is a $U$-admissible blowup.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-blowing-up-two-ideals}

Let $\mathcal{I}_i \subset \mathcal{O}_X$ be the finite type
quasi-coherent sheaf of ideals such that $V(\mathcal{I}_i)$ is
disjoint from $U$ and such that $X_i$ is isomorphic to the
blowup of $X$ in $\mathcal{I}_i$. Set
$\mathcal{I} = \mathcal{I}_1 \cdot \ldots \cdot \mathcal{I}_n$
and let $X'$ be the blowup of $X$ in $\mathcal{I}$. Then
$X' \to X$ factors through $b_i$ by Lemma \ref{divisors-lemma-blowing-up-two-ideals}.
\end{proof}

\begin{lemma}[Separate irreducible components by blowing up.]
\label{divisors-lemma-separate-disjoint-opens-by-blowing-up}
\source{stacks:080P}
\href{https://stacks.math.columbia.edu/tag/080P}{\texttt{Stacks tag 080P}}
\group{divisors}


Let $X$ be a quasi-compact and quasi-separated scheme.
Let $U, V$ be quasi-compact disjoint open subschemes of $X$.
Then there exist a $U \cup V$-admissible blowup $b : X' \to X$
such that $X'$ is a disjoint union of open subschemes
$X' = X'_1 \amalg X'_2$ with $b^{-1}(U) \subset X'_1$ and
$b^{-1}(V) \subset X'_2$.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-blowing-up-affine}

Choose a finite type quasi-coherent sheaf of ideals $\mathcal{I}$,
resp.\ $\mathcal{J}$ such that $X \setminus U = V(\mathcal{I})$,
resp.\ $X \setminus V = V(\mathcal{J})$, see
Properties, Lemma \ref{properties-lemma-quasi-coherent-finite-type-ideals}.
Then $V(\mathcal{I}\mathcal{J}) = X$ set theoretically, hence
$\mathcal{I}\mathcal{J}$ is a locally nilpotent sheaf of ideals.
Since $\mathcal{I}$ and $\mathcal{J}$ are of finite type and $X$
is quasi-compact there exists an $n > 0$ such that
$\mathcal{I}^n \mathcal{J}^n = 0$. We may and do replace $\mathcal{I}$
by $\mathcal{I}^n$ and $\mathcal{J}$ by $\mathcal{J}^n$. Whence
$\mathcal{I} \mathcal{J} = 0$. Let $b : X' \to X$ be the blowing
up in $\mathcal{I} + \mathcal{J}$. This is $U \cup V$-admissible
as $V(\mathcal{I} + \mathcal{J}) = X \setminus U \cup V$. We will show that
$X'$ is a disjoint union of open subschemes $X' = X'_1 \amalg X'_2$
such that $b^{-1}\mathcal{I}|_{X'_2} = 0$ and $b^{-1}\mathcal{J}|_{X'_1} = 0$
which will prove the lemma.

\medskip\noindent
We will use the description of the blowing up in
Lemma \ref{divisors-lemma-blowing-up-affine}. Suppose that $U = \Spec(A) \subset X$
is an affine open such that $\mathcal{I}|_U$, resp.\ $\mathcal{J}|_U$
corresponds to the finitely generated ideal $I \subset A$, resp.\ $J \subset A$.
Then
$$
b^{-1}(U) = \text{Proj}(A \oplus (I + J) \oplus (I + J)^2 \oplus \ldots)
$$
This is covered by the affine open subsets $A[\frac{I + J}{x}]$
and $A[\frac{I + J}{y}]$ with $x \in I$ and $y \in J$. Since $x \in I$ is a
nonzerodivisor in $A[\frac{I + J}{x}]$ and $IJ = 0$ we see that
$J A[\frac{I + J}{x}] = 0$. Since $y \in J$ is a nonzerodivisor
in $A[\frac{I + J}{y}]$ and $IJ = 0$ we see that
$I A[\frac{I + J}{y}] = 0$. Moreover,
$$
\Spec(A[\textstyle{\frac{I + J}{x}}]) \cap
\Spec(A[\textstyle{\frac{I + J}{y}}]) =
\Spec(A[\textstyle{\frac{I + J}{xy}}]) = \emptyset
$$
because $xy$ is both a nonzerodivisor and zero. Thus $b^{-1}(U)$
is the disjoint union of the open subscheme $U_1$ defined as the union
of the standard opens $\Spec(A[\frac{I + J}{x}])$ for $x \in I$ and the open
subscheme $U_2$ which is the union of the affine opens
$\Spec(A[\frac{I + J}{y}])$ for $y \in J$. We have seen that
$b^{-1}\mathcal{I}\mathcal{O}_{X'}$ restricts to zero on $U_2$
and $b^{-1}\mathcal{I}\mathcal{O}_{X'}$ restricts to zero on $U_1$.
We omit the verification that these open subschemes glue to global
open subschemes $X'_1$ and $X'_2$.
\end{proof}

\begin{lemma}[Blowing up denominators]
\label{divisors-lemma-blowing-up-denominators}
\source{stacks:0ESL}
\href{https://stacks.math.columbia.edu/tag/0ESL}{\texttt{Stacks tag 0ESL}}
\group{divisors}

Let $X$ be a locally Noetherian scheme.
Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Let $s$ be a regular meromorphic section of $\mathcal{L}$.
Let $U \subset X$ be the maximal open subscheme such that
$s$ corresponds to a section of $\mathcal{L}$ over $U$.
The blowup $b : X' \to X$ in the ideal of denominators
of $s$ is $U$-admissible. There exists an effective Cartier divisor
$D \subset X'$ and an isomorphism
$$
b^*\mathcal{L} = \mathcal{O}_{X'}(D - E),
$$
where $E \subset X'$ is the exceptional divisor such that the
meromorphic section $b^*s$ corresponds, via the isomorphism,
to the meromorphic section $1_D \otimes (1_E)^{-1}$.
\end{lemma}

\begin{proof}
\uses{divisors-definition-regular-meromorphic-ideal-denominators, divisors-definition-invertible-sheaf-effective-Cartier-divisor, divisors-lemma-blow-up-pullback-effective-Cartier, divisors-lemma-meromorphic-sections-pullback, divisors-lemma-blowing-up-affine}

From the definition of the ideal of denominators in
Definition
\ref{divisors-definition-regular-meromorphic-ideal-denominators}
we immediately see that $b$ is a $U$-admissible blowup.
For the notation $1_D$, $1_E$, and $\mathcal{O}_{X'}(D - E)$
please see Definition
\ref{divisors-definition-invertible-sheaf-effective-Cartier-divisor}.
The pullback $b^*s$ is defined by
Lemmas \ref{divisors-lemma-blow-up-pullback-effective-Cartier} and
\ref{divisors-lemma-meromorphic-sections-pullback}.
Thus the statement of the lemma makes sense.
We can reinterpret the final assertion as saying
that $b^*s$ is a global regular section of
$b^*\mathcal{L}(E)$ whose zero scheme is $D$.
This uniquely defines $D$ hence
to prove the lemma we may work affine locally on $X$ and $X'$.
Assume $X = \Spec(A)$ is affine and
$\mathcal{L} = \mathcal{O}_X$. Then $s$ is a regular meromorphic
function and shrinking further we may assume
$s = a'/a$ with $a', a \in A$ nonzerodivisors.
Then the ideal of denominators of $s$ corresponds
to the ideal $I = \{x \in A \mid xa' \in aA\}$.
Recall that $X'$ is covered by spectra of affine blowup
algebras $A' = A[\frac{I}{x}]$ with $x \in I$
(Lemma \ref{divisors-lemma-blowing-up-affine}). Fix $x \in I$ and
write $xa' = a a''$ for some $a'' \in A$.
The divisor $E \subset X'$ is cut out by $x \in A'$ over
the spectrum of $A'$ and hence $1/x$ is a
generator of $\mathcal{O}_{X'}(E)$ over $\Spec(A')$.
Finally, in the total quotient ring
of $A'$ we have $a'/a = a''/x$. Hence $b^*s = a'/a$ restricts
to a regular section of $\mathcal{O}_{X'}(E)$ which is
over $\Spec(A')$ given by $a''/x$. This finishes the proof.
(The divisor $D \cap \Spec(A')$ is cut out by the image of
$a''$ in $A'$.)
\end{proof}

\section{Blowing up and flatness}
\label{divisors-section-blowup-flat}
We continue the discussion started in
More on Algebra, Section \ref{more-algebra-section-blowup-flat}.
We will prove further results in More on Flatness, Section
\ref{flat-section-blowup-flat}.


\begin{lemma}[Strict transform blowup fitting ideal]
\label{divisors-lemma-strict-transform-blowup-fitting-ideal}
\source{stacks:0CZP}
\href{https://stacks.math.columbia.edu/tag/0CZP}{\texttt{Stacks tag 0CZP}}
\group{divisors}

Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type
quasi-coherent $\mathcal{O}_S$-module. Let $Z_k \subset S$ be the closed
subscheme cut out by $\text{Fit}_k(\mathcal{F})$, see
Section \ref{divisors-section-fitting-ideals}.
Let $S' \to S$ be the blowup of $S$ in $Z_k$ and let
$\mathcal{F}'$ be the strict transform of $\mathcal{F}$.
Then $\mathcal{F}'$ can locally be generated by $\leq k$
sections.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-fitting-ideal-generate-locally}

Recall that $\mathcal{F}'$ can locally be generated by $\leq k$
sections if and only if $\text{Fit}_k(\mathcal{F}') = \mathcal{O}_{S'}$, see
Lemma \ref{divisors-lemma-fitting-ideal-generate-locally}.
Hence this lemma is a translation of
More on Algebra, Lemma \ref{more-algebra-lemma-blowup-fitting-ideal}.
\end{proof}

\begin{lemma}[Strict transform blowup fitting ideal locally free]
\label{divisors-lemma-strict-transform-blowup-fitting-ideal-locally-free}
\source{stacks:0CZQ}
\href{https://stacks.math.columbia.edu/tag/0CZQ}{\texttt{Stacks tag 0CZQ}}
\group{divisors}

Let $S$ be a scheme. Let $\mathcal{F}$ be a finite type
quasi-coherent $\mathcal{O}_S$-module. Let $Z_k \subset S$ be the closed
subscheme cut out by $\text{Fit}_k(\mathcal{F})$, see
Section \ref{divisors-section-fitting-ideals}.
Assume that $\mathcal{F}$ is locally free of rank $k$ on $S \setminus Z_k$.
Let $S' \to S$ be the blowup of $S$ in $Z_k$ and let
$\mathcal{F}'$ be the strict transform of $\mathcal{F}$.
Then $\mathcal{F}'$ is locally free of rank $k$.
\end{lemma}

\begin{proof}
Translation of More on Algebra, Lemma
\ref{more-algebra-lemma-blowup-fitting-ideal-locally-free}.
\end{proof}

\begin{lemma}[Blowup fitting ideal]
\label{divisors-lemma-blowup-fitting-ideal}
\source{stacks:0ESN}
\href{https://stacks.math.columbia.edu/tag/0ESN}{\texttt{Stacks tag 0ESN}}
\group{divisors}

Let $X$ be a scheme. Let $\mathcal{F}$ be a finitely presented
$\mathcal{O}_X$-module. Let $U \subset X$ be a scheme theoretically
dense open such that $\mathcal{F}|_U$ is finite locally free of
constant rank $r$. Then
\begin{enumerate}
\item the blowup $b : X' \to X$ of $X$ in the $r$th Fitting
ideal of $\mathcal{F}$ is $U$-admissible,
\item the strict transform $\mathcal{F}'$ of $\mathcal{F}$
with respect to $b$ is locally free of rank $r$,
\item the kernel $\mathcal{K}$ of the surjection
$b^*\mathcal{F} \to \mathcal{F}'$ is
finitely presented and $\mathcal{K}|_U = 0$,
\item $b^*\mathcal{F}$ and $\mathcal{K}$ are perfect
$\mathcal{O}_{X'}$-modules of tor dimension $\leq 1$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{divisors-lemma-fitting-ideal-of-finitely-presented, divisors-lemma-fitting-ideal-finite-locally-free, divisors-definition-admissible-blowup, divisors-lemma-strict-transform-blowup-fitting-ideal-locally-free}

The ideal $\text{Fit}_r(\mathcal{F})$ is of finite type
by Lemma \ref{divisors-lemma-fitting-ideal-of-finitely-presented}
and its restriction to $U$ is equal to $\mathcal{O}_U$ by
Lemma \ref{divisors-lemma-fitting-ideal-finite-locally-free}.
Hence $b : X' \to X$ is $U$-admissible, see
Definition \ref{divisors-definition-admissible-blowup}.

\medskip\noindent
By Lemma \ref{divisors-lemma-fitting-ideal-finite-locally-free}
the restriction of $\text{Fit}_{r - 1}(\mathcal{F})$
to $U$ is zero, and since $U$ is scheme theoretically dense
we conclude that $\text{Fit}_{r - 1}(\mathcal{F}) = 0$
on all of $X$. Thus it follows from
Lemma \ref{divisors-lemma-fitting-ideal-finite-locally-free}
that $\mathcal{F}$ is locally free of rank $r$
on the complement of subscheme cut out by the $r$th
Fitting ideal of $\mathcal{F}$ (this complement may
be bigger than $U$ which is why we had to do this step
in the argument). Hence by
Lemma \ref{divisors-lemma-strict-transform-blowup-fitting-ideal-locally-free}
the strict transform
$$
b^*\mathcal{F} \longrightarrow \mathcal{F}'
$$
is locally free of rank $r$. The kernel $\mathcal{K}$
of this map is supported on the exceptional divisor
of the blowup $b$ and hence $\mathcal{K}|_U = 0$.
Finally, since $\mathcal{F}'$ is finite locally free
and since the displayed arrow is surjective, we can
locally on $X'$ write $b^*\mathcal{F}$ as the
direct sum of $\mathcal{K}$ and $\mathcal{F}'$.
Since $b^*\mathcal{F}'$ is finitely presented
(Modules, Lemma \ref{modules-lemma-pullback-finite-presentation})
the same is true for $\mathcal{K}$.

\medskip\noindent
The statement on tor dimension follows from
More on Algebra, Lemma \ref{more-algebra-lemma-fitting-ideals-and-pd1}.
\end{proof}

\section{Modifications}
\label{divisors-section-modifications}
In this section we will collect results of the type: after a modification
such and such are true. We will later see that a modification can be
dominated by a blowup (More on Flatness, Lemma
\ref{flat-lemma-dominate-modification-by-blowup}).

\begin{lemma}[Filter after modification]
\label{divisors-lemma-filter-after-modification}
\source{stacks:0AYP}
\href{https://stacks.math.columbia.edu/tag/0AYP}{\texttt{Stacks tag 0AYP}}
\group{divisors}

Let $X$ be an integral scheme. Let $\mathcal{E}$ be a finite locally free
$\mathcal{O}_X$-module. There exists a modification $f : X' \to X$
such that $f^*\mathcal{E}$ has a filtration whose successive quotients
are invertible $\mathcal{O}_{X'}$-modules.
\end{lemma}

\begin{proof}
\uses{divisors-lemma-relative-proj-proper}

We prove this by induction on the rank $r$ of $\mathcal{E}$.
If $r = 1$ or $r = 0$ the lemma is obvious. Assume $r > 1$.
Let $P = \mathbf{P}(\mathcal{E})$ with structure morphism $\pi : P \to X$,
see Constructions, Section \ref{constructions-section-projective-bundle}.
Then $\pi$ is proper (Lemma \ref{divisors-lemma-relative-proj-proper}).
There is a canonical surjection
$$
\pi^*\mathcal{E} \to \mathcal{O}_P(1)
$$
whose kernel is finite locally free of rank $r - 1$.
Choose a nonempty open subscheme $U \subset X$ such that
$\mathcal{E}|_U \cong \mathcal{O}_U^{\oplus r}$.
Then $P_U = \pi^{-1}(U)$ is isomorphic to $\mathbf{P}^{r - 1}_U$.
In particular, there exists a section $s : U \to P_U$ of $\pi$.
Let $X' \subset P$ be the scheme theoretic image of the
morphism $U \to P_U \to P$. Then $X'$ is integral
(Morphisms, Lemma \ref{morphisms-lemma-scheme-theoretic-image-reduced}),
the morphism $f = \pi|_{X'} : X' \to X$ is proper (Morphisms, Lemmas
\ref{morphisms-lemma-closed-immersion-proper} and
\ref{morphisms-lemma-composition-proper}), and
$f^{-1}(U) \to U$ is an isomorphism. Hence $f$ is a modification
(Morphisms, Definition \ref{morphisms-definition-modification}).
By construction the pullback $f^*\mathcal{E}$ has a two step
filtration whose quotient is invertible because it is equal to
$\mathcal{O}_P(1)|_{X'}$ and whose sub $\mathcal{E}'$ is locally free of rank
$r - 1$. By induction we can find a modification $g : X'' \to X'$
such that $g^*\mathcal{E}'$ has a filtration as in the statement of
the lemma. Thus $f \circ g : X'' \to X$ is the required modification.
\end{proof}

\begin{lemma}[Extend rational map after modification]
\label{divisors-lemma-extend-rational-map-after-modification}
\source{stacks:0C4V}
\href{https://stacks.math.columbia.edu/tag/0C4V}{\texttt{Stacks tag 0C4V}}
\group{divisors}

Let $S$ be a scheme. Let $X$, $Y$ be schemes over $S$.
Assume $X$ is Noetherian and $Y$ is proper over $S$.
Given an $S$-rational map $f : U \to Y$ from $X$ to $Y$
there exists a morphism $p : X' \to X$ and an
$S$-morphism $f' : X' \to Y$ such that
\begin{enumerate}
\item $p$ is proper and $p^{-1}(U) \to U$ is an isomorphism,
\item $f'|_{p^{-1}(U)}$ is equal to $f \circ p|_{p^{-1}(U)}$.
\end{enumerate}
\end{lemma}

\begin{proof}
Denote $j : U \to X$ the inclusion morphism. Let $X' \subset Y \times_S X$
be the scheme theoretic image of $(f, j) : U \to Y \times_S X$
(Morphisms, Definition \ref{morphisms-definition-scheme-theoretic-image}).
The projection $g : Y \times_S X \to X$ is proper
(Morphisms, Lemma \ref{morphisms-lemma-base-change-proper}).
The composition $p : X' \to X$ of $X' \to Y \times_S X$ and $g$ is proper
(Morphisms, Lemmas \ref{morphisms-lemma-closed-immersion-proper} and
\ref{morphisms-lemma-composition-proper}).
Since $g$ is separated and $U \subset X$ is retrocompact (as $X$ is Noetherian)
we conclude that $p^{-1}(U) \to U$ is an isomorphism by
Morphisms, Lemma
\ref{morphisms-lemma-scheme-theoretic-image-of-partial-section}.
On the other hand, the composition $f' : X' \to Y$ of $X' \to Y \times_S X$
and the projection $Y \times_S X \to Y$ agrees with $f$ on $p^{-1}(U)$.
\end{proof}

\label{chap:limits}
\section{Introduction}
\label{limits-section-introduction}
In this chapter we put material related to limits of schemes. We mostly
study limits of inverse systems over directed sets
(Categories, Definition \ref{categories-definition-directed-set})
with affine transition maps. We discuss absolute Noetherian
approximation. We characterize schemes locally of finite presentation
over a base as those whose associated functor of points is limit
preserving. As an application of absolute Noetherian approximation
we prove that the image of an affine under an integral morphism is affine.
Moreover, we prove some very general variants of Chow's lemma.
A basic reference is \cite{EGA}.

\section{Directed limits of schemes with affine transition maps}
\label{limits-section-limits}
In this section we construct the limit.

\begin{lemma}[Directed inverse system affine schemes has limit]
\label{limits-lemma-directed-inverse-system-affine-schemes-has-limit}
\source{stacks:01YW}
\href{https://stacks.math.columbia.edu/tag/01YW}{\texttt{Stacks tag 01YW}}
\group{limits}

Let $I$ be a directed set. Let $(S_i, f_{ii'})$ be an inverse system of
schemes over $I$.  If all the schemes $S_i$
are affine, then the limit $S = \lim_i S_i$ exists
in the category of schemes.
In fact $S$ is affine and $S = \Spec(\colim_i R_i)$
with $R_i = \Gamma(S_i, \mathcal{O})$.
\end{lemma}

\begin{proof}
Just define $S = \Spec(\colim_i R_i)$.
It follows from Schemes, Lemma \ref{schemes-lemma-morphism-into-affine}
that $S$ is the limit even in the category of locally ringed spaces.
\end{proof}

\begin{lemma}[Directed inverse system has limit]
\label{limits-lemma-directed-inverse-system-has-limit}
\source{stacks:01YX}
\href{https://stacks.math.columbia.edu/tag/01YX}{\texttt{Stacks tag 01YX}}
\group{limits}

Let $I$ be a directed set. Let $(S_i, f_{ii'})$ be an
inverse system of schemes over $I$. If all the morphisms
$f_{ii'} : S_i \to S_{i'}$ are affine, then the limit $S = \lim_i S_i$ exists
in the category of schemes. Moreover,
\begin{enumerate}
\item each of the morphisms $f_i : S \to S_i$ is affine,
\item for an element $0 \in I$ and any open subscheme $U_0 \subset S_0$
we have
$$
f_0^{-1}(U_0) = \lim_{i \geq 0} f_{i0}^{-1}(U_0)
$$
in the category of schemes.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{limits-lemma-directed-inverse-system-affine-schemes-has-limit}

Choose an element $0 \in I$. Note that $I$ is nonempty as the limit is
directed. For every $i \geq 0$ consider the quasi-coherent sheaf of
$\mathcal{O}_{S_0}$-algebras $\mathcal{A}_i = f_{i0, *}\mathcal{O}_{S_i}$.
Recall that $S_i = \underline{\Spec}_{S_0}(\mathcal{A}_i)$,
see Morphisms, Lemma \ref{morphisms-lemma-characterize-affine}.
Set $\mathcal{A} = \colim_{i \geq 0} \mathcal{A}_i$.
This is a quasi-coherent sheaf of $\mathcal{O}_{S_0}$-algebras,
see Schemes, Section \ref{schemes-section-quasi-coherent}.
Set $S = \underline{\Spec}_{S_0}(\mathcal{A})$.
By Morphisms, Lemma \ref{morphisms-lemma-affine-equivalence-algebras}
we get for $i \geq 0$ morphisms $f_i : S \to S_i$ compatible with
the transition morphisms. Note that the morphisms $f_i$ are
affine by Morphisms, Lemma \ref{morphisms-lemma-affine-permanence} for example.
By Lemma \ref{limits-lemma-directed-inverse-system-affine-schemes-has-limit} above
we see that for any affine open $U_0 \subset S_0$ the
inverse image $U = f_0^{-1}(U_0) \subset S$ is the limit of the
system of opens $U_i = f_{i0}^{-1}(U_0)$, $i \geq 0$ in the
category of schemes.

\medskip\noindent
Let $T$ be a scheme. Let $g_i : T \to S_i$ be a compatible system
of morphisms. To show that $S = \lim_i S_i$ we have
to prove there is a unique morphism $g : T \to S$ with
$g_i = f_i \circ g$ for all $i \in I$.
For every $t \in T$ there exists an affine open
$U_0 \subset S_0$ containing $g_0(t)$. Let $V \subset g_0^{-1}(U_0)$
be an affine open neighbourhood containing $t$.
By the remarks above we obtain a unique morphism
$g_V : V \to U = f_0^{-1}(U_0)$ such that $f_i \circ g_V = g_i|_{U_i}$
for all $i$. The open sets $V \subset T$ so constructed form
a basis for the topology of $T$. The morphisms $g_V$ glue to a morphism
$g : T \to S$ because of the uniqueness property. This gives the
desired morphism $g : T \to S$.

\medskip\noindent
The final statement is clear from the construction of the limit above.
\end{proof}

\begin{lemma}[Scheme over limit]
\label{limits-lemma-scheme-over-limit}
\source{stacks:01YZ}
\href{https://stacks.math.columbia.edu/tag/01YZ}{\texttt{Stacks tag 01YZ}}
\group{limits}

Let $I$ be a directed set.
Let $(S_i, f_{ii'})$ be an inverse system of schemes over $I$.
Assume all the morphisms $f_{ii'} : S_i \to S_{i'}$ are affine,
Let $S = \lim_i S_i$. Let $0 \in I$.
Suppose that $T$ is a scheme over $S_0$.
Then
$$
T \times_{S_0} S = \lim_{i \geq 0} T \times_{S_0} S_i
$$
\end{lemma}

\begin{proof}
\uses{limits-lemma-directed-inverse-system-has-limit}

The right hand side is a scheme by
Lemma \ref{limits-lemma-directed-inverse-system-has-limit}.
The equality is formal, see
Categories, Lemma \ref{categories-lemma-colimits-commute}.
\end{proof}

\section{Infinite products}
\label{limits-section-inifinite-products}
Infinite products of schemes usually do not exist. For example in
Examples, Section \ref{examples-section-not-algebraic}
it is shown that an infinite product of
copies of $\mathbf{P}^1$ is not even an algebraic space.

\medskip\noindent
On the other hand, infinite products of affine schemes do exist
and are affine. Using Schemes, Lemma \ref{schemes-lemma-morphism-into-affine}
this corresponds to the fact that in the category of rings
we have infinite coproducts: if $I$ is a set and $R_i$ is a ring
for each $i$, then we can consider the ring
$$
R = \otimes R_i =
\colim_{\{i_1, \ldots, i_n\} \subset I}
R_{i_1} \otimes_\mathbf{Z} \ldots \otimes_\mathbf{Z} R_{i_n}
$$
Given another ring $A$ a map $R \to A$ is the same thing as a
collection of ring maps $R_i \to A$ for all $i \in I$ as
follows from the corresponding property of finite tensor products.

\begin{lemma}[Infinite products of affine schemes exist and are affine.]
\label{limits-lemma-infinite-product}
\source{stacks:0CNI}
\href{https://stacks.math.columbia.edu/tag/0CNI}{\texttt{Stacks tag 0CNI}}
\group{limits}


Let $S$ be a scheme. Let $I$ be a set and for each $i \in I$
let $f_i : T_i \to S$ be an affine morphism. Then the
product $T = \prod T_i$ exists in the category of schemes
over $S$. In fact, we have
$$
T = \lim_{\{i_1, \ldots, i_n\} \subset I}
T_{i_1} \times_S \ldots \times_S T_{i_n}
$$
and the projection morphisms $T \to T_{i_1} \times_S \ldots \times_S T_{i_n}$
are affine.
\end{lemma}

\begin{proof}
\uses{limits-lemma-directed-inverse-system-has-limit}

Omitted. Hint: Argue as in the discussion preceding the lemma
and use Lemma \ref{limits-lemma-directed-inverse-system-has-limit}
for existence of the limit.
\end{proof}

\begin{lemma}[Infinite product surjective]
\label{limits-lemma-infinite-product-surjective}
\source{stacks:0CNJ}
\href{https://stacks.math.columbia.edu/tag/0CNJ}{\texttt{Stacks tag 0CNJ}}
\group{limits}

\uses{limits-lemma-infinite-product}
Let $S$ be a scheme. Let $I$ be a set and for each $i \in I$
let $f_i : T_i \to S$ be a surjective affine morphism. Then the
product $T = \prod T_i$ in the category of schemes over $S$
(Lemma \ref{limits-lemma-infinite-product})
maps surjectively to $S$.
\end{lemma}

\begin{proof}
Let $s \in S$. Choose $t_i \in T_i$ mapping to $s$.
Choose a huge field extension $K/\kappa(s)$ such that
$\kappa(s_i)$ embeds into $K$ for each $i$. Then we get
morphisms $\Spec(K) \to T_i$ with image $s_i$ agreeing
as morphisms to $S$. Whence a morphism $\Spec(K) \to T$
which proves there is a point of $T$ mapping to $s$.
\end{proof}

\begin{lemma}[Infinite product integral]
\label{limits-lemma-infinite-product-integral}
\source{stacks:0CNK}
\href{https://stacks.math.columbia.edu/tag/0CNK}{\texttt{Stacks tag 0CNK}}
\group{limits}

\uses{limits-lemma-infinite-product}
Let $S$ be a scheme. Let $I$ be a set and for each $i \in I$
let $f_i : T_i \to S$ be an integral morphism. Then the
product $T = \prod T_i$ in the category of schemes over $S$
(Lemma \ref{limits-lemma-infinite-product})
is integral over $S$.
\end{lemma}

\begin{proof}
Omitted. Hint: On affine pieces this reduces to the following
algebra fact: if $A \to B_i$ is integral for all $i$, then
$A \to \otimes_A B_i$ is integral.
\end{proof}

\section{Descending properties}
\label{limits-section-descent}
First some basic lemmas describing the topology of a limit.

\begin{lemma}[Inverse limit sets]
\label{limits-lemma-inverse-limit-sets}
\source{stacks:0CUE}
\href{https://stacks.math.columbia.edu/tag/0CUE}{\texttt{Stacks tag 0CUE}}
\group{limits}

\uses{limits-lemma-directed-inverse-system-has-limit}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{limits-lemma-directed-inverse-system-has-limit}). Then
$S_{set} = \lim_i S_{i, set}$ where $S_{set}$
indicates the underlying set of the scheme $S$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-directed-inverse-system-has-limit}

Pick $i \in I$. Take $U_i \subset S_i$ an affine open.
Denote $U_{i'} = f_{i'i}^{-1}(U_i)$ and $U = f_i^{-1}(U_i)$.
Here $f_{i'i} : S_{i'} \to S_i$ is the transition morphism
and $f_i : S \to S_i$ is the projection.
By Lemma \ref{limits-lemma-directed-inverse-system-has-limit}
we have $U = \lim_{i' \geq i} U_i$.
Suppose we can show that $U_{set} = \lim_{i' \geq i} U_{i', set}$. Then
the lemma follows by a simple argument using an affine covering of $S_i$.
Hence we may assume all $S_i$ and $S$ affine. This reduces us to the
algebra question considered in the next paragraph.

\medskip\noindent
Suppose given a system of rings $(A_i, \varphi_{ii'})$
over $I$. Set $A = \colim_i A_i$ with canonical maps $\varphi_i : A_i \to A$.
Then
$$
\Spec(A) = \lim_i \Spec(A_i)
$$
Namely, suppose that we are given primes $\mathfrak p_i \subset A_i$
such that $\mathfrak p_i = \varphi_{ii'}^{-1}(\mathfrak p_{i'})$
for all $i' \geq i$. Then we simply set
$$
\mathfrak p =
\{x \in A
\mid
\exists i, x_i \in \mathfrak p_i \text{ with }\varphi_i(x_i) = x\}
$$
It is clear that this is an ideal and has the property that
$\varphi_i^{-1}(\mathfrak p) = \mathfrak p_i$. Then it follows
easily that it is a prime ideal as well.
\end{proof}

\begin{lemma}[Inverse limit top]
\label{limits-lemma-inverse-limit-top}
\source{stacks:0CUF}
\href{https://stacks.math.columbia.edu/tag/0CUF}{\texttt{Stacks tag 0CUF}}
\group{limits}

\uses{limits-lemma-directed-inverse-system-has-limit}
\begin{reference}
\cite[IV, Proposition 8.2.9]{EGA}
\end{reference}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{limits-lemma-directed-inverse-system-has-limit}). Then
$S_{top} = \lim_i S_{i, top}$ where $S_{top}$
indicates the underlying topological space of the scheme $S$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-inverse-limit-sets, limits-lemma-directed-inverse-system-has-limit, limits-lemma-directed-inverse-system-affine-schemes-has-limit}

We will use the criterion of
Topology, Lemma \ref{topology-lemma-characterize-limit}.
We have seen that $S_{set} = \lim_i S_{i, set}$ in
Lemma \ref{limits-lemma-inverse-limit-sets}.
The maps $f_i : S \to S_i$ are morphisms of schemes
hence continuous. Thus $f_i^{-1}(U_i)$ is open for each
open $U_i \subset S_i$. Finally,
let $s \in S$ and let $s \in V \subset S$ be an open
neighbourhood. Choose $0 \in I$ and choose an
affine open neighbourhood $U_0 \subset S_0$ of the image of $s$.
Then $f_0^{-1}(U_0) = \lim_{i \geq 0} f_{i0}^{-1}(U_0)$, see
Lemma \ref{limits-lemma-directed-inverse-system-has-limit}.
Then $f_0^{-1}(U_0)$ and $f_{i0}^{-1}(U_0)$ are affine and
$$
\mathcal{O}_S(f_0^{-1}(U_0)) =
\colim_{i \geq 0} \mathcal{O}_{S_i}(f_{i0}^{-1}(U_0))
$$
either by the proof of
Lemma \ref{limits-lemma-directed-inverse-system-has-limit}
or by
Lemma \ref{limits-lemma-directed-inverse-system-affine-schemes-has-limit}.
Choose $a \in \mathcal{O}_S(f_0^{-1}(U_0))$ such that
$s \in D(a) \subset V$. This is possible because the principal
opens form a basis for the topology on the affine scheme $f_0^{-1}(U_0)$.
Then we can pick an $i \geq 0$ and
$a_i \in \mathcal{O}_{S_i}(f_{i0}^{-1}(U_0))$ mapping to $a$.
It follows that $D(a_i) \subset f_{i0}^{-1}(U_0) \subset S_i$
is an open subset whose inverse image in $S$ is $D(a)$.
This finishes the proof.
\end{proof}

\begin{lemma}[Limit nonempty]
\label{limits-lemma-limit-nonempty}
\source{stacks:01Z2}
\href{https://stacks.math.columbia.edu/tag/01Z2}{\texttt{Stacks tag 01Z2}}
\group{limits}

\uses{limits-lemma-directed-inverse-system-has-limit}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{limits-lemma-directed-inverse-system-has-limit}).
If all the schemes $S_i$ are nonempty and quasi-compact,
then the limit $S = \lim_i S_i$ is nonempty.
\end{lemma}

\begin{proof}
Choose $0 \in I$. Note that $I$ is nonempty as the limit is directed.
Choose an affine open covering $S_0 = \bigcup_{j = 1, \ldots, m} U_j$.
Since $I$ is directed there exists a $j \in \{1, \ldots, m\}$
such that $f_{i0}^{-1}(U_j) \not = \emptyset$ for all
$i \geq 0$. Hence $\lim_{i \geq 0} f_{i0}^{-1}(U_j)$ is not
empty since a directed colimit of nonzero rings is nonzero
(because $1 \not = 0$). As $\lim_{i \geq 0} f_{i0}^{-1}(U_j)$
is an open subscheme of the limit we win.
\end{proof}

\begin{lemma}[Inverse limit irreducibles]
\label{limits-lemma-inverse-limit-irreducibles}
\source{stacks:0CUG}
\href{https://stacks.math.columbia.edu/tag/0CUG}{\texttt{Stacks tag 0CUG}}
\group{limits}

\uses{limits-lemma-directed-inverse-system-has-limit}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{limits-lemma-directed-inverse-system-has-limit}).
Let $s \in S$ with images $s_i \in S_i$.
Then
\begin{enumerate}
\item $s = \lim s_i$ as schemes, i.e., $\kappa(s) = \colim \kappa(s_i)$,
\item $\overline{\{s\}} = \lim \overline{\{s_i\}}$ as sets, and
\item $\overline{\{s\}} = \lim \overline{\{s_i\}}$ as schemes
where $\overline{\{s\}}$ and $\overline{\{s_i\}}$ are
endowed with the reduced induced scheme structure.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{limits-lemma-inverse-limit-sets}

Choose $0 \in I$ and an affine open covering
$S_0 = \bigcup_{j \in J} U_{0, j}$.
For $i \geq 0$ let $U_{i, j} = f_{i, 0}^{-1}(U_{0, j})$
and set $U_j = f_0^{-1}(U_{0, j})$.
Here $f_{i'i} : S_{i'} \to S_i$ is the transition morphism
and $f_i : S \to S_i$ is the projection.
For $j \in J$ the following are equivalent:
(a) $s \in U_j$, (b) $s_0 \in U_{0, j}$,
(c) $s_i \in U_{i, j}$ for all $i \geq 0$.
Let $J' \subset J$ be the set of indices for which (a), (b), (c) are true.
Then $\overline{\{s\}} = \bigcup_{j \in J'} (\overline{\{s\}} \cap U_j)$
and similarly for $\overline{\{s_i\}}$ for $i \geq 0$.
Note that $\overline{\{s\}} \cap U_j$ is the closure of the
set $\{s\}$ in the topological space $U_j$. Similarly for
$\overline{\{s_i\}} \cap U_{i, j}$ for $i \geq 0$.
Hence it suffices to prove the lemma in the case
$S$ and $S_i$ affine for all $i$. This reduces us to the
algebra question considered in the next paragraph.

\medskip\noindent
Suppose given a system of rings $(A_i, \varphi_{ii'})$
over $I$. Set $A = \colim_i A_i$ with canonical maps
$\varphi_i : A_i \to A$. Let $\mathfrak p \subset A$ be a
prime and set $\mathfrak p_i = \varphi_i^{-1}(\mathfrak p)$.
Then
$$
V(\mathfrak p) = \lim_i V(\mathfrak p_i)
$$
This follows from Lemma \ref{limits-lemma-inverse-limit-sets}
because $A/\mathfrak p = \colim A_i/\mathfrak p_i$.
This equality of rings also shows the final statement
about reduced induced scheme structures holds true.
The equality $\kappa(\mathfrak p) = \colim \kappa(\mathfrak p_i)$
follows from the statement as well.
\end{proof}

In the rest of this section we work in the following situation.

\begin{definition}[Situation: Descent]
\label{limits-situation-descent}
\source{stacks:086P}
\href{https://stacks.math.columbia.edu/tag/086P}{\texttt{Stacks tag 086P}}
\group{limits}

\uses{limits-lemma-directed-inverse-system-has-limit}
Let $S = \lim_{i \in I} S_i$ be the limit of a directed system of schemes
with affine transition morphisms $f_{i'i} : S_{i'} \to S_i$
(Lemma \ref{limits-lemma-directed-inverse-system-has-limit}).
We assume that $S_i$ is quasi-compact and quasi-separated for all $i \in I$.
We denote $f_i : S \to S_i$ the projection.
We also choose an element $0 \in I$.
\end{definition}

In this situation the morphism $S \to S_0$ is affine. It follows
that $S$ is quasi-compact and quasi-separated\footnote{Follows
from Morphisms, Lemma \ref{morphisms-lemma-affine-separated},
Topology, Definition \ref{topology-definition-quasi-compact}, and
Schemes, Lemma \ref{schemes-lemma-separated-permanence}.}.
The type of result we are looking for is the following:
If we have an object over $S$, then for some $i$ there is a
similar object over $S_i$.

\begin{lemma}[Topology limit]
\label{limits-lemma-topology-limit}
\source{stacks:01YY}
\href{https://stacks.math.columbia.edu/tag/01YY}{\texttt{Stacks tag 01YY}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent}.
\begin{enumerate}
\item We have $S_{set} = \lim_i S_{i, set}$ where $S_{set}$
indicates the underlying set of the scheme $S$.
\item We have $S_{top} = \lim_i S_{i, top}$ where $S_{top}$
indicates the underlying topological space of the scheme $S$.
\item If $s, s' \in S$ and $s'$ is not a specialization of $s$
then for some $i \in I$ the image $s'_i \in S_i$ of $s'$ is not
a specialization of the image $s_i \in S_i$ of $s$.
\item Add more easy facts on topology of $S$ here.
(Requirement: whatever is added should be easy in the affine case.)
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{limits-lemma-inverse-limit-sets, limits-lemma-inverse-limit-top, limits-lemma-inverse-limit-irreducibles}

Part (1) is a special case of Lemma \ref{limits-lemma-inverse-limit-sets}.

\medskip\noindent
Part (2) is a special case of Lemma \ref{limits-lemma-inverse-limit-top}.

\medskip\noindent
Part (3) is a special case of Lemma \ref{limits-lemma-inverse-limit-irreducibles}.
\end{proof}

\begin{lemma}[Descend section]
\label{limits-lemma-descend-section}
\source{stacks:01Z0}
\href{https://stacks.math.columbia.edu/tag/01Z0}{\texttt{Stacks tag 01Z0}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent}.
Suppose that $\mathcal{F}_0$ is a quasi-coherent sheaf on $S_0$.
Set $\mathcal{F}_i = f_{i0}^*\mathcal{F}_0$ for $i \geq 0$ and set
$\mathcal{F} = f_0^*\mathcal{F}_0$.
Then
$$
\Gamma(S, \mathcal{F}) = \colim_{i \geq 0} \Gamma(S_i, \mathcal{F}_i)
$$
\end{lemma}

\begin{proof}
\uses{limits-lemma-directed-inverse-system-has-limit}

Write $\mathcal{A}_j = f_{i0, *} \mathcal{O}_{S_i}$.
This is a quasi-coherent sheaf of $\mathcal{O}_{S_0}$-algebras
(see Morphisms, Lemma \ref{morphisms-lemma-affine-equivalence-algebras})
and $S_i$ is the relative spectrum of $\mathcal{A}_i$ over $S_0$.
In the proof of Lemma \ref{limits-lemma-directed-inverse-system-has-limit}
we constructed $S$ as the relative spectrum of
$\mathcal{A} = \colim_{i \geq 0} \mathcal{A}_i$
over $S_0$. Set
$$
\mathcal{M}_i = \mathcal{F}_0 \otimes_{\mathcal{O}_{S_0}} \mathcal{A}_i
$$
and
$$
\mathcal{M} = \mathcal{F}_0 \otimes_{\mathcal{O}_{S_0}} \mathcal{A}.
$$
Then we have $f_{i0, *} \mathcal{F}_i = \mathcal{M}_i$
and $f_{0, *}\mathcal{F} = \mathcal{M}$. Since $\mathcal{A}$
is the colimit of the sheaves $\mathcal{A}_i$ and since tensor
product commutes with directed colimits, we conclude that
$\mathcal{M} = \colim_{i \geq 0} \mathcal{M}_i$.
Since $S_0$ is quasi-compact and quasi-separated we see that
\begin{eqnarray*}
\Gamma(S, \mathcal{F})
& = &
\Gamma(S_0, \mathcal{M}) \\
& = &
\Gamma(S_0, \colim_{i \geq 0} \mathcal{M}_i) \\
& = &
\colim_{i \geq 0} \Gamma(S_0, \mathcal{M}_i) \\
& = &
\colim_{i \geq 0} \Gamma(S_i, \mathcal{F}_i)
\end{eqnarray*}
see Sheaves, Lemma \ref{sheaves-lemma-directed-colimits-sections} and
Topology, Lemma \ref{topology-lemma-topology-quasi-separated-scheme}
for the middle equality.
\end{proof}

\begin{lemma}[Limit closed nonempty]
\label{limits-lemma-limit-closed-nonempty}
\source{stacks:01Z3}
\href{https://stacks.math.columbia.edu/tag/01Z3}{\texttt{Stacks tag 01Z3}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent}.
Suppose for each $i$ we are given a nonempty closed subset
$Z_i \subset S_i$ with $f_{i'i}(Z_{i'}) \subset Z_i$ for all
$i' \geq i$.
Then there exists a point $s \in S$ with $f_i(s) \in Z_i$ for
all $i$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-limit-nonempty}

Let $Z_i \subset S_i$ also denote the reduced closed subscheme
associated to $Z_i$, see Schemes,
Definition \ref{schemes-definition-reduced-induced-scheme}.
A closed immersion is affine, and a composition of affine
morphisms is affine (see
Morphisms, Lemmas \ref{morphisms-lemma-closed-immersion-affine}
and \ref{morphisms-lemma-composition-affine}), and hence $Z_{i'} \to S_i$ is
affine when $i' \geq i$. We conclude that the morphism
$f_{i'i} : Z_{i'} \to Z_i$ is affine by
Morphisms, Lemma \ref{morphisms-lemma-affine-permanence}.
Each of the schemes $Z_i$ is quasi-compact as a closed
subscheme of a quasi-compact scheme. Hence we may apply
Lemma \ref{limits-lemma-limit-nonempty} to see that
$Z = \lim_i Z_i$ is nonempty. Since there is a
canonical morphism $Z \to S$ we win.
\end{proof}

\begin{lemma}[Limit fibre product empty]
\label{limits-lemma-limit-fibre-product-empty}
\source{stacks:05F3}
\href{https://stacks.math.columbia.edu/tag/05F3}{\texttt{Stacks tag 05F3}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent}.
Suppose we are given an $i$ and a morphism $T \to S_i$ such that
\begin{enumerate}
\item $T \times_{S_i} S = \emptyset$, and
\item $T$ is quasi-compact.
\end{enumerate}
Then $T \times_{S_i} S_{i'} = \emptyset$ for all sufficiently large $i'$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-scheme-over-limit, limits-lemma-limit-nonempty}

By Lemma \ref{limits-lemma-scheme-over-limit}
we see that $T \times_{S_i} S = \lim_{i' \geq i} T \times_{S_i} S_{i'}$.
Hence the result follows from
Lemma \ref{limits-lemma-limit-nonempty}.
\end{proof}

\begin{lemma}[Limit contained in constructible]
\label{limits-lemma-limit-contained-in-constructible}
\source{stacks:05F4}
\href{https://stacks.math.columbia.edu/tag/05F4}{\texttt{Stacks tag 05F4}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent}.
Suppose we are given an $i$ and a locally constructible subset
$E \subset S_i$ such that $f_i(S) \subset E$.
Then $f_{i'i}(S_{i'}) \subset E$ for all sufficiently large $i'$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-directed-inverse-system-has-limit, limits-lemma-limit-fibre-product-empty}

Writing $S_i$ as a finite union of open affine subschemes reduces
the question to the case that $S_i$ is affine and $E$ is constructible, see
Lemma \ref{limits-lemma-directed-inverse-system-has-limit}
and
Properties, Lemma \ref{properties-lemma-locally-constructible}.
In this case the complement $S_i \setminus E$ is constructible too.
Hence there exists an affine scheme $T$ and a morphism $T \to S_i$
whose image is $S_i \setminus E$, see
Algebra, Lemma \ref{algebra-lemma-constructible-is-image}.
By
Lemma \ref{limits-lemma-limit-fibre-product-empty}
we see that $T \times_{S_i} S_{i'}$ is empty for all sufficiently large
$i'$, and hence $f_{i'i}(S_{i'}) \subset E$ for all sufficiently large $i'$.
\end{proof}

\begin{lemma}[Descend opens]
\label{limits-lemma-descend-opens}
\source{stacks:01Z4}
\href{https://stacks.math.columbia.edu/tag/01Z4}{\texttt{Stacks tag 01Z4}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent} we have the following:
\begin{enumerate}
\item Given any quasi-compact open $V \subset S = \lim_i S_i$
there exists an $i \in I$ and a quasi-compact open $V_i \subset S_i$
such that $f_i^{-1}(V_i) = V$.
\item Given $V_i \subset S_i$ and $V_{i'} \subset S_{i'}$
quasi-compact opens such that $f_i^{-1}(V_i) = f_{i'}^{-1}(V_{i'})$
there exists an index $i'' \geq i, i'$ such that
$f_{i''i}^{-1}(V_i) = f_{i''i'}^{-1}(V_{i'})$.
\item If $V_{1, i}, \ldots, V_{n, i} \subset S_i$ are quasi-compact
opens and $S = f_i^{-1}(V_{1, i}) \cup \ldots \cup f_i^{-1}(V_{n, i})$
then $S_{i'} = f_{i'i}^{-1}(V_{1, i}) \cup \ldots \cup f_{i'i}^{-1}(V_{n, i})$
for some $i' \geq i$.
\end{enumerate}
\end{lemma}

\begin{proof}
Choose $i_0 \in I$. Note that $I$ is nonempty as the limit is directed.
For convenience we write $S_0 = S_{i_0}$ and $i_0 = 0$.
Choose an affine open covering $S_0 = U_{1, 0} \cup \ldots \cup U_{m, 0}$.
Denote $U_{j, i} \subset S_i$ the inverse image of $U_{j, 0}$
under the transition morphism for $i \geq 0$.
Denote $U_j$ the inverse image of $U_{j, 0}$ in $S$.
Note that $U_j = \lim_i U_{j, i}$ is a limit of affine
schemes.

\medskip\noindent
We first prove the uniqueness statement: Let
$V_i \subset S_i$ and $V_{i'} \subset S_{i'}$
quasi-compact opens such that $f_i^{-1}(V_i) = f_{i'}^{-1}(V_{i'})$.
It suffices to show that $f_{i''i}^{-1}(V_i \cap U_{j, i''})$ and
$f_{i''i'}^{-1}(V_{i'} \cap U_{j, i''})$ become equal
for $i''$ large enough. Hence we reduce to the case
of a limit of affine schemes. In this case write
$S = \Spec(R)$ and $S_i = \Spec(R_i)$ for all $i \in I$.
We may write $V_i = S_i \setminus V(h_1, \ldots, h_m)$
and $V_{i'} = S_{i'} \setminus V(g_1, \ldots, g_n)$.
The assumption means that the ideals
$\sum g_jR$ and $\sum h_jR$ have the same radical
in $R$. This means that $g_j^N = \sum a_{jj'}h_{j'}$ and
$h_j^N = \sum b_{jj'} g_{j'}$ for some $N \gg 0$ and $a_{jj'}$
and $b_{jj'}$ in $R$.
Since $R = \colim_i R_i$ we can chose an index
$i'' \geq i$ such that the equations
$g_j^N = \sum a_{jj'}h_{j'}$ and
$h_j^N = \sum b_{jj'} g_{j'}$ hold in $R_{i''}$ for some
$a_{jj'}$ and $b_{jj'}$ in $R_{i''}$. This implies that
the ideals $\sum g_jR_{i''}$ and $\sum h_jR_{i''}$ have the same radical
in $R_{i''}$ as desired.

\medskip\noindent
We prove existence: If $S_0$ is affine, then $S_i = \Spec(R_i)$ for all
$i \geq 0$ and $S = \Spec(R)$ with $R = \colim R_i$. Then
$V = S \setminus V(g_1, \ldots, g_n)$ for some $g_1, \ldots, g_n \in R$.
Choose any $i$ large enough so that each of the $g_j$ comes from an
element $g_{j, i} \in R_i$ and take
$V_i = S_i \setminus V(g_{1, i}, \ldots, g_{n, i})$.
If $S_0$ is general, then the opens $V \cap U_j$
are quasi-compact because $S$ is quasi-separated. Hence by the
affine case we see that for each $j = 1, \ldots, m$
there exists an $i_j \in I$ and a quasi-compact open
$V_{i_j} \subset U_{j, i_j}$ whose inverse image in $U_j$
is $V \cap U_j$. Set $i = \max(i_1, \ldots, i_m)$
and let $V_i = \bigcup f_{ii_j}^{-1}(V_{i_j})$.

\medskip\noindent
The statement on coverings follows from the uniqueness statement
for the opens $V_{1, i} \cup \ldots \cup V_{n, i}$ and $S_i$ of $S_i$.
\end{proof}

\begin{lemma}[Limit quasi affine]
\label{limits-lemma-limit-quasi-affine}
\source{stacks:01Z5}
\href{https://stacks.math.columbia.edu/tag/01Z5}{\texttt{Stacks tag 01Z5}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent} if $S$ is quasi-affine, then
for some $i_0 \in I$ the schemes $S_i$ for $i \geq i_0$ are quasi-affine.
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-section, limits-lemma-descend-opens}

Choose $i_0 \in I$. Note that $I$ is nonempty as the limit is directed.
For convenience we write $S_0 = S_{i_0}$ and $i_0 = 0$.
Let $s \in S$. We may choose an affine open
$U_0 \subset S_0$ containing $f_0(s)$. Since $S$ is quasi-affine
we may choose an element $a \in \Gamma(S, \mathcal{O}_S)$ such
that $s \in D(a) \subset f_0^{-1}(U_0)$, and such that
$D(a)$ is affine. By Lemma \ref{limits-lemma-descend-section}
there exists an $i \geq 0$ such that $a$
comes from an element $a_i \in \Gamma(S_i, \mathcal{O}_{S_i})$.
For any index $j \geq i$ we denote $a_j$
the image of $a_i$ in the global sections of the
structure sheaf of $S_j$.
Consider the opens $D(a_j) \subset S_j$
and $U_j = f_{j0}^{-1}(U_0)$. Note that
$U_j$ is affine and $D(a_j)$ is a quasi-compact open of $S_j$,
see Properties, Lemma \ref{properties-lemma-affine-cap-s-open}
for example. Hence we may apply Lemma \ref{limits-lemma-descend-opens} to the opens
$U_j$ and $U_j \cup D(a_j)$ to conclude that
$D(a_j) \subset U_j$ for some  $j \geq i$.
For such an index $j$ we see that $D(a_j) \subset S_j$ is an affine open
(because $D(a_j)$ is a standard affine open of the affine open $U_j$)
containing the image $f_j(s)$.

\medskip\noindent
We conclude that for every $s \in S$ there exist
an index $i \in I$, and a global section
$a \in \Gamma(S_i, \mathcal{O}_{S_i})$
such that $D(a) \subset S_i$ is an affine open
containing $f_i(s)$. Because $S$ is quasi-compact we
may choose a single index $i \in I$ and global sections
$a_1, \ldots, a_m \in \Gamma(S_i, \mathcal{O}_{S_i})$
such that each $D(a_j) \subset S_i$ is affine open
and such that $f_i : S \to S_i$ has image contained
in the union $W_i = \bigcup_{j = 1, \ldots, m} D(a_j)$.
For $i' \geq i$ set $W_{i'} = f_{i'i}^{-1}(W_i)$.
Since $f_i^{-1}(W_i)$ is all of $S$ we see
(by Lemma \ref{limits-lemma-descend-opens} again)
that for a suitable $i' \geq i$ we
have $S_{i'} = W_{i'}$. Thus we may replace $i$ by
$i'$ and assume that $S_i = \bigcup_{j = 1, \ldots, m} D(a_j)$.
This implies that $\mathcal{O}_{S_i}$ is an ample invertible
sheaf on $S_i$ (see Properties, Definition \ref{properties-definition-ample})
and hence that $S_i$ is quasi-affine, see
Properties, Lemma \ref{properties-lemma-quasi-affine-O-ample}.
Hence we win.
\end{proof}

\begin{lemma}[Limit affine]
\label{limits-lemma-limit-affine}
\source{stacks:01Z6}
\href{https://stacks.math.columbia.edu/tag/01Z6}{\texttt{Stacks tag 01Z6}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent} if $S$ is affine,
then for some $i_0 \in I$ the schemes $S_i$ for $i \geq i_0$
are affine.
\end{lemma}

\begin{proof}
\uses{limits-lemma-limit-quasi-affine, limits-lemma-descend-section, limits-lemma-limit-closed-nonempty, limits-lemma-topology-limit}

By Lemma \ref{limits-lemma-limit-quasi-affine} we may assume that $S_0$ is
quasi-affine for some $0 \in I$. Set $R_0 = \Gamma(S_0, \mathcal{O}_{S_0})$.
Then $S_0$ is a quasi-compact open of $T_0 = \Spec(R_0)$. Denote
$j_0 : S_0 \to T_0$ the corresponding quasi-compact open immersion.
For $i \geq 0$ set $\mathcal{A}_i = f_{i0, *}\mathcal{O}_{S_i}$.
Since $f_{i0}$ is affine we see that
$S_i = \underline{\Spec}_{S_0}(\mathcal{A}_i)$.
Set $T_i = \underline{\Spec}_{T_0}(j_{0, *}\mathcal{A}_i)$.
Then $T_i \to T_0$ is affine, hence $T_i$ is affine. Thus
$T_i$ is the spectrum of
$$
R_i = \Gamma(T_0, j_{0, *}\mathcal{A}_i) = \Gamma(S_0, \mathcal{A}_i) =
\Gamma(S_i, \mathcal{O}_{S_i}).
$$
Write $S = \Spec(R)$. We have $R = \colim_i R_i$
by Lemma \ref{limits-lemma-descend-section}.
Hence also $S = \lim_i T_i$. As formation of the relative spectrum commutes
with base change, the inverse image
of the open $S_0 \subset T_0$ in $T_i$ is $S_i$.
Let $Z_0 = T_0 \setminus S_0$ and let $Z_i \subset T_i$
be the inverse image of $Z_0$. As $S_i = T_i \setminus Z_i$, it suffices
to show that $Z_i$ is empty for some $i$. Assume $Z_i$ is nonempty for all
$i$ to get a contradiction. By Lemma \ref{limits-lemma-limit-closed-nonempty}
there exists a point $s$ of $S = \lim T_i$ which maps to a point of $Z_i$
for every $i$. But $S = \lim_i S_i$, and hence we arrive at a contradiction
by Lemma \ref{limits-lemma-topology-limit}.
\end{proof}

\begin{lemma}[Limit separated]
\label{limits-lemma-limit-separated}
\source{stacks:086Q}
\href{https://stacks.math.columbia.edu/tag/086Q}{\texttt{Stacks tag 086Q}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent} if $S$ is separated,
then for some $i_0 \in I$ the schemes $S_i$ for $i \geq i_0$
are separated.
\end{lemma}

\begin{proof}
\uses{limits-lemma-limit-affine}

Choose a finite affine open covering
$S_0 = U_{0, 1} \cup \ldots \cup U_{0, m}$.
Set $U_{i, j} \subset S_i$ and $U_j \subset S$
equal to the inverse image of $U_{0, j}$.
Note that $U_{i, j}$ and $U_j$ are affine. As $S$ is separated
the intersections $U_{j_1} \cap U_{j_2}$ are affine. Since
$U_{j_1} \cap U_{j_2} = \lim_{i \geq 0} U_{i, j_1} \cap U_{i, j_2}$
we see that $U_{i, j_1} \cap U_{i, j_2}$ is affine for large $i$
by Lemma \ref{limits-lemma-limit-affine}. To show that $S_i$ is separated
for large $i$ it now suffices to show that
$$
\mathcal{O}_{S_i}(U_{i, j_1})
\otimes_{\mathcal{O}_S(S)}
\mathcal{O}_{S_i}(U_{i, j_2})
\longrightarrow
\mathcal{O}_{S_i}(U_{i, j_1} \cap U_{i, j_2})
$$
is surjective for large $i$
(Schemes, Lemma \ref{schemes-lemma-characterize-separated}).

\medskip\noindent
To get rid of the annoying indices, assume we have affine opens
$U, V \subset S_0$ such that $U \cap V$ is affine too.
Let $U_i, V_i \subset S_i$, resp.\ $U, V \subset S$ be the inverse images.
We have to show that
$\mathcal{O}(U_i) \otimes \mathcal{O}(V_i) \to
\mathcal{O}(U_i \cap V_i)$
is surjective for $i$ large enough and we know that
$\mathcal{O}(U) \otimes \mathcal{O}(V) \to \mathcal{O}(U \cap V)$
is surjective. Note that
$\mathcal{O}(U_0) \otimes \mathcal{O}(V_0) \to
\mathcal{O}(U_0 \cap V_0)$
is of finite type, as the diagonal morphism $S_i \to S_i \times S_i$
is an immersion (Schemes, Lemma \ref{schemes-lemma-diagonal-immersion})
hence locally of finite type
(Morphisms, Lemmas \ref{morphisms-lemma-locally-finite-type-characterize} and
\ref{morphisms-lemma-immersion-locally-finite-type}).
Thus we can choose elements
$f_{0, 1}, \ldots, f_{0, n} \in \mathcal{O}(U_0 \cap V_0)$
which generate $\mathcal{O}(U_0 \cap V_0)$ over
$\mathcal{O}(U_0) \otimes \mathcal{O}(V_0)$.
Observe that for $i \geq 0$ the diagram of schemes
$$
\begin{array}{cc}U_i \cap V_i \longrightarrow\downarrow & U_i \downarrow \\ U_0 \cap V_0 \longrightarrow & U_0\end{array}
$$
is cartesian. Thus we see that the images
$f_{i, 1}, \ldots, f_{i, n} \in \mathcal{O}(U_i \cap V_i)$
generate $\mathcal{O}(U_i \cap V_i)$ over
$\mathcal{O}(U_i) \otimes \mathcal{O}(V_0)$
and a fortiori over
$\mathcal{O}(U_i) \otimes \mathcal{O}(V_i)$.
By assumption the images $f_1, \ldots, f_n \in \mathcal{O}(U \otimes V)$
are in the image of the map
$\mathcal{O}(U) \otimes \mathcal{O}(V) \to \mathcal{O}(U \cap V)$.
Since
$\mathcal{O}(U) \otimes \mathcal{O}(V) =
\colim \mathcal{O}(U_i) \otimes \mathcal{O}(V_i)$
we see that they are in the image of the map at some finite level
and the lemma is proved.
\end{proof}

\begin{lemma}[Limit ample]
\label{limits-lemma-limit-ample}
\source{stacks:09MT}
\href{https://stacks.math.columbia.edu/tag/09MT}{\texttt{Stacks tag 09MT}}
\group{limits}

\uses{limits-situation-descent}
In Situation \ref{limits-situation-descent} let $\mathcal{L}_0$ be an invertible
sheaf of modules on $S_0$. If the pullback $\mathcal{L}$ to $S$ is ample,
then for some $i \in I$ the pullback $\mathcal{L}_i$ to $S_i$ is ample.
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-section, limits-lemma-limit-affine, limits-lemma-descend-opens}

The assumption means there are finitely many sections
$s_1, \ldots, s_m \in \Gamma(S, \mathcal{L})$ such that
$S_{s_j}$ is affine and such that $S = \bigcup S_{s_j}$, see
Properties, Definition \ref{properties-definition-ample}.
By Lemma \ref{limits-lemma-descend-section} we can find an $i \in I$
and sections $s_{i, j} \in \Gamma(S_i, \mathcal{L}_i)$ mapping to $s_j$.
By Lemma \ref{limits-lemma-limit-affine} we may, after increasing $i$, assume
that $(S_i)_{s_{i, j}}$ is affine for $j = 1, \ldots, m$.
By Lemma \ref{limits-lemma-descend-opens} we may, after increasing $i$ a
last time, assume that $S_i = \bigcup (S_i)_{s_{i, j}}$.
Then $\mathcal{L}_i$ is ample by definition.
\end{proof}

\begin{lemma}[Finite type eventually closed]
\label{limits-lemma-finite-type-eventually-closed}
\source{stacks:081B}
\href{https://stacks.math.columbia.edu/tag/081B}{\texttt{Stacks tag 081B}}
\group{limits}

Let $S$ be a scheme. Let $X = \lim X_i$ be a directed limit of
schemes over $S$ with affine transition morphisms. Let $Y \to X$
be a morphism of schemes over $S$.
\begin{enumerate}
\item If $Y \to X$ is a closed immersion, $X_i$ quasi-compact, and
$Y$ locally of finite type over $S$, then $Y \to X_i$ is a closed
immersion for $i$ large enough.
\item If $Y \to X$ is an immersion, $X_i$ quasi-separated, $Y \to S$ locally
of finite type, and $Y$ quasi-compact, then $Y \to X_i$ is an
immersion for $i$ large enough.
\item If $Y \to X$ is an isomorphism, $X_i$ quasi-compact,
$X_i \to S$ locally of finite type, the transition morphisms
$X_{i'} \to X_i$ are closed immersions, and $Y \to S$ is locally
of finite presentation, then $Y \to X_i$ is an isomorphism for $i$
large enough.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-opens}

Proof of (1). Choose $0 \in I$ and a finite affine open covering
$X_0 = U_{0, 1} \cup \ldots \cup U_{0, m}$ with the property that
$U_{0, j}$ maps into an affine open $W_j \subset S$.
Let $V_j \subset Y$, resp.\ $U_{i, j} \subset X_i$, $i \geq 0$,
resp. $U_j \subset X$ be the inverse image of $U_{0, j}$. It suffices
to prove that $V_j \to U_{i, j}$ is a closed immersion for $i$
sufficiently large and we know that $V_j \to U_j$ is a closed immersion.
Thus we reduce to the following algebra fact: If $A = \colim A_i$ is a
directed colimit of $R$-algebras, $A \to B$ is a surjection of $R$-algebras,
and $B$ is a finitely generated $R$-algebra, then
$A_i \to B$ is surjective for $i$ sufficiently large.

\medskip\noindent
Proof of (2). Choose $0 \in I$. Choose a quasi-compact open
$X'_0 \subset X_0$ such that $Y \to X_0$ factors through $X'_0$.
After replacing $X_i$ by the inverse image of $X'_0$ for $i \geq 0$
we may assume all $X_i'$ are quasi-compact and quasi-separated.
Let $U \subset X$ be a quasi-compact open such that $Y \to X$ factors
through a closed immersion $Y \to U$ ($U$ exists as $Y$ is quasi-compact). By
Lemma \ref{limits-lemma-descend-opens}
we may assume that $U = \lim U_i$ with $U_i \subset X_i$ quasi-compact
open. By part (1) we see that $Y \to U_i$ is a closed immersion for some
$i$. Thus (2) holds.

\medskip\noindent
Proof of (3). Working affine locally on $X_0$ for some $0 \in I$ as in
the proof of (1) we reduce to the following algebra fact: If $A = \lim A_i$
is a directed colimit of $R$-algebras with surjective transition
maps and $A$ of finite presentation over $A_0$, then $A = A_i$ for
some $i$. Namely, write $A = A_0/(f_1, \ldots, f_n)$. Pick $i$ such
that $f_1, \ldots, f_n$ map to zero under the surjective map $A_0 \to A_i$.
\end{proof}

\begin{lemma}[Eventually separated]
\label{limits-lemma-eventually-separated}
\source{stacks:01ZH}
\href{https://stacks.math.columbia.edu/tag/01ZH}{\texttt{Stacks tag 01ZH}}
\group{limits}

Let $S$ be a scheme. Let $X = \lim X_i$ be a directed
limit of schemes over $S$ with affine transition morphisms.
Assume
\begin{enumerate}
\item $S$ quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item $X \to S$ separated.
\end{enumerate}
Then $X_i \to S$ is separated for all $i$ large enough.
\end{lemma}

\begin{proof}
\uses{limits-lemma-limit-separated}

Let $0 \in I$. Note that $I$ is nonempty as the limit is directed.
As $X_0$ is quasi-compact we can find finitely many
affine opens $U_1, \ldots, U_n \subset S$ such that
$X_0 \to S$ maps into $U_1 \cup \ldots \cup U_n$.
Denote $h_i : X_i \to S$ the structure morphism.
It suffices to check that for some $i \geq 0$ the morphisms
$h_i^{-1}(U_j) \to U_j$ are separated for $j = 1, \ldots,  n$.
Since $S$ is quasi-separated the morphisms $U_j \to S$ are quasi-compact.
Hence $h_i^{-1}(U_j)$ is quasi-compact and quasi-separated.
In this way we reduce to the case $S$ affine. In this case we
have to show that $X_i$ is separated and we know that $X$ is separated.
Thus the lemma follows from Lemma \ref{limits-lemma-limit-separated}.
\end{proof}

\begin{lemma}[Eventually affine]
\label{limits-lemma-eventually-affine}
\source{stacks:09ZM}
\href{https://stacks.math.columbia.edu/tag/09ZM}{\texttt{Stacks tag 09ZM}}
\group{limits}

Let $S$ be a scheme. Let $X = \lim X_i$ be a directed limit of schemes
over $S$ with affine transition morphisms. Assume
\begin{enumerate}
\item $S$ quasi-compact and quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item $X \to S$ affine.
\end{enumerate}
Then $X_i \to S$ is affine for $i$ large enough.
\end{lemma}

\begin{proof}
\uses{limits-lemma-limit-affine}

Choose a finite affine open covering $S = \bigcup_{j = 1, \ldots, n} V_j$.
Denote $f : X \to S$ and $f_i : X_i \to S$ the structure morphisms.
For each $j$ the scheme $f^{-1}(V_j) = \lim_i f_i^{-1}(V_j)$
is affine (as a finite morphism is affine by definition). Hence by
Lemma \ref{limits-lemma-limit-affine} there exists an $i \in I$ such that
each $f_i^{-1}(V_j)$ is affine. In other words, $f_i : X_i \to S$ is
affine for $i$ large enough, see
Morphisms, Lemma \ref{morphisms-lemma-characterize-affine}.
\end{proof}

\begin{lemma}[Eventually finite]
\label{limits-lemma-eventually-finite}
\source{stacks:09ZN}
\href{https://stacks.math.columbia.edu/tag/09ZN}{\texttt{Stacks tag 09ZN}}
\group{limits}

Let $S$ be a scheme. Let $X = \lim X_i$ be a directed limit of schemes
over $S$ with affine transition morphisms. Assume
\begin{enumerate}
\item $S$ quasi-compact and quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item the transition morphisms $X_{i'} \to X_i$ are finite,
\item $X_i \to S$ locally of finite type
\item $X \to S$ integral.
\end{enumerate}
Then $X_i \to S$ is finite for $i$ large enough.
\end{lemma}

\begin{proof}
\uses{limits-lemma-eventually-affine}

By Lemma \ref{limits-lemma-eventually-affine}
we may assume $X_i \to S$ is affine for all $i$.
Choose a finite affine open covering $S = \bigcup_{j = 1, \ldots, n} V_j$.
Denote $f : X \to S$ and $f_i : X_i \to S$ the structure morphisms.
It suffices to show that there exists an $i$ such that
$f_i^{-1}(V_j)$ is finite over $V_j$ for $j = 1, \ldots, m$
(Morphisms, Lemma \ref{morphisms-lemma-finite-local}).
Namely, for $i' \geq i$ the composition $X_{i'} \to X_i \to S$
will be finite as a composition of finite morphisms
(Morphisms, Lemma \ref{morphisms-lemma-composition-finite}).
This reduces us to the affine case: Let $R$ be a ring and
$A = \colim A_i$ with $R \to A$ integral and $A_i \to A_{i'}$
finite for all $i \leq i'$. Moreover $R \to A_i$ is of finite type
for all $i$. Goal: Show that $A_i$ is finite over $R$ for some $i$.
To prove this choose an $i \in I$ and pick generators
$x_1, \ldots, x_m \in A_i$ of $A_i$ as an $R$-algebra.
Since $A$ is integral over $R$ we can find monic polynomials
$P_j \in R[T]$ such that $P_j(x_j) = 0$ in $A$.
Thus there exists an $i' \geq i$ such that $P_j(x_j) = 0$ in $A_{i'}$
for $j = 1, \ldots, m$. Then the image $A'_i$ of $A_i$ in $A_{i'}$
is finite over $R$ by
Algebra, Lemma \ref{algebra-lemma-characterize-finite-in-terms-of-integral}.
Since $A'_i \subset A_{i'}$ is finite too we conclude
that $A_{i'}$ is finite over $R$ by
Algebra, Lemma \ref{algebra-lemma-finite-transitive}.
\end{proof}

\begin{lemma}[Eventually closed immersion]
\label{limits-lemma-eventually-closed-immersion}
\source{stacks:0A0N}
\href{https://stacks.math.columbia.edu/tag/0A0N}{\texttt{Stacks tag 0A0N}}
\group{limits}

Let $S$ be a scheme. Let $X = \lim X_i$ be a directed limit of schemes
over $S$ with affine transition morphisms. Assume
\begin{enumerate}
\item $S$ quasi-compact and quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item the transition morphisms $X_{i'} \to X_i$ are closed immersions,
\item $X_i \to S$ locally of finite type
\item $X \to S$ a closed immersion.
\end{enumerate}
Then $X_i \to S$ is a closed immersion for $i$ large enough.
\end{lemma}

\begin{proof}
\uses{limits-lemma-eventually-affine}

By Lemma \ref{limits-lemma-eventually-affine}
we may assume $X_i \to S$ is affine for all $i$.
Choose a finite affine open covering $S = \bigcup_{j = 1, \ldots, n} V_j$.
Denote $f : X \to S$ and $f_i : X_i \to S$ the structure morphisms.
It suffices to show that there exists an $i$ such that
$f_i^{-1}(V_j)$ is a closed subscheme of $V_j$ for $j = 1, \ldots, m$
(Morphisms, Lemma \ref{morphisms-lemma-closed-immersion}).
This reduces us to the affine case: Let $R$ be a ring and
$A = \colim A_i$ with $R \to A$ surjective and $A_i \to A_{i'}$
surjective for all $i \leq i'$. Moreover $R \to A_i$ is of finite type
for all $i$. Goal: Show that $R \to A_i$ is surjective for some $i$.
To prove this choose an $i \in I$ and pick generators
$x_1, \ldots, x_m \in A_i$ of $A_i$ as an $R$-algebra.
Since $R \to A$ is surjective we can find
$r_j \in R$ such that $r_j$ maps to $x_j$ in $A$.
Thus there exists an $i' \geq i$ such that $r_j$ maps to the image
of $x_j$ in $A_{i'}$ for $j = 1, \ldots, m$. Since $A_i \to A_{i'}$
is surjective this implies that $R \to A_{i'}$ is surjective.
\end{proof}

\begin{lemma}[Eventually immersion]
\label{limits-lemma-eventually-immersion}
\source{stacks:0GIH}
\href{https://stacks.math.columbia.edu/tag/0GIH}{\texttt{Stacks tag 0GIH}}
\group{limits}

Let $S$ be a scheme. Let $X = \lim X_i$ be a directed limit of schemes
over $S$ with affine transition morphisms. Assume
\begin{enumerate}
\item $S$ quasi-separated,
\item $X_i$ quasi-compact and quasi-separated,
\item the transition morphisms $X_{i'} \to X_i$ are closed immersions,
\item $X_i \to S$ locally of finite type, and
\item $X \to S$ an immersion.
\end{enumerate}
Then $X_i \to S$ is an immersion for $i$ large enough.
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-opens, limits-lemma-eventually-closed-immersion}

Choose an open subscheme $U \subset S$ such that $X \to S$ factors
as a closed immersion $X \to U$ composed with the inclusion morphism
$U \to S$. Since $X$ is quasi-compact, we may shrink $U$ and assume
$U$ is quasi-compact. Denote $V_i \subset X_i$ the inverse image of $U$.
Since $V_i$ pulls back to $X$ we see that $V_i = X_i$ for all $i$
large enough by Lemma \ref{limits-lemma-descend-opens}. Thus we may
assume $X = \lim X_i$ in the category of schemes over $U$.
Then we see that $X_i \to U$ is a closed immersion for $i$
large enough by Lemma \ref{limits-lemma-eventually-closed-immersion}.
This proves the lemma.
\end{proof}

\section{Absolute Noetherian Approximation}
\label{limits-section-approximation}
A nice reference for this section is Appendix C of the article
by Thomason and Trobaugh \cite{TT}.
See Categories, Section \ref{categories-section-posets-limits}
for our conventions regarding directed systems.
We will use the existence result and properties of the limit
from Section \ref{limits-section-limits} without further mention.

\begin{lemma}[Quasi affine finite type over Z]
\label{limits-lemma-quasi-affine-finite-type-over-Z}
\source{stacks:01Z7}
\href{https://stacks.math.columbia.edu/tag/01Z7}{\texttt{Stacks tag 01Z7}}
\group{limits}

Let $W$ be a quasi-affine scheme of finite type over
$\mathbf{Z}$. Suppose $W \to \Spec(R)$ is an
open immersion into an affine scheme. There exists a
finite type $\mathbf{Z}$-algebra $A \subset R$
which induces an open immersion $W \to \Spec(A)$.
Moreover, $R$ is the directed colimit of such subalgebras.
\end{lemma}

\begin{proof}
Choose an affine open covering $W = \bigcup_{i = 1, \ldots, n} W_i$
such that each $W_i$ is a standard affine open in $\Spec(R)$.
In other words, if we write $W_i = \Spec(R_i)$
then $R_i = R_{f_i}$ for some $f_i \in R$.
Choose finitely many $x_{ij} \in R_i$ which generate
$R_i$ over $\mathbf{Z}$.
Pick an $N \gg 0$ such that each $f_i^Nx_{ij}$ comes from an
element of $R$, say $y_{ij} \in R$.
Set $A$ equal to the $\mathbf{Z}$-algebra generated by
the $f_i$ and the $y_{ij}$ and (optionally) finitely many
additional elements of $R$. Then $A$ works. Details omitted.
\end{proof}

\begin{lemma}[Diagram]
\label{limits-lemma-diagram}
\source{stacks:01Z9}
\href{https://stacks.math.columbia.edu/tag/01Z9}{\texttt{Stacks tag 01Z9}}
\group{limits}

Suppose given a cartesian diagram of rings
$$
\begin{array}{cc}B \underset{s}{\longrightarrow} & R \\ B'\uparrow\longrightarrow & R' \underset{t}{\uparrow}\end{array}
$$
Let $W' \subset \Spec(R')$ be an open of
the form $W' = D(f_1) \cup \ldots \cup D(f_n)$
such that $t(f_i) = s(g_i)$ for some $g_i \in B$
and $B_{g_i} \cong R_{s(g_i)}$. Then $B' \to R'$
induces an open immersion of $W'$ into $\Spec(B')$.
\end{lemma}

\begin{proof}
Set $h_i = (g_i, f_i) \in B'$. More on Algebra,
Lemma \ref{more-algebra-lemma-diagram-localize} shows that
$(B')_{h_i} \cong (R')_{f_i}$ as desired.
\end{proof}

The following lemma is a precise statement of Noetherian
approximation.

\begin{lemma}[Approximate]
\label{limits-lemma-approximate}
\source{stacks:07RN}
\href{https://stacks.math.columbia.edu/tag/07RN}{\texttt{Stacks tag 07RN}}
\group{limits}

Let $S$ be a quasi-compact and quasi-separated scheme. Let $V \subset S$
be a quasi-compact open. Let $I$ be a directed set
and let $(V_i, f_{ii'})$ be an inverse system of schemes over $I$
with affine transition maps, with each $V_i$ of finite type over $\mathbf{Z}$,
and with $V = \lim V_i$. Then there exist
\begin{enumerate}
\item a directed set $J$,
\item an inverse system of schemes $(S_j, g_{jj'})$ over $J$,
\item an order preserving map $\alpha : J \to I$,
\item open subschemes $V'_j \subset S_j$, and
\item isomorphisms $V'_j \to V_{\alpha(j)}$
\end{enumerate}
such that
\begin{enumerate}
\item the transition morphisms $g_{jj'} : S_j \to S_{j'}$ are affine,
\item each $S_j$ is of finite type over $\mathbf{Z}$,
\item $g_{jj'}^{-1}(V'_{j'}) = V'_j$,
\item $S = \lim S_j$ and $V = \lim V'_j$, and
\item the diagrams
$$
\vcenter{
\begin{array}{cc}V \downarrow\searrow &  \\ V'_j \longrightarrow & V_{\alpha(j)}\end{array}
}
\quad\text{and}\quad
\vcenter{
\begin{array}{cc}V'_j \longrightarrow\downarrow & V_{\alpha(j)} \downarrow \\ V'_{j'} \longrightarrow & V_{\alpha(j')}\end{array}
}
$$
are commutative.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-opens, limits-lemma-limit-quasi-affine, limits-lemma-descend-section, limits-lemma-diagram, limits-lemma-quasi-affine-finite-type-over-Z}

Set $Z = S \setminus V$. Choose affine opens $U_1, \ldots, U_m \subset S$
such that $Z \subset \bigcup_{l = 1, \ldots, m} U_l$. Consider the opens
$$
V \subset V \cup U_1 \subset V \cup U_1 \cup U_2 \subset
\ldots \subset V \cup \bigcup\nolimits_{l = 1, \ldots, m} U_l = S
$$
If we can prove the lemma successively for each of the cases
$$
V \cup U_1 \cup \ldots \cup U_l
\subset
V \cup U_1 \cup \ldots \cup U_{l + 1}
$$
then the lemma will follow for $V \subset S$. In each case we are adding
one affine open. Thus we may assume
\begin{enumerate}
\item $S = U \cup V$,
\item $U$ affine open in $S$,
\item $V$ quasi-compact open in $S$, and
\item $V = \lim_i V_i$ with $(V_i, f_{ii'})$
an inverse system over a directed set $I$, each $f_{ii'}$
affine and each $V_i$ of finite type over $\mathbf{Z}$.
\end{enumerate}
Denote $f_i : V \to V_i$ the projections.
Set $W = U \cap V$. As $S$ is quasi-separated, this is a quasi-compact open
of $V$. By Lemma \ref{limits-lemma-descend-opens}
(and after shrinking $I$) we may assume that there exist
opens $W_i \subset V_i$ such that $f_{ii'}^{-1}(W_{i'}) = W_i$
and such that $f_i^{-1}(W_i) = W$. Since $W$ is a quasi-compact open
of $U$ it is quasi-affine. Hence we may assume (after shrinking $I$ again)
that $W_i$ is quasi-affine for all $i$, see
Lemma \ref{limits-lemma-limit-quasi-affine}.

\medskip\noindent
Write $U = \Spec(B)$. Set $R = \Gamma(W, \mathcal{O}_W)$,
and $R_i = \Gamma(W_i, \mathcal{O}_{W_i})$.
By Lemma \ref{limits-lemma-descend-section} we have $R = \colim_i R_i$.
Now we have the maps of rings
$$
\begin{array}{cc}B \underset{s}{\longrightarrow} & R \\  & R_i \underset{t_i}{\uparrow}\end{array}
$$
We set $B_i = \{(b, r) \in B \times R_i \mid s(b) = t_i(r)\}$ so that we
have a cartesian diagram
$$
\begin{array}{cc}B \underset{s}{\longrightarrow} & R \\ B_i \uparrow\longrightarrow & R_i \underset{t_i}{\uparrow}\end{array}
$$
for each $i$. The transition maps $R_i \to R_{i'}$ induce maps
$B_i \to B_{i'}$. It is clear that $B = \colim_i B_i$.
In the next paragraph we show that for all sufficiently large $i$
the composition $W_i \to \Spec(R_i) \to \Spec(B_i)$ is an open immersion.

\medskip\noindent
As $W$ is a quasi-compact open of $U = \Spec(B)$
we can find a finitely many elements $g_l \in B$, $l = 1, \ldots, m$
such that $D(g_l) \subset W$ and such that
$W = \bigcup_{l = 1, \ldots, m} D(g_l)$.
Note that this implies $D(g_l) = W_{s(g_l)}$ as open subsets of $U$,
where $W_{s(g_l)}$ denotes the largest open subset of $W$ on which
$s(g_l)$ is invertible. Hence
$$
B_{g_l} =
\Gamma(D(g_l), \mathcal{O}_U) =
\Gamma(W_{s(g_l)}, \mathcal{O}_W) = R_{s(g_l)},
$$
where the last equality is
Properties, Lemma \ref{properties-lemma-invert-f-sections}.
Since $W_{s(g_l)}$ is affine this also
implies that $D(s(g_l)) = W_{s(g_l)}$ as open subsets of $\Spec(R)$.
Since $R = \colim_i R_i$ we can (after shrinking $I$)
assume there exist $g_{l, i} \in R_i$ for all $i \in I$ such that
$s(g_l) = t_i(g_{l, i})$. Of course we choose the $g_{l, i}$
such that $g_{l, i}$ maps to $g_{l, i'}$ under the transition maps
$R_i \to R_{i'}$. Then, by Lemma \ref{limits-lemma-descend-opens} we can
(after shrinking $I$ again)
assume the corresponding opens $D(g_{l, i}) \subset \Spec(R_i)$
are contained in $W_i$ for $l = 1, \ldots, m$ and cover $W_i$.
We conclude that the morphism $W_i \to \Spec(R_i) \to \Spec(B_i)$
is an open immersion, see Lemma \ref{limits-lemma-diagram}.

\medskip\noindent
By Lemma \ref{limits-lemma-quasi-affine-finite-type-over-Z}
we can write $B_i$ as a directed colimit of subalgebras
$A_{i, p} \subset B_i$, $p \in P_i$ each
of finite type over $\mathbf{Z}$ and such that $W_i$ is
identified with an open subscheme of $\Spec(A_{i, p})$.
Let $S_{i, p}$ be the scheme obtained by glueing
$V_i$ and $\Spec(A_{i, p})$ along the open $W_i$, see
Schemes, Section \ref{schemes-section-glueing-schemes}.
Here is the resulting commutative diagram of schemes:
$$
\begin{array}{cccc} &  & V \swarrow\downarrow & W \longleftarrow\swarrow\downarrow \\ V_i \downarrow & W_i \longleftarrow\downarrow & S \swarrow & U \swarrow\longleftarrow \\ S_{i, p} & \Spec(A_{i, p}) \longleftarrow &  & \end{array}
$$
The morphism $S \to S_{i, p}$ arises because the upper right
square is a pushout in the category of schemes.
Note that $S_{i, p}$ is of finite type over $\mathbf{Z}$ since
it has a finite affine open covering whose members are
spectra of finite type $\mathbf{Z}$-algebras.
We define a preorder on $J = \coprod_{i \in I} P_i$
by the rule $(i', p') \geq (i, p)$ if and only if
$i' \geq i$ and the map $B_i \to B_{i'}$ maps $A_{i, p}$ into
$A_{i', p'}$. This is exactly the condition needed to
define a morphism $S_{i', p'} \to S_{i, p}$: namely make a commutative
diagram as above using the transition morphisms $V_{i'} \to V_i$
and $W_{i'} \to W_i$ and
the morphism $\Spec(A_{i', p'}) \to \Spec(A_{i, p})$ induced
by the ring map $A_{i, p} \to A_{i', p'}$. The relevant commutativities
have been built into the constructions.
We claim that $S$ is the directed limit of the schemes $S_{i, p}$.
Since by construction the schemes $V_i$ have limit $V$ this boils
down to the fact that $B$ is the limit of the rings $A_{i, p}$
which is true by construction. The map $\alpha : J \to I$ is given
by the rule $j = (i, p) \mapsto i$. The open subscheme $V'_j$ is
just the image of $V_i \to S_{i, p}$ above. The commutativity of
the diagrams in (5) is clear from the construction.
This finishes the proof of the lemma.
\end{proof}

\begin{proposition}[Approximate]
\label{limits-proposition-approximate}
