\begin{lemma}[Descend finite locally free]
\label{limits-lemma-descend-finite-locally-free}
\source{stacks:06AC}
\href{https://stacks.math.columbia.edu/tag/06AC}{\texttt{Stacks tag 06AC}}
\group{limits}

\uses{limits-situation-descent-property}
Notation and assumptions as in Situation \ref{limits-situation-descent-property}.
If
\begin{enumerate}
\item $f$ is finite locally free (of degree $d$),
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is finite locally free (of degree $d$) for some $i \geq 0$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-flat-finite-presentation, limits-lemma-descend-finite-finite-presentation, limits-lemma-limit-contained-in-constructible}

By
Lemmas \ref{limits-lemma-descend-flat-finite-presentation} and
\ref{limits-lemma-descend-finite-finite-presentation}
we find an $i$ such that $f_i$ is flat and finite.
On the other hand, $f_i$ is locally of finite presentation.
Hence $f_i$ is finite locally free by
Morphisms, Lemma \ref{morphisms-lemma-finite-flat}.
If moreover $f$ is finite locally free of degree $d$,
then the image of $Y \to Y_i$ is contained in the
open and closed locus $W_d \subset Y_i$ over which $f_i$ has degree
$d$. By
Lemma \ref{limits-lemma-limit-contained-in-constructible}
we see that for some $i' \geq i$ the image of $Y_{i'} \to Y_i$
is contained in $W_d$.
Then $f_{i'}$ will be finite locally free of degree $d$.
\end{proof}

