\begin{lemma}[Descend open immersion]
\label{limits-lemma-descend-open-immersion}
\source{stacks:0EUU}
\href{https://stacks.math.columbia.edu/tag/0EUU}{\texttt{Stacks tag 0EUU}}
\group{limits}

\uses{limits-situation-descent-property}
Notation and assumptions as in Situation \ref{limits-situation-descent-property}.
If
\begin{enumerate}
\item $f$ is an open immersion, and
\item $f_0$ is locally of finite presentation,
\end{enumerate}
then $f_i$ is an open immersion for some $i \geq 0$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-etale, limits-lemma-descend-isomorphism}

By Lemma \ref{limits-lemma-descend-etale} we can find an $i$ such that $f_i$
is \'etale. Then $V_i = f_i(X_i)$ is a quasi-compact open subscheme
of $Y_i$ (Morphisms, Lemma \ref{morphisms-lemma-etale-open}).
let $V$ and $V_{i'}$ for $i' \geq i$ be the inverse image of $V_i$
in $Y$ and $Y_{i'}$. Then $f : X \to V$ is an isomorphism
(namely it is a surjective open immersion). Hence by
Lemma \ref{limits-lemma-descend-isomorphism} we see that
$X_{i'} \to V_{i'}$ is an isomorphism
for some $i' \geq i$ as desired.
\end{proof}

\begin{lemma}[Descend immersion]
\label{limits-lemma-descend-immersion}
\source{stacks:0GTB}
\href{https://stacks.math.columbia.edu/tag/0GTB}{\texttt{Stacks tag 0GTB}}
\group{limits}

\uses{limits-situation-descent-property}
Notation and assumptions as in Situation \ref{limits-situation-descent-property}.
If
\begin{enumerate}
\item $f$ is an immersion, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is an immersion for some $i \geq 0$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-opens, limits-lemma-descend-closed-immersion-finite-presentation}

There exists an open $V \subset Y$ such that the morphism
$f$ factors as $X \to V \to Y$ and such that $X \to V$ is
a closed immersion, see discussion in
Schemes, Section \ref{schemes-section-immersions}.
Since $X$ is quasi-compact, we may and do assume $V$ is a quasi-compact open
of $Y$. By Lemma \ref{limits-lemma-descend-opens} after increasing $0$
we can find a quasi-compact open $V_0 \subset Y_0$ such that
$V$ is the inverse image of $V_0$. Then the inverse image of
$V_0$ in $X_0$ is a quasi-compact open whose inverse image in $X$ is $X$.
Hence by the same lemma applied to $X = \lim X_i$ we may
assume after increasing $0$ that we have the factorization
$X_0 \to V_0 \to Y_0$. Then for large enough $i \geq 0$ the morphism
$X_i \to V_i$ where $V_i = Y_i \times_{Y_0} V_0$ is a closed immersion by
Lemma \ref{limits-lemma-descend-closed-immersion-finite-presentation}
and the proof is complete.
\end{proof}

\begin{lemma}[Descend monomorphism]
\label{limits-lemma-descend-monomorphism}
\source{stacks:07RQ}
\href{https://stacks.math.columbia.edu/tag/07RQ}{\texttt{Stacks tag 07RQ}}
\group{limits}

\uses{limits-situation-descent-property}
Notation and assumptions as in Situation \ref{limits-situation-descent-property}.
If
\begin{enumerate}
\item $f$ is a monomorphism, and
\item $f_0$ is locally of finite type,
\end{enumerate}
then $f_i$ is a monomorphism for some $i \geq 0$.
\end{lemma}

\begin{proof}
\uses{limits-lemma-descend-isomorphism}

Recall that a morphism of schemes $V \to W$ is a monomorphism if and
only if the diagonal $V \to V \times_W V$ is an isomorphism
(Schemes, Lemma \ref{schemes-lemma-monomorphism}).
The morphism $X_0 \to X_0 \times_{Y_0} X_0$ is locally of finite
presentation by
Morphisms, Lemma \ref{morphisms-lemma-diagonal-morphism-finite-type}.
Since $X_0 \times_{Y_0} X_0$ is quasi-compact and quasi-separated
(Schemes, Remark \ref{schemes-remark-quasi-compact-and-quasi-separated})
we conclude from
Lemma \ref{limits-lemma-descend-isomorphism}
that $\Delta_i : X_i \to X_i \times_{Y_i} X_i$ is an isomorphism for
some $i \geq 0$. For this $i$ the morphism $f_i$ is a monomorphism.
\end{proof}

