\begin{lemma}[Geometrically connected if connected and point]
\label{varieties-lemma-geometrically-connected-if-connected-and-point}
\source{stacks:04KV}
\href{https://stacks.math.columbia.edu/tag/04KV}{\texttt{Stacks tag 04KV}}
\group{varieties}

Let $k$ be a field. Let $X$ be a scheme over $k$.
Assume $X$ is connected and has a point $x$ such that
$k$ is algebraically closed in $\kappa(x)$.
Then $X$ is geometrically connected.
In particular, if $X$ has a $k$-rational point and $X$ is connected,
then $X$ is geometrically connected.
\end{lemma}

\begin{proof}
\uses{varieties-lemma-geometrically-connected-criterion, varieties-lemma-characterize-geometrically-connected}

